import type { ComponentKind, WorkspaceArtifactV1, WorkspaceNodeV1, WorkspaceWireV1 } from '../domain/workspace.ts';
import { createGraphPlan } from './graph.ts';
import { muxSelectCount } from './logic.ts';

function gateExpression(component: ComponentKind, inputs: readonly string[]): string {
  const value = (index: number) => inputs[index] ?? '?';
  const joined = (operator: string) => `(${inputs.map(input => input || '?').join(` ${operator} `)})`;
  switch (component) {
    case 'SWITCH':
    case 'BUTTON':
      return '?';
    case 'CONSTANT_0':
      return '0';
    case 'CONSTANT_1':
      return '1';
    case 'PROBE':
    case 'LED':
    case 'BUFFER':
      return value(0);
    case 'NOT':
      return `¬(${value(0)})`;
    case 'AND':
      return joined('·');
    case 'NAND':
      return `¬${joined('·')}`;
    case 'OR':
      return joined('+');
    case 'NOR':
      return `¬${joined('+')}`;
    case 'XOR':
    case 'ODD_PARITY':
      return joined('⊕');
    case 'XNOR':
    case 'EVEN_PARITY':
      return `¬${joined('⊕')}`;
    /* المازجُ يُفكَّك إلى مجموع حواصلَ كما في الكتاب: لكل مدخلِ بيانات
       حدٌّ يضربه صغرى محدِّداته. عامٌّ في السعة — كتابةُ 2:1 حرفياً كانت
       تنتج تعبيراً كاذباً لـ4:1 و8:1. */
    case 'MUX': {
      const selectCount = muxSelectCount(inputs.length);
      const dataCount = 2 ** selectCount;
      const terms = Array.from({ length: dataCount }, (_, dataIndex) => {
        const selectLiterals = Array.from({ length: selectCount }, (_, bit) => {
          const select = value(dataCount + bit);
          return (dataIndex >> bit) & 1 ? select : `¬(${select})`;
        });
        return `(${[...selectLiterals.reverse(), value(dataIndex)].join(' · ')})`;
      });
      return `(${terms.join(' + ')})`;
    }
    /* الأغلبيةُ بثلاثةٍ تُكتب مفكوكةً كما في الكتاب؛ وبخمسةٍ أو سبعةٍ
       يصير المفكوكُ عشراتِ الحدود فيُكتب بالدالّة — تعبيرٌ يُقرأ خيرٌ من
       تعبيرٍ صحيحٍ لا يُقرأ. */
    case 'MAJORITY':
      return inputs.length === 3
        ? `((${value(0)} · ${value(1)}) + (${value(0)} · ${value(2)}) + (${value(1)} · ${value(2)}))`
        : `MAJ(${inputs.map(input => input || '?').join(', ')})`;
  }
}

function inputExpressions(node: WorkspaceNodeV1, wires: readonly WorkspaceWireV1[], expressions: Readonly<Record<string, string>>): string[] {
  const byPort = new Map<number, WorkspaceWireV1[]>();
  for (const wire of wires) {
    const match = /^in-(\d+)$/.exec(wire.target.portId);
    if (!match) continue;
    const inputIndex = Number(match[1]);
    const candidates = byPort.get(inputIndex) ?? [];
    candidates.push(wire);
    byPort.set(inputIndex, candidates);
  }
  return Array.from({ length: node.inputCount }, (_, inputIndex) => {
    const candidates = byPort.get(inputIndex) ?? [];
    return candidates.length === 1 ? (expressions[candidates[0].source.nodeId] ?? '?') : '?';
  });
}

export function deriveExpressions(artifact: WorkspaceArtifactV1): Readonly<Record<string, string>> {
  const graphPlan = createGraphPlan(artifact);
  const nodeById = new Map(artifact.circuit.nodes.map(node => [node.id, node]));
  const expressions: Record<string, string> = {};
  for (const nodeId of graphPlan.orderedNodeIds) {
    const node = nodeById.get(nodeId);
    if (!node) continue;
    if (node.role === 'input') {
      expressions[node.id] = node.component === 'CONSTANT_0' ? '0' : node.component === 'CONSTANT_1' ? '1' : (node.label || node.id);
      continue;
    }
    expressions[node.id] = gateExpression(node.component, inputExpressions(node, graphPlan.incomingWires.get(node.id) ?? [], expressions));
  }
  for (const nodeId of graphPlan.cycleNodeIds) expressions[nodeId] = '?';
  return expressions;
}
