import { parseWorkspaceArtifact, parseWorkspaceArtifactJson } from './parse-workspace.ts';
import type { ParseWorkspaceResult } from './domain-issues.ts';

export function migrateWorkspaceArtifact(input: unknown): ParseWorkspaceResult {
  return parseWorkspaceArtifact(input);
}

export function migrateWorkspaceArtifactJson(jsonText: string): ParseWorkspaceResult {
  return parseWorkspaceArtifactJson(jsonText);
}
