import type { TruthTable } from '../kernel/truth-table.ts';

export interface TruthTableColumn { readonly id: string; readonly kind: 'input' | 'output'; readonly direction: 'ltr' }
export interface TruthTableViewModel { readonly columns: readonly TruthTableColumn[]; readonly rowCount: number; readonly table: TruthTable }

export function createTruthTableViewModel(table: TruthTable): TruthTableViewModel {
  return {
    columns: [
      ...table.inputNodeIds.map(id => ({ id, kind: 'input' as const, direction: 'ltr' as const })),
      ...table.outputNodeIds.map(id => ({ id, kind: 'output' as const, direction: 'ltr' as const }))
    ],
    rowCount: table.rows.length,
    table
  };
}
