import type { WorkspaceArtifactV1 } from '../domain/workspace.ts';
import type { LogicValue } from '../kernel/logic.ts';
import type { EvidenceSnapshot } from './evidence-projection.ts';

export interface SignalViewRow {
  readonly nodeId: string;
  readonly label: string;
  readonly role: WorkspaceArtifactV1['circuit']['nodes'][number]['role'];
  readonly value: LogicValue;
  readonly expression: string;
  readonly direction: 'ltr';
}

export function createSignalViewRows(artifact: WorkspaceArtifactV1, snapshot: EvidenceSnapshot): readonly SignalViewRow[] {
  return artifact.circuit.nodes.map(node => ({ nodeId: node.id, label: node.label || node.id, role: node.role, value: snapshot.values[node.id] ?? 'X', expression: snapshot.expressions[node.id] ?? '?', direction: 'ltr' }));
}
