import { cloneWorkspaceArtifactV1, type WorkspaceArtifactV1 } from '../domain/workspace.ts';
import { sha256 } from './checksum.ts';

export const SHARE_KIND = 'digital-garden-circuit-share' as const;

export interface ShareEnvelope {
  readonly kind: typeof SHARE_KIND;
  readonly version: 1;
  readonly checksum: string;
  readonly artifact: WorkspaceArtifactV1;
}

export async function createShareEnvelope(artifact: WorkspaceArtifactV1): Promise<ShareEnvelope> {
  const copy = cloneWorkspaceArtifactV1(artifact);
  return { kind: SHARE_KIND, version: 1, checksum: await sha256(copy), artifact: copy };
}
