/* ═══════════════════════════════════════════════════════════════
   render.ts — تصيير الرموز والأسلاك إلى SVG
   ═══════════════════════════════════════════════════════════════
   مُصيِّرٌ واحدٌ يخدم مساحةَ البناء **ومكتبةَ العناصر معاً**. سببُ
   التوحيد ليس اختصارَ كود: رمزُ البوابة في المكتبة يجب أن يكون هو
   نفسَه الذي يظهر على اللوحة، وإلا تعلّم الطالبُ شكلاً واختار غيرَه.
   (وهي علّةُ «رموزُ SVG حقيقية لا اختصاراتٌ حرفية» في قبول G6-R5.)

   قواعدُ الرسم الملزمة من G6-R5:
   • لا يُكتب نوعُ البوابة داخل شكلها — الشكلُ وحدَه يكفي.
   • دائرةُ النفي والمنافذُ الظاهرة جسمٌ هندسيٌّ واحدٌ متصل، والسلكُ
     ينتهي عند **مركز المنفذ الظاهر** لا عند حافّة الجسم.
   • خطُّ XOR/XNOR الإضافيّ منفصلٌ بوضوحٍ عن الجسم.
   • الأسلاك أفقيةٌ/عمودية فقط — بلا منحنياتٍ ولا ميول.
   ═══════════════════════════════════════════════════════════════ */

import {
  expectedRoleForComponent,
  type CircuitDocumentV1,
  type WorkspaceNodeV1,
  type WorkspaceWireV1
} from '../domain/workspace.ts';
import type { LogicValue } from '../kernel/logic.ts';
import { geometryForComponent, labelPoint } from '../editor/symbol-geometry.ts';
import { portGeometryForNode } from '../editor/port-geometry.ts';
import { pointsToSvgPath, routeWire } from '../editor/route-geometry.ts';

const SVG_NS = 'http://www.w3.org/2000/svg';

export function svgElement<K extends keyof SVGElementTagNameMap>(
  name: K,
  attributes: Record<string, string | number> = {}
): SVGElementTagNameMap[K] {
  const element = document.createElementNS(SVG_NS, name);
  for (const [key, value] of Object.entries(attributes)) element.setAttribute(key, String(value));
  return element;
}

/** صنفُ الحالة المنطقية — اللونُ لا يحمل المعنى وحدَه؛ القيمةُ مكتوبةٌ دائماً. */
export function logicClass(value: LogicValue | undefined): string {
  if (value === 1) return 'is-high';
  if (value === 0) return 'is-low';
  return 'is-unknown';
}

export function logicText(value: LogicValue | undefined): string {
  return value === undefined ? 'X' : String(value);
}

/* ── الرمز ───────────────────────────────────────────────────── */

export interface SymbolOptions {
  readonly showPorts: boolean;
  readonly label?: string;
  readonly labelPlacement?: 'top' | 'center' | 'bottom';
  readonly value?: LogicValue;
}

/**
 * الطبقةُ الحيّة: الأجزاءُ التي **يتغيّر شكلُها** بالقيمة لا لونُها فقط.
 * مصباحٌ يضيء · مفتاحٌ ينقلب ذراعُه · زرٌّ ينضغط. سببُها أنّ الطالب
 * يقرأ الحالةَ من الشكل قبل أن يقرأ الرقم — وهذا ما يجعل اللوحة
 * دائرةً تعمل لا مخطَّطاً ساكناً.
 *
 * تعمل بلا قيمة أيضاً (أيقونةُ المكتبة): الشكلُ عندئذٍ حالةُ الصفر،
 * فيتعرّف الطالبُ على العنصر قبل أن يضعه.
 */
function appendLiveLayer(group: SVGGElement, node: WorkspaceNodeV1, value: LogicValue | undefined): void {
  const on = value === 1;
  if (node.component === 'LED') {
    /* الحشوُ يتبع **شكلَ الزجاجة نفسِه** لا دائرةً تقاربها، والهالةُ خلفه.
       كلاهما قبل الحدّ في الترتيب فيبقى الحدُّ حادّاً فوق الضوء. */
    const glass = 'M 52 40 A 26 26 0 1 1 104 40 A 26 26 0 1 1 52 40 Z';
    if (on) group.prepend(svgElement('circle', { class: 'cx-lamp-glow', cx: 78, cy: 40, r: 40 }));
    group.prepend(svgElement('path', { class: 'cx-lamp', d: glass }));
    const digit = svgElement('text', { class: 'cx-lamp-text', x: 78, y: 40 });
    digit.textContent = logicText(value);
    group.appendChild(digit);
    return;
  }
  /* الذراعُ في يسار البطاقة والرقمُ في يمينها: لا يتراكبان، والحركةُ
     أفقيةٌ صريحةٌ تُقرأ حتى بلا لون. */
  if (node.component === 'SWITCH') {
    group.appendChild(svgElement('rect', { class: 'cx-track', x: 20, y: 21, width: 54, height: 22, rx: 11 }));
    group.appendChild(svgElement('circle', { class: 'cx-knob', cx: on ? 63 : 31, cy: 32, r: 9 }));
    return;
  }
  if (node.component === 'BUTTON') {
    group.appendChild(svgElement('circle', { class: 'cx-cap', cx: 47, cy: 32, r: 15 }));
  }
}

/**
 * مجموعةُ منفذ: نقطةٌ مرئيةٌ صغيرة + هدفُ إصابةٍ شفّافٌ واسع. الهدفُ
 * الواسعُ شرطُ التوصيل بالإصبع، والنقطةُ الصغيرة شرطُ ألّا يبدو الرسمُ
 * مرقَّطاً بدوائرَ كبيرة.
 */
function buildPort(portId: string, center: { x: number; y: number }, extraClass: string): SVGGElement {
  const group = svgElement('g', { class: `cx-port-group ${extraClass}`.trim(), 'data-port-id': portId });
  group.appendChild(svgElement('circle', { class: 'cx-port-hit', cx: center.x, cy: center.y, r: 15 }));
  group.appendChild(svgElement('circle', { class: 'cx-port', cx: center.x, cy: center.y, r: 4 }));
  return group;
}

/**
 * يبني مجموعةَ الرمز في إحداثيّاتها المحلّية (0,0 أعلى يسار الرمز).
 * المستدعي يضع `transform` ليضبط موضعَها على اللوحة.
 */
export function buildSymbol(node: WorkspaceNodeV1, options: SymbolOptions): SVGGElement {
  const geometry = geometryForComponent(node.component, node.inputCount);
  const group = svgElement('g', { class: 'cx-symbol' });

  /* الوجهُ المملوءُ أوّلاً فيبقى تحت كلِّ شيء: هو خلفيةُ الطرف لا زخرفةٌ
     فوقه، وحشوُه هو ما يقول حالتَه. */
  if (geometry.facePath) {
    group.appendChild(svgElement('path', { class: 'cx-face', d: geometry.facePath }));
  }
  /* الأرجلُ قبل الجسم: الجسمُ يعلوها فيبقى حدُّه متّصلاً بلا شرطةٍ
     ناتئةٍ داخله. */
  for (const path of geometry.leadPaths) {
    group.appendChild(svgElement('path', { class: 'cx-lead', d: path }));
  }
  for (const path of geometry.bodyPaths) {
    group.appendChild(svgElement('path', { class: 'cx-body', d: path }));
  }
  /* 🔴 تفصيلُ المصباح يُوسَم باسمه. القاعدةُ التي تقلب لونَ الشعيرة على
     زجاجةٍ مضيئةٍ كانت تُصيب **كلَّ** `.cx-detail` في عقدةٍ قيمتُها ١ —
     ومنها قوسُ XOR الإضافيّ، فيختفي القوسُ كلّما اشتغلت البوابة. نفسُ
     خطأِ `has-face`: قاعدةٌ تُنتقى **بالحالة** وتُصيب ما لم يُقصد. */
  const detailClass = node.component === 'LED' ? 'cx-detail cx-lamp-detail' : 'cx-detail';
  for (const path of geometry.detailPaths) {
    group.appendChild(svgElement('path', { class: detailClass, d: path }));
  }
  if (geometry.inversionBubble) {
    const { center, radius } = geometry.inversionBubble;
    group.appendChild(svgElement('circle', { class: 'cx-bubble', cx: center.x, cy: center.y, r: radius }));
  }

  /* الثابتان يعرضان قيمتهما داخل الجسم — وهي **قيمةٌ** لا اسمُ نوع،
     فلا تناقض قاعدةَ «لا نصَّ داخل الشكل». */
  if (node.component === 'CONSTANT_0' || node.component === 'CONSTANT_1') {
    const bit = node.component === 'CONSTANT_1' ? '1' : '0';
    const text = svgElement('text', { class: 'cx-const', x: geometry.width / 2, y: geometry.height / 2 });
    text.textContent = bit;
    group.appendChild(text);
  }

  /* أسماءُ الدبابيس واسمُ الكتلة — للكتل التوافقية وحدَها. بدونها كان
     المستطيلُ الأصمُّ يجعل التوصيلَ تخميناً. */
  if (geometry.blockTitle) {
    /* مركزُ **الجسم** لا مركزُ الرمز: مازجٌ بكِشحٍ سفليٍّ يجعل الاثنين
       مختلفين، وارتفاعُ الخرج هو مركزُ الجسم في الحالتين. */
    const title = svgElement('text', { class: 'cx-block-title', x: geometry.width / 2, y: geometry.outputPort.y });
    title.textContent = geometry.blockTitle;
    group.appendChild(title);
  }
  for (const [pinIndex, pinName] of (geometry.pinNames ?? []).entries()) {
    const port = geometry.inputPorts[pinIndex];
    if (!port) continue;
    /* الاسمُ **داخل** الجسم بجوار دبّوسه: خارجَه يصطدم بالأسلاك الداخلة.
       والفرزُ بحافّة الدخول لا بنصف العرض — محدِّدُ المازج عند x=45 كان
       يُحسب دبّوساً جانبياً فيُكتب اسمُه في غير موضعه. */
    const onLeftEdge = port.x <= 5;
    const pin = svgElement('text', {
      class: `cx-pin ${onLeftEdge ? 'cx-pin--start' : 'cx-pin--below'}`,
      x: onLeftEdge ? 26 : port.x,
      y: onLeftEdge ? port.y : geometry.outputPort.y * 2 - 14
    });
    pin.textContent = pinName;
    group.appendChild(pin);
  }

  appendLiveLayer(group, node, options.value);

  if (options.showPorts) {
    for (const [portIndex, port] of geometry.inputPorts.entries()) {
      group.appendChild(buildPort(`in-${portIndex}`, port, ''));
    }
    /* لا منفذَ خرجٍ لطرفٍ من دور `output`: المُحقِّق يرفضه مصدراً أصلاً،
       ورسمُه يدعو الطالبَ إلى سحبةٍ محكومٍ عليها بالفشل. */
    if (node.role !== 'output') {
      group.appendChild(buildPort('out', geometry.outputPort, 'cx-port-out'));
    }
  }

  if (options.label) {
    const anchor = labelPoint(geometry, options.labelPlacement ?? 'bottom');
    const text = svgElement('text', { class: 'cx-label', x: anchor.x, y: anchor.y });
    text.textContent = options.label;
    group.appendChild(text);
  }

  return group;
}

/** أيقونةُ المكتبة: الرمزُ نفسُه مقيساً داخل صندوقٍ صغير. */
export function buildSymbolIcon(component: WorkspaceNodeV1['component'], inputCount: number): SVGSVGElement {
  const geometry = geometryForComponent(component, inputCount);
  const svg = svgElement('svg', {
    class: 'cx-icon',
    viewBox: `0 0 ${geometry.width} ${geometry.height}`,
    'aria-hidden': 'true',
    focusable: 'false'
  });
  const node: WorkspaceNodeV1 = {
    id: 'icon', role: expectedRoleForComponent(component), component, label: '',
    labelPlacement: 'bottom', position: { x: 0, y: 0 }, inputCount
  };
  svg.appendChild(buildSymbol(node, { showPorts: false }));
  return svg;
}

/* ── العقدة على اللوحة ───────────────────────────────────────── */

export interface NodeRenderContext {
  readonly value: LogicValue | undefined;
  readonly selected: boolean;
  readonly interactive: boolean;
}

/**
 * 🔴 **هدفُ الإصابة — علّةُ «التحديد والتحريك صعبٌ جداً».**
 * جسمُ الرمز `fill:none` (رسمُ دائرةٍ لا بطاقةُ واجهة)، وشكلٌ بلا حشوٍ
 * **لا يستقبل النقرَ إلا على خطّه** — أي شريطٌ عرضُه بكسلان. فكان على
 * الطالب أن يصيب حافّةَ البوابة بالضبط ليمسكها. مستطيلٌ شفّافٌ يغطّي
 * الرمزَ كلَّه يحلّها، ويسبق البقيةَ في الترتيب فلا يحجب منفذاً.
 */
function buildHitArea(width: number, height: number): SVGRectElement {
  return svgElement('rect', { class: 'cx-node-hit', x: -6, y: -6, width: width + 12, height: height + 12 });
}

export function buildNode(node: WorkspaceNodeV1, context: NodeRenderContext): SVGGElement {
  const geometry = geometryForComponent(node.component, node.inputCount);
  const group = svgElement('g', {
    class: [
      'cx-node',
      `cx-role-${node.role}`,
      /* 🔴 «له وجهٌ مملوء» صنفٌ **على العقدة**، لا يُستنتج بالجوار في CSS.
         كان الاستنتاجُ بـ`~ .cx-face`، والوجهُ داخل `<g class="cx-symbol">`
         بينما رقمُ القيمة أخٌ للمجموعة نفسِها — فلا أخوّةَ بينهما وسقطت
         القاعدةُ صامتة: بقي الرقمُ بلون النصّ الأساسيّ، وهو فاتحٌ في
         الداكن فلم يُلحَظ، وأسودُ في النهاريّ فوق أخضرَ عميق. */
      geometry.facePath ? 'has-face' : '',
      logicClass(context.value),
      context.selected ? 'is-selected' : '',
      context.interactive ? 'is-interactive' : ''
    ].filter(Boolean).join(' '),
    transform: `translate(${node.position.x} ${node.position.y})`,
    'data-node-id': node.id
  });

  group.appendChild(buildHitArea(geometry.width, geometry.height));
  group.appendChild(buildSymbol(node, {
    showPorts: true,
    label: node.label,
    labelPlacement: node.labelPlacement,
    value: context.value
  }));

  /* المدخلاتُ والمخرجات تعرض قيمتها الحالية **داخل** جسمها — الطالبُ
     يتتبّع الإشارة على الرسم نفسِه لا في جدولٍ منفصل. وكانت في صندوقٍ
     صغيرٍ ملصَقٍ على الحافّة، وصندوقٌ فوق بطاقةٍ ملوّنةٍ طبقتان تتنازعان
     العينَ. المصباحُ مستثنى: قيمتُه مكتوبةٌ داخل زجاجته أصلاً، والثوابتُ
     تكتب قيمتها بنفسها. */
  const showsValue = (node.role === 'input' || node.role === 'output')
    && node.component !== 'LED' && node.component !== 'CONSTANT_0' && node.component !== 'CONSTANT_1';
  if (showsValue) {
    const text = svgElement('text', {
      class: 'cx-value-text',
      x: node.role === 'input' ? 94 : geometry.width / 2,
      y: geometry.height / 2
    });
    text.textContent = logicText(context.value);
    group.appendChild(text);
  }

  if (context.interactive) {
    group.setAttribute('tabindex', '0');
    group.setAttribute('role', 'button');
  }

  return group;
}

/* ── الأسلاك ─────────────────────────────────────────────────── */

/**
 * قيمةُ السلك قيمةُ **منفذ مصدره** — لا قيمةُ وجهته. الوجهةُ قد تكون
 * بوابةً لم تُحسب بعد، فأخذُ قيمتها يُلوّن السلكَ بنتيجةٍ لا يحملها.
 */
export function buildWire(
  document_: CircuitDocumentV1,
  wire: WorkspaceWireV1,
  sourceValue: LogicValue | undefined,
  selected: boolean
): SVGGElement {
  const route = routeWire(document_, wire);
  const path = pointsToSvgPath(route.points);
  const group = svgElement('g', {
    class: ['cx-wire', logicClass(sourceValue), selected ? 'is-selected' : ''].filter(Boolean).join(' '),
    'data-wire-id': wire.id
  });
  /* مسارٌ شفّافٌ سميكٌ تحت المسار المرئي: هدفُ إصابةٍ يصلح للإصبع
     بينما يبقى الخطُّ المرئيّ رفيعاً كخطّ دائرةٍ كهربائية. */
  group.appendChild(svgElement('path', { class: 'cx-wire-hit', d: path }));
  group.appendChild(svgElement('path', { class: 'cx-wire-line', d: path }));
  return group;
}

/** نقاطُ التقاء الأسلاك — نقطةٌ ممتلئة تفرّق التفرّعَ عن التقاطع العابر. */
export function buildJunctions(document_: CircuitDocumentV1): SVGGElement {
  const group = svgElement('g', { class: 'cx-junctions' });
  const counts = new Map<string, { x: number; y: number; count: number }>();
  for (const wire of document_.wires) {
    const source = document_.nodes.find(node => node.id === wire.source.nodeId);
    if (!source) continue;
    const { center } = portGeometryForNode(source).output;
    const key = `${center.x}:${center.y}`;
    const entry = counts.get(key) ?? { x: center.x, y: center.y, count: 0 };
    entry.count += 1;
    counts.set(key, entry);
  }
  for (const entry of counts.values()) {
    if (entry.count < 2) continue;
    group.appendChild(svgElement('circle', { class: 'cx-junction', cx: entry.x, cy: entry.y, r: 4 }));
  }
  return group;
}
