import { migrateWorkspaceArtifact } from '../domain/migrate-workspace.ts';
import { WORKSPACE_LAB_ID, type WorkspaceArtifactV1 } from '../domain/workspace.ts';
import { createExportEnvelope, type ArtifactExportEnvelope } from './import-export.ts';
import { verifySha256 } from './checksum.ts';

export interface KeyValueStorage {
  readonly length: number;
  key(index: number): string | null;
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

export type LocalLoadResult =
  | Readonly<{ ok: true; artifact: WorkspaceArtifactV1; source: 'primary' | 'backup' }>
  | Readonly<{ ok: false; reason: 'missing' | 'corrupted' }>;

export type LocalSaveResult = Readonly<{ ok: true }> | Readonly<{ ok: false; reason: 'quota-or-storage-failure'; error: unknown }>;

/* بادئةُ `garden_labs_` قاعدةٌ عامّة في الحديقة: تقدّمُ المختبرات مستقلٌّ
   عن تقدّم الدراسة، ويمكن مسحُه وحدَه بلا مساسٍ بعمل الطالب الآخر. */
const prefix = `garden_labs_${WORKSPACE_LAB_ID}`;
const primaryKey = `${prefix}:artifact`;
const backupKey = `${prefix}:backup`;
const stagingKey = `${prefix}:staging`;

async function decode(serialized: string | null): Promise<WorkspaceArtifactV1 | null> {
  if (!serialized) return null;
  try {
    const envelope = JSON.parse(serialized) as ArtifactExportEnvelope;
    if (!envelope.artifact || typeof envelope.checksum !== 'string' || !await verifySha256(envelope.artifact, envelope.checksum)) return null;
    const migration = migrateWorkspaceArtifact(envelope.artifact);
    return migration.ok ? migration.value : null;
  } catch { return null; }
}

export class LocalArtifactStore {
  private readonly storage: KeyValueStorage;
  private readonly now: () => string;
  constructor(storage: KeyValueStorage, now: () => string = () => new Date().toISOString()) { this.storage = storage; this.now = now; }

  async load(): Promise<LocalLoadResult> {
    const primary = await decode(this.storage.getItem(primaryKey));
    if (primary) return { ok: true, artifact: primary, source: 'primary' };
    const backup = await decode(this.storage.getItem(backupKey));
    if (backup) return { ok: true, artifact: backup, source: 'backup' };
    return { ok: false, reason: this.storage.getItem(primaryKey) || this.storage.getItem(backupKey) ? 'corrupted' : 'missing' };
  }

  async save(artifact: WorkspaceArtifactV1): Promise<LocalSaveResult> {
    try {
      const serialized = JSON.stringify(await createExportEnvelope(artifact, this.now()));
      this.storage.setItem(stagingKey, serialized);
      if (!await decode(this.storage.getItem(stagingKey))) throw new Error('Staged artifact failed checksum verification.');
      const current = this.storage.getItem(primaryKey);
      if (current) this.storage.setItem(backupKey, current);
      this.storage.setItem(primaryKey, serialized);
      this.storage.removeItem(stagingKey);
      return { ok: true };
    } catch (error) {
      try { this.storage.removeItem(stagingKey); } catch { /* best effort: primary is never removed */ }
      return { ok: false, reason: 'quota-or-storage-failure', error };
    }
  }

  reset(): void {
    this.storage.removeItem(primaryKey);
    this.storage.removeItem(backupKey);
    this.storage.removeItem(stagingKey);
  }
}

/* ── مسالكُ الحفظ المسمّاة ──────────────────────────────────────
   طلبُ فهد 08-05: «حفظٌ متعدّدٌ يسمّيه الطالب، مع بقاء الحفظ التلقائي
   لآخر جلسة». والتكلفةُ زهيدةٌ فعلاً: المظروفُ الواحد بضعةُ كيلوبايتات،
   واثنا عشرَ مسلكاً أقلُّ من ٢٪ من حصّة التخزين المحلّي المعتادة — لذلك
   لا داعيَ لضغطٍ ولا لمخزَنٍ آخر.

   ⚠️ والمسلكُ **لا يمسّ المفتاحَ الأساسيّ**: الحفظُ التلقائيُّ يبقى هو
   ما يُستأنف عند العودة، والمسالكُ نُسخٌ يستدعيها الطالبُ بنفسه. خلطُ
   الاثنين يجعل «احفظ باسم» يبتلع جلستَك الجارية. */
const slotIndexKey = `${prefix}:slots`;
const slotKey = (slotId: string): string => `${prefix}:slot:${slotId}`;

export const MAXIMUM_SLOTS = 12;
export const MAXIMUM_SLOT_NAME = 60;

export interface ArtifactSlot {
  readonly id: string;
  readonly name: string;
  readonly updatedAt: string;
  readonly presetId: string | null;
}

export type SlotSaveResult =
  | Readonly<{ ok: true; slot: ArtifactSlot }>
  | Readonly<{ ok: false; reason: 'quota-or-storage-failure' | 'limit-reached' | 'empty-name' }>;

function readIndex(storage: KeyValueStorage): ArtifactSlot[] {
  try {
    const parsed = JSON.parse(storage.getItem(slotIndexKey) ?? '[]') as unknown;
    if (!Array.isArray(parsed)) return [];
    return parsed.filter((entry): entry is ArtifactSlot =>
      !!entry && typeof entry === 'object'
      && typeof (entry as ArtifactSlot).id === 'string'
      && typeof (entry as ArtifactSlot).name === 'string'
      && typeof (entry as ArtifactSlot).updatedAt === 'string');
  } catch { return []; }
}

export class ArtifactSlotStore {
  private readonly storage: KeyValueStorage;
  private readonly now: () => string;
  constructor(storage: KeyValueStorage, now: () => string = () => new Date().toISOString()) {
    this.storage = storage;
    this.now = now;
  }

  /** الأحدثُ أوّلاً: آخرُ ما حفظه الطالبُ هو أوّلُ ما يبحث عنه. */
  list(): ArtifactSlot[] {
    return readIndex(this.storage).sort((left, right) => right.updatedAt.localeCompare(left.updatedAt));
  }

  async save(name: string, artifact: WorkspaceArtifactV1, slotId?: string): Promise<SlotSaveResult> {
    const trimmed = name.trim().slice(0, MAXIMUM_SLOT_NAME);
    if (!trimmed) return { ok: false, reason: 'empty-name' };
    const index = readIndex(this.storage);
    /* الاسمُ نفسُه يكتب فوق مسلكه: طالبٌ يحفظ «تجربتي» مرّتين يقصد
       تحديثَها لا مسلكين متطابقَي الاسم لا يفرّق بينهما. */
    const existing = index.find(slot => slot.id === slotId) ?? index.find(slot => slot.name === trimmed);
    if (!existing && index.length >= MAXIMUM_SLOTS) return { ok: false, reason: 'limit-reached' };
    const id = existing?.id ?? `s${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
    const slot: ArtifactSlot = {
      id, name: trimmed, updatedAt: this.now(),
      presetId: artifact.sourcePresetId ?? null
    };
    try {
      this.storage.setItem(slotKey(id), JSON.stringify(await createExportEnvelope(artifact, slot.updatedAt)));
      this.storage.setItem(slotIndexKey, JSON.stringify([...index.filter(entry => entry.id !== id), slot]));
      return { ok: true, slot };
    } catch (error) {
      /* المظروفُ قد يكون كُتب قبل الفهرس ⇒ يُنظَّف، وإلا بقي بايتاتٌ
         يتيمةٌ تستهلك الحصّةَ ولا يصل إليها أحد. */
      try { this.storage.removeItem(slotKey(id)); } catch { /* المحاولةُ الأخيرة */ }
      return { ok: false, reason: 'quota-or-storage-failure' };
    }
  }

  async load(slotId: string): Promise<WorkspaceArtifactV1 | null> {
    return decode(this.storage.getItem(slotKey(slotId)));
  }

  remove(slotId: string): void {
    this.storage.removeItem(slotKey(slotId));
    this.storage.setItem(slotIndexKey, JSON.stringify(readIndex(this.storage).filter(slot => slot.id !== slotId)));
  }

  rename(slotId: string, name: string): boolean {
    const trimmed = name.trim().slice(0, MAXIMUM_SLOT_NAME);
    if (!trimmed) return false;
    const index = readIndex(this.storage);
    if (!index.some(slot => slot.id === slotId)) return false;
    this.storage.setItem(slotIndexKey, JSON.stringify(index.map(slot => slot.id === slotId ? { ...slot, name: trimmed } : slot)));
    return true;
  }
}

export class DebouncedArtifactSaver {
  private timeout: ReturnType<typeof setTimeout> | null = null;
  private readonly store: LocalArtifactStore;
  private readonly delayMilliseconds: number;
  constructor(store: LocalArtifactStore, delayMilliseconds = 350) { this.store = store; this.delayMilliseconds = delayMilliseconds; }
  schedule(artifact: WorkspaceArtifactV1, onSaved?: (result: LocalSaveResult) => void): void {
    if (this.timeout) clearTimeout(this.timeout);
    this.timeout = setTimeout(async () => {
      this.timeout = null;
      onSaved?.(await this.store.save(artifact));
    }, this.delayMilliseconds);
  }
  cancel(): void { if (this.timeout) clearTimeout(this.timeout); this.timeout = null; }
}
