/* ═══════════════════════════════════════════════════════════════
   canvas-view.ts — مساحةُ البناء: التصيير والتنقّل والإيماءات
   ═══════════════════════════════════════════════════════════════
   مسؤوليّاتها ثلاث فقط: ترسم الوثيقة · تتنقّل فيها · تُبلّغ عن نيّة
   المستخدم. **لا تعدّل الوثيقة ولا تحسب منطقاً** — كلُّ تعديلٍ يخرج
   من هنا نيّةً ويعود أمراً مُحقَّقاً من `LabView`. هذا ما يجعل التراجع
   ممكناً أصلاً: لا مسارَ ثانياً يغيّر الحالة من تحت التاريخ.

   قراراتٌ من قبول G6-R5:
   • مساحةُ العمل 2200×1400 أكبرُ من الشاشة، وسحبُ الخلفية يحرّكها.
   • zoom بعجلة الفأرة وبإصبعين **مع تثبيت نقطة الارتساء**.
   • **المدخلاتُ تُشغَّل بالنقر عليها داخل مساحة البناء** لا من شريطٍ
     علويّ منفصل.

   قواعدُ الإيماءات في البناء الحرّ:
   • سحبُ الخلفية = تنقّل · **Shift+سحب الخلفية = تحديدٌ بمستطيل**.
   • سحبُ عنصرٍ محدَّدٍ يحرّك **كلَّ** المحدَّد، والالتزامُ أمرٌ واحد.
   • سحبةٌ بلا حركة = نقرة: على مفتاحٍ تُشغّله، وعلى الخلفية تُلغي
     التحديد. بلا هذا الفرق كان كلُّ تحريكٍ للوحة يمسح تحديدَ المستخدم.
   • السحبُ من منفذٍ إلى منفذ يوصّل، و`Esc` يلغي، والرفضُ **لا يغيّر
     الرسم** — يشرح فقط.
   ═══════════════════════════════════════════════════════════════ */

import type {
  ComponentKind,
  WireEndpointV1,
  WorkspaceArtifactV1,
  WorkspaceNodeV1,
  WorkspacePointV1,
  WorkspaceViewportV1
} from '../domain/workspace.ts';
import { WORKSPACE_LIMITS } from '../domain/workspace.ts';
import type { LogicValue } from '../kernel/logic.ts';
import { nodeBounds, portGeometryForNode } from '../editor/port-geometry.ts';
import { rectangleFromPoints, type SelectionRectangle, type SelectionState } from '../editor/selection-model.ts';
import { defaultInputCount } from './free-build/component-library.ts';
import { geometryForComponent } from '../editor/symbol-geometry.ts';
import { clampPan, clampZoom, panViewport, wheelZoomFactor, zoomAroundPoint } from '../editor/viewport-controller.ts';
import { buildJunctions, buildNode, buildSymbol, buildWire, svgElement } from './render.ts';

/**
 * خطوةُ المحاذاة **تساوي خطوةَ الشبكة المرسومة**. كانت الشبكةُ ٤٠ والوضعُ
 * ٢٠، فتستقرّ نصفُ العناصر بين الخطوط ⇒ «الخطوطُ المرسومة لا تتبعها
 * الآلة». شبكةٌ لا يقف عليها شيءٌ زخرفةٌ كاذبة.
 */
export const PLACEMENT_GRID = 40;

export type SelectionIntent =
  | Readonly<{ kind: 'node'; nodeId: string; additive: boolean }>
  | Readonly<{ kind: 'wire'; wireId: string; additive: boolean }>
  | Readonly<{ kind: 'rectangle'; rectangle: SelectionRectangle; additive: boolean }>
  | Readonly<{ kind: 'clear' }>;

export interface CanvasCallbacks {
  readonly onToggleInput: (nodeId: string) => void;
  readonly onSelect: (intent: SelectionIntent) => void;
  readonly onViewportChange: (viewport: WorkspaceViewportV1) => void;
  readonly onMoveNodes: (positions: Readonly<Record<string, WorkspacePointV1>>) => void;
  readonly onConnect: (source: WireEndpointV1, target: WireEndpointV1) => void;
  readonly onPlace: (point: WorkspacePointV1) => void;
  readonly onRejectConnection: () => void;
}

type Gesture =
  | Readonly<{ kind: 'pan'; pointerId: number; startClient: WorkspacePointV1; startViewport: WorkspaceViewportV1 }>
  /* `nodeId` هو المضغوطُ فعلاً، و`origins` مجموعتُه. الفرقُ ليس ترفاً:
     نقرةٌ بلا حركةٍ تُشغّل **ما نُقر عليه** لا أوّلَ عضوٍ في المجموعة. */
  | Readonly<{ kind: 'drag'; pointerId: number; nodeId: string; startWorld: WorkspacePointV1; origins: ReadonlyMap<string, WorkspacePointV1> }>
  | Readonly<{ kind: 'wire'; pointerId: number; from: WireEndpointV1; fromPoint: WorkspacePointV1 }>
  | Readonly<{ kind: 'marquee'; pointerId: number; startWorld: WorkspacePointV1 }>;

export class CanvasView {
  readonly element: HTMLDivElement;
  private readonly surface: SVGSVGElement;
  private readonly scene: SVGGElement;
  private readonly overlay: SVGGElement;
  private readonly gridPattern: SVGPatternElement;
  private edgeTimeout: ReturnType<typeof setTimeout> | null = null;
  private readonly callbacks: CanvasCallbacks;
  private viewport: WorkspaceViewportV1 = { x: 0, y: 0, zoom: 1 };
  private gesture: Gesture | null = null;
  private moved = false;
  private pinchDistance = 0;
  private selection: SelectionState = { nodeIds: [], wireIds: [] };
  private nodes: readonly WorkspaceNodeV1[] = [];
  private armed: ComponentKind | null = null;

  constructor(callbacks: CanvasCallbacks) {
    this.callbacks = callbacks;

    this.element = document.createElement('div');
    this.element.className = 'cx-canvas';

    this.surface = svgElement('svg', { class: 'cx-surface', role: 'application' });
    this.surface.setAttribute('aria-label', 'Circuit workspace');

    /* شبكةُ قياسٍ من مستويين: خطٌّ كلَّ خطوةِ وضعٍ (٤٠) — فيقف عليه كلُّ
       عنصرٍ فعلاً — وخطٌّ أوضحُ كلَّ خمسِ خطوات ليقيس الطالبُ المسافات
       بالعين. الخطوةُ عريضةٌ عمداً: شبكةٌ كثيفةٌ تصير ضجيجاً تحت الرسم.
       ومستوياها في **بلاطةٍ واحدة**: نمطٌ داخل نمطٍ لا يقبل تحويلاً
       واحداً يحرّك الاثنين معاً. */
    const majorStep = PLACEMENT_GRID * 5;
    const defs = svgElement('defs');
    const grid = svgElement('pattern', {
      id: 'cx-grid', width: majorStep, height: majorStep, patternUnits: 'userSpaceOnUse'
    });
    const minorLines = Array.from({ length: 4 }, (_, index) => {
      const offset = (index + 1) * PLACEMENT_GRID;
      return `M ${offset} 0 V ${majorStep} M 0 ${offset} H ${majorStep}`;
    }).join(' ');
    grid.appendChild(svgElement('path', { class: 'cx-grid-line', d: minorLines }));
    grid.appendChild(svgElement('path', {
      class: 'cx-grid-line cx-grid-line--major', d: `M 0 0 V ${majorStep} M 0 0 H ${majorStep}`
    }));
    defs.appendChild(grid);
    this.surface.appendChild(defs);
    this.gridPattern = grid;

    /* 🔴 **الشبكةُ خارج المشهد لا داخله** — علّةُ «التقريبُ يكشف خلفيةً
       فارغةً بلا خطوط». كانت مستطيلاً بحجم مساحة العمل يتحرّك معها،
       فكلُّ ما وقع خارج حدودها ظهر أبيضَ أصمّ؛ و«ملاءمة» تُخرج الرؤيةَ
       عن الحدّ كثيراً حين تكون الدائرةُ أصغرَ من الإطار. الآن مستطيلٌ
       يملأ **السطحَ** بلا تحويل، والنمطُ وحدَه يُزاح بالرؤية — فالخطوط
       في كل موضعٍ وكل تكبيرٍ ولا فراغَ في أي حال. */
    this.surface.appendChild(svgElement('rect', {
      class: 'cx-grid-bg', x: 0, y: 0, width: '100%', height: '100%', fill: 'url(#cx-grid)'
    }));

    this.scene = svgElement('g', { class: 'cx-scene' });
    /* طبقةُ المعاينة داخل المشهد لا فوقه: فتأخذ التحويلَ نفسَه وتُرسم
       بإحداثيّات العالم مباشرةً بلا حسابٍ موازٍ يتفرّق عن الرسم. */
    this.overlay = svgElement('g', { class: 'cx-overlay' });
    this.surface.appendChild(this.scene);
    this.element.appendChild(this.surface);

    this.bindPointer();
    this.bindWheel();
  }

  /* ── التصيير ──────────────────────────────────────────────── */

  render(
    artifact: WorkspaceArtifactV1,
    values: Readonly<Record<string, LogicValue>>,
    selection: SelectionState
  ): void {
    this.viewport = artifact.session.viewport;
    this.selection = selection;
    this.nodes = artifact.circuit.nodes;
    const selectedNodeIds = new Set(selection.nodeIds);
    const selectedWireIds = new Set(selection.wireIds);
    this.scene.replaceChildren();

    /* 🔴 حدُّ مساحة العمل **لا يُرسم إلا عند بلوغه** — طلبُ فهد 08-05.
       إطارٌ دائمُ الظهور يجعل «ملاءمة» تُظهر صندوقاً حول الفراغ فيبدو
       المختبرُ محبوساً في ورقةٍ صغيرة. الحدُّ خبرٌ لا زينة: يُقال حين
       يصطدم به المستخدمُ فعلاً، ويصمت بقيةَ الوقت. */
    this.scene.appendChild(svgElement('rect', {
      class: 'cx-grid-edge', x: 0, y: 0,
      width: WORKSPACE_LIMITS.width, height: WORKSPACE_LIMITS.height
    }));

    /* الأسلاك قبل العقد: تمرّ **تحت** الأجسام فلا يقطع خطٌّ رمزَ بوابة. */
    const wireLayer = svgElement('g', { class: 'cx-wires' });
    for (const wire of artifact.circuit.wires) {
      wireLayer.appendChild(buildWire(artifact.circuit, wire, values[wire.source.nodeId], selectedWireIds.has(wire.id)));
    }
    this.scene.appendChild(wireLayer);
    this.scene.appendChild(buildJunctions(artifact.circuit));

    const nodeLayer = svgElement('g', { class: 'cx-nodes' });
    for (const node of artifact.circuit.nodes) {
      const interactive = node.component === 'SWITCH' || node.component === 'BUTTON';
      nodeLayer.appendChild(buildNode(node, {
        value: values[node.id],
        selected: selectedNodeIds.has(node.id),
        interactive
      }));
    }
    this.scene.appendChild(nodeLayer);
    this.scene.appendChild(this.overlay);

    this.applyViewport();
  }

  /** العنصرُ المُهيَّأ للوضع: يغيّر المؤشّرَ ويُظهر شبحاً يتبعه. */
  setArmedComponent(component: ComponentKind | null): void {
    this.armed = component;
    this.element.classList.toggle('is-placing', component !== null);
    if (!component) this.clearOverlay();
  }

  /** إلغاءُ أي إيماءةٍ جارية — `Esc` والفقدُ المفاجئ للتركيز يمرّان هنا. */
  cancelGesture(): void {
    this.gesture = null;
    this.moved = false;
    this.clearOverlay();
    this.restoreDraggedNodes();
    this.element.classList.remove('is-panning');
  }

  private clearOverlay(): void {
    this.overlay.replaceChildren();
  }

  /**
   * الالتقاطُ تحسينٌ لا شرط: يرمي `NotFoundError` إن انتهى المؤشّرُ قبل
   * أن نطلبه (أو في حدثٍ مُصطنَع)، ورميةٌ هنا تُسقط الإيماءةَ كلَّها قبل
   * أن تبدأ.
   */
  private capturePointer(pointerId: number): void {
    try { this.element.setPointerCapture(pointerId); } catch { /* الإيماءةُ تمضي بلا التقاط */ }
  }

  /* ── التنقّل ──────────────────────────────────────────────── */

  private applyViewport(): void {
    const { x, y, zoom } = this.viewport;
    this.scene.setAttribute('transform', `translate(${-x * zoom} ${-y * zoom}) scale(${zoom})`);
    /* نفسُ التحويل حرفياً على النمط: أيُّ اختلافٍ يجعل الشبكةَ تنزلق
       تحت العناصر فتعود «خطوطاً وهميةً لا تتبعها الآلة». */
    this.gridPattern.setAttribute('patternTransform', `translate(${-x * zoom} ${-y * zoom}) scale(${zoom})`);
  }

  private commitViewport(viewport: WorkspaceViewportV1): void {
    const rect = this.element.getBoundingClientRect();
    this.viewport = rect.width > 0 ? clampPan(viewport, rect) : viewport;
    this.applyViewport();
    this.callbacks.onViewportChange(this.viewport);
  }

  /**
   * الحدُّ يظهر لحظةَ بلوغه ثم ينطفئ. مؤقّتٌ واحدٌ يُعاد ضبطُه: سحبٌ
   * متواصلٌ على الحافّة يبقيه ظاهراً بلا وميضٍ متقطّع.
   */
  private revealEdge(): void {
    this.element.classList.add('is-at-edge');
    if (this.edgeTimeout) clearTimeout(this.edgeTimeout);
    this.edgeTimeout = setTimeout(() => {
      this.edgeTimeout = null;
      this.element.classList.remove('is-at-edge');
    }, 900);
  }

  zoomBy(factor: number): void {
    const rect = this.element.getBoundingClientRect();
    const anchor = { x: rect.width / 2, y: rect.height / 2 };
    this.commitViewport(zoomAroundPoint(this.viewport, anchor, clampZoom(this.viewport.zoom * factor)));
  }

  /**
   * «Fit» يُلائم **الدائرة** لا مساحةَ العمل كاملة: مساحةُ العمل ثابتةٌ
   * 2200×1400 ومعظمُها فارغ، فملاءمتُها تُصغّر دائرةً صغيرةً إلى نقطة.
   * (هذا بالضبط عيبُ «الدائرة تسبح في فراغ» في نسخة الإنتاج المرفوضة.)
   */
  fitTo(artifact: WorkspaceArtifactV1): void {
    const rect = this.element.getBoundingClientRect();
    if (rect.width === 0 || rect.height === 0) return;
    const nodes = artifact.circuit.nodes;
    if (nodes.length === 0) {
      this.commitViewport({ x: 0, y: 0, zoom: 1 });
      return;
    }
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (const node of nodes) {
      const bounds = nodeBounds(node);
      minX = Math.min(minX, bounds.x);
      minY = Math.min(minY, bounds.y);
      maxX = Math.max(maxX, bounds.x + bounds.width);
      maxY = Math.max(maxY, bounds.y + bounds.height);
    }
    const padding = 40;
    const width = maxX - minX + padding * 2;
    const height = maxY - minY + padding * 2;
    const zoom = clampZoom(Math.min(rect.width / width, rect.height / height));
    /* التوسيطُ يُحسب بعد قصّ التكبير على حدوده، وإلا انزاح المركز عند
       دائرةٍ صغيرةٍ جداً يقصّ تكبيرُها عند 1.8. */
    const x = minX - padding - (rect.width / zoom - width) / 2;
    const y = minY - padding - (rect.height / zoom - height) / 2;
    this.commitViewport({ x, y, zoom });
  }

  /** مركزُ الرؤية بإحداثيّات العالم — موضعُ الوضع الافتراضيُّ للعناصر. */
  viewportCenter(): WorkspacePointV1 {
    const rect = this.element.getBoundingClientRect();
    return this.clientToWorld({ x: rect.width / 2, y: rect.height / 2 });
  }

  private clientToLocal(event: PointerEvent | WheelEvent): WorkspacePointV1 {
    const rect = this.element.getBoundingClientRect();
    return { x: event.clientX - rect.left, y: event.clientY - rect.top };
  }

  private clientToWorld(local: WorkspacePointV1): WorkspacePointV1 {
    return { x: local.x / this.viewport.zoom + this.viewport.x, y: local.y / this.viewport.zoom + this.viewport.y };
  }

  private eventWorld(event: PointerEvent): WorkspacePointV1 {
    return this.clientToWorld(this.clientToLocal(event));
  }

  private bindWheel(): void {
    this.element.addEventListener('wheel', event => {
      event.preventDefault();
      const anchor = this.clientToLocal(event);
      const factor = wheelZoomFactor(event.deltaY);
      this.commitViewport(zoomAroundPoint(this.viewport, anchor, clampZoom(this.viewport.zoom * factor)));
    }, { passive: false });
  }

  /* ── الإيماءات ────────────────────────────────────────────── */

  private bindPointer(): void {
    const touches = new Map<number, WorkspacePointV1>();

    this.element.addEventListener('pointerdown', event => {
      const target = event.target as Element;
      const portGroup = target.closest('[data-port-id]');
      const nodeGroup = target.closest('[data-node-id]');
      const wireGroup = target.closest('[data-wire-id]');
      const additive = event.shiftKey || event.ctrlKey || event.metaKey;

      /* وضعُ عنصرٍ مُهيَّأ يسبق كلَّ شيء: النقرةُ التالية موضعُه. */
      if (this.armed) {
        this.callbacks.onPlace(snapPoint(this.eventWorld(event)));
        return;
      }

      if (portGroup && nodeGroup) {
        this.capturePointer(event.pointerId);
        const nodeId = nodeGroup.getAttribute('data-node-id')!;
        const portId = portGroup.getAttribute('data-port-id')!;
        const node = this.nodes.find(candidate => candidate.id === nodeId);
        if (!node) return;
        const ports = portGeometryForNode(node);
        const center = portId === 'out'
          ? ports.output.center
          : ports.inputs[Number(portId.slice(3))]?.center ?? ports.output.center;
        this.gesture = {
          kind: 'wire', pointerId: event.pointerId,
          from: { nodeId, portId: portId as WireEndpointV1['portId'] },
          fromPoint: center
        };
        this.moved = false;
        this.drawWirePreview(center, center);
        return;
      }

      if (nodeGroup) {
        const nodeId = nodeGroup.getAttribute('data-node-id')!;
        const alreadySelected = this.selection.nodeIds.includes(nodeId);
        /* ⚠️ المجموعةُ تُلتقط **قبل** إبلاغ التحديد: الإبلاغُ يعيد التصيير
           فيكتب `this.selection` من جديد، وقراءتُها بعده تعطي عنصراً
           واحداً — فتتحرّك قطعةٌ من مجموعةٍ محدَّدةٍ وتبقى بقيّتُها. */
        const groupIds = alreadySelected && !additive ? [...this.selection.nodeIds] : [nodeId];
        const origins = new Map<string, WorkspacePointV1>();
        for (const id of groupIds) {
          const node = this.nodes.find(candidate => candidate.id === id);
          if (node) origins.set(id, node.position);
        }
        /* نقرةٌ على عضوٍ في مجموعةٍ محدَّدة **لا تُفكِّكها**: هي بدايةُ سحبٍ
           للمجموعة لا اختيارٌ جديد. */
        if (!alreadySelected || additive) this.callbacks.onSelect({ kind: 'node', nodeId, additive });
        this.capturePointer(event.pointerId);
        this.gesture = { kind: 'drag', pointerId: event.pointerId, nodeId, startWorld: this.eventWorld(event), origins };
        this.moved = false;
        return;
      }

      if (wireGroup) {
        this.callbacks.onSelect({ kind: 'wire', wireId: wireGroup.getAttribute('data-wire-id')!, additive });
        return;
      }

      touches.set(event.pointerId, { x: event.clientX, y: event.clientY });
      if (touches.size === 2) { this.gesture = null; this.pinchDistance = distanceOf(touches); return; }

      this.element.setPointerCapture(event.pointerId);
      this.moved = false;
      if (event.shiftKey) {
        this.gesture = { kind: 'marquee', pointerId: event.pointerId, startWorld: this.eventWorld(event) };
        return;
      }
      this.gesture = {
        kind: 'pan', pointerId: event.pointerId,
        startClient: { x: event.clientX, y: event.clientY },
        startViewport: this.viewport
      };
      this.element.classList.add('is-panning');
    });

    this.element.addEventListener('pointermove', event => {
      if (touches.has(event.pointerId)) touches.set(event.pointerId, { x: event.clientX, y: event.clientY });

      if (touches.size === 2 && this.pinchDistance > 0) {
        const current = distanceOf(touches);
        const anchor = this.clientToLocal(event);
        const factor = current / this.pinchDistance;
        this.pinchDistance = current;
        this.commitViewport(zoomAroundPoint(this.viewport, anchor, clampZoom(this.viewport.zoom * factor)));
        return;
      }

      if (this.armed) { this.drawGhost(snapPoint(this.eventWorld(event))); return; }

      const gesture = this.gesture;
      if (!gesture || gesture.pointerId !== event.pointerId) return;

      if (gesture.kind === 'pan') {
        const zoom = gesture.startViewport.zoom;
        const delta = {
          x: -(event.clientX - gesture.startClient.x) / zoom,
          y: -(event.clientY - gesture.startClient.y) / zoom
        };
        if (Math.abs(delta.x) > 1 || Math.abs(delta.y) > 1) this.moved = true;
        /* التنقّلُ يُقصّ **أثناء السحب** لا عند إفلاته: بلا هذا ينزلق
           المشهدُ إلى فراغٍ ثم يقفز عائداً عند الرفع. والإبلاغُ يُؤجَّل
           إلى الرفع — إبلاغٌ في كل حركةِ مؤشّرٍ يعيد التصيير ويُشغّل
           الحفظَ عشراتِ المرّات في سحبةٍ واحدة. */
        const requested = panViewport(gesture.startViewport, delta);
        const rect = this.element.getBoundingClientRect();
        const clamped = rect.width > 0 ? clampPan(requested, rect) : requested;
        if (clamped.x !== requested.x || clamped.y !== requested.y) this.revealEdge();
        this.viewport = clamped;
        this.applyViewport();
        return;
      }

      if (gesture.kind === 'drag') {
        const world = this.eventWorld(event);
        const delta = { x: world.x - gesture.startWorld.x, y: world.y - gesture.startWorld.y };
        if (Math.abs(delta.x) > 2 || Math.abs(delta.y) > 2) this.moved = true;
        /* المعاينةُ تُحرّك مجموعاتِ SVG مباشرةً بلا إعادة تصيير: إعادةُ
           بناء المشهد في كل حركةِ مؤشّرٍ تُسقط الإطارات وتقطع الالتقاط. */
        for (const [nodeId, origin] of gesture.origins) {
          const group = this.scene.querySelector(`[data-node-id="${cssEscape(nodeId)}"]`);
          if (!group) continue;
          const requested = { x: origin.x + delta.x, y: origin.y + delta.y };
          const next = clampNodePosition(this.nodes.find(node => node.id === nodeId)!, requested);
          /* عنصرٌ بلغ الحافّة فتوقّف: الحدُّ يُقال عندئذٍ، وإلا بدا العنصرُ
             عالقاً بلا سبب. */
          if (next.x !== requested.x || next.y !== requested.y) this.revealEdge();
          group.setAttribute('transform', `translate(${next.x} ${next.y})`);
        }
        return;
      }

      if (gesture.kind === 'wire') {
        this.moved = true;
        this.drawWirePreview(gesture.fromPoint, this.eventWorld(event));
        return;
      }

      this.moved = true;
      this.drawMarquee(rectangleFromPoints(gesture.startWorld, this.eventWorld(event)));
    });

    const endPointer = (event: PointerEvent) => {
      touches.delete(event.pointerId);
      if (touches.size < 2) this.pinchDistance = 0;
      const gesture = this.gesture;
      if (!gesture || gesture.pointerId !== event.pointerId) return;
      this.gesture = null;
      this.element.classList.remove('is-panning');

      if (gesture.kind === 'pan') {
        /* سحبٌ بلا حركةٍ فعلية = نقرةٌ على الخلفية ⇒ إلغاءُ التحديد. */
        if (!this.moved) this.callbacks.onSelect({ kind: 'clear' });
        this.callbacks.onViewportChange(this.viewport);
        return;
      }

      if (gesture.kind === 'drag') {
        if (!this.moved) {
          const group = this.scene.querySelector(`[data-node-id="${cssEscape(gesture.nodeId)}"]`);
          if (group?.classList.contains('is-interactive')) this.callbacks.onToggleInput(gesture.nodeId);
          return;
        }
        const world = this.eventWorld(event);
        const delta = { x: world.x - gesture.startWorld.x, y: world.y - gesture.startWorld.y };
        const positions: Record<string, WorkspacePointV1> = {};
        for (const [nodeId, origin] of gesture.origins) {
          positions[nodeId] = clampNodePosition(
            this.nodes.find(node => node.id === nodeId)!,
            snapPoint({ x: origin.x + delta.x, y: origin.y + delta.y })
          );
        }
        this.callbacks.onMoveNodes(positions);
        return;
      }

      if (gesture.kind === 'wire') {
        this.clearOverlay();
        const endpoint = this.endpointAt(event.clientX, event.clientY);
        if (!endpoint) { this.callbacks.onRejectConnection(); return; }
        const from = gesture.from;
        if (from.portId === 'out' && endpoint.portId !== 'out') this.callbacks.onConnect(from, endpoint);
        else if (from.portId !== 'out' && endpoint.portId === 'out') this.callbacks.onConnect(endpoint, from);
        else this.callbacks.onRejectConnection();
        return;
      }

      this.clearOverlay();
      this.callbacks.onSelect({
        kind: 'rectangle',
        rectangle: rectangleFromPoints(gesture.startWorld, this.eventWorld(event)),
        additive: event.shiftKey || event.ctrlKey || event.metaKey
      });
    };
    this.element.addEventListener('pointerup', endPointer);
    /* `pointercancel` ليس ترفاً: نظامُ التشغيل يسحب المؤشّر عند إيماءةٍ
       من حافّة الشاشة، فتبقى اللوحةُ عالقةً في وضع السحب بلا هذا السطر. */
    this.element.addEventListener('pointercancel', () => this.cancelGesture());
  }

  /** المنفذُ تحت نقطةٍ على الشاشة — الالتقاطُ يوجّه الأحداث ولا يمنع الفحص. */
  private endpointAt(clientX: number, clientY: number): WireEndpointV1 | null {
    const element = document.elementFromPoint(clientX, clientY);
    const portGroup = element?.closest('[data-port-id]');
    const nodeGroup = element?.closest('[data-node-id]');
    if (!portGroup || !nodeGroup) return null;
    return {
      nodeId: nodeGroup.getAttribute('data-node-id')!,
      portId: portGroup.getAttribute('data-port-id') as WireEndpointV1['portId']
    };
  }

  /** يُعيد العقدَ المسحوبةَ إلى مواضعها الحقيقية بعد إلغاءٍ. */
  private restoreDraggedNodes(): void {
    for (const node of this.nodes) {
      const group = this.scene.querySelector(`[data-node-id="${cssEscape(node.id)}"]`);
      group?.setAttribute('transform', `translate(${node.position.x} ${node.position.y})`);
    }
  }

  private drawWirePreview(from: WorkspacePointV1, to: WorkspacePointV1): void {
    /* المعاينةُ أورثوجونالية مثل السلك النهائيّ: خطٌّ مائلٌ يعِد بشكلٍ
       لن يظهر بعد الإفلات. */
    const middleX = (from.x + to.x) / 2;
    const path = `M ${from.x} ${from.y} H ${middleX} V ${to.y} H ${to.x}`;
    this.overlay.replaceChildren(
      svgElement('path', { class: 'cx-wire-preview', d: path }),
      svgElement('circle', { class: 'cx-wire-preview-dot', cx: to.x, cy: to.y, r: 5 })
    );
  }

  private drawMarquee(rectangle: SelectionRectangle): void {
    this.overlay.replaceChildren(svgElement('rect', {
      class: 'cx-marquee', x: rectangle.x, y: rectangle.y,
      width: rectangle.width, height: rectangle.height
    }));
  }

  private drawGhost(position: WorkspacePointV1): void {
    if (!this.armed) return;
    const inputCount = defaultInputCount(this.armed);
    const ghost = svgElement('g', { class: 'cx-ghost', transform: `translate(${position.x} ${position.y})` });
    ghost.appendChild(buildSymbol({
      id: 'ghost', role: 'gate', component: this.armed, label: '',
      labelPlacement: 'bottom', position, inputCount
    } as WorkspaceNodeV1, { showPorts: false }));
    this.overlay.replaceChildren(ghost);
  }
}

function snapPoint(point: WorkspacePointV1): WorkspacePointV1 {
  return {
    x: Math.round(point.x / PLACEMENT_GRID) * PLACEMENT_GRID,
    y: Math.round(point.y / PLACEMENT_GRID) * PLACEMENT_GRID
  };
}

/**
 * الموضعُ يُقصّ داخل مساحة العمل قبل أن يصير أمراً: خارجَها يرفضه
 * المُحقِّق بـ`OUT_OF_BOUNDS` فتضيع السحبةُ كلُّها بلا سببٍ مفهوم.
 */
function clampNodePosition(node: WorkspaceNodeV1, position: WorkspacePointV1): WorkspacePointV1 {
  const geometry = geometryForComponent(node.component, node.inputCount);
  return {
    x: Math.min(Math.max(0, position.x), WORKSPACE_LIMITS.width - geometry.width),
    y: Math.min(Math.max(0, position.y), WORKSPACE_LIMITS.height - geometry.height)
  };
}

function cssEscape(value: string): string {
  return value.replace(/["\\]/g, '\\$&');
}

function distanceOf(touches: ReadonlyMap<number, WorkspacePointV1>): number {
  const [first, second] = [...touches.values()];
  if (!first || !second) return 0;
  return Math.hypot(first.x - second.x, first.y - second.y);
}
