import { cloneWorkspaceArtifactV1, type WorkspaceArtifactV1, type WorkspaceNodeV1, type WorkspaceWireV1 } from '../domain/workspace.ts';
import { validateCommandPreflight, type CircuitCommand } from '../validator/validate-command.ts';
import { validateWorkspaceDocument } from '../validator/validate-document.ts';
import type { ValidationIssue } from '../validator/issues.ts';
import type { CommandMetadata } from './commands.ts';

export type CommandReductionResult =
  | Readonly<{ ok: true; artifact: WorkspaceArtifactV1 }>
  | Readonly<{ ok: false; artifact: WorkspaceArtifactV1; issues: readonly ValidationIssue[] }>;

function nextId(baseId: string, occupiedIds: Set<string>): string {
  let suffix = 1;
  let candidate = `${baseId}-copy`;
  while (occupiedIds.has(candidate)) {
    suffix += 1;
    candidate = `${baseId}-copy-${suffix}`;
  }
  occupiedIds.add(candidate);
  return candidate;
}

function duplicateSelection(artifact: WorkspaceArtifactV1, command: Extract<CircuitCommand, { type: 'node.duplicate-many' }>): WorkspaceArtifactV1 {
  const selectedIds = new Set(command.nodeIds);
  const occupiedNodeIds = new Set(artifact.circuit.nodes.map(node => node.id));
  const occupiedWireIds = new Set(artifact.circuit.wires.map(wire => wire.id));
  const idBySourceId = new Map<string, string>();
  const copies: WorkspaceNodeV1[] = [];
  for (const node of artifact.circuit.nodes.filter(candidate => selectedIds.has(candidate.id))) {
    const copyId = nextId(node.id, occupiedNodeIds);
    idBySourceId.set(node.id, copyId);
    copies.push({ ...node, id: copyId, position: { x: node.position.x + command.offset.x, y: node.position.y + command.offset.y } });
  }
  const wireCopies: WorkspaceWireV1[] = [];
  for (const wire of artifact.circuit.wires) {
    const sourceNodeId = idBySourceId.get(wire.source.nodeId);
    const targetNodeId = idBySourceId.get(wire.target.nodeId);
    if (!sourceNodeId || !targetNodeId) continue;
    wireCopies.push({
      ...wire,
      id: nextId(wire.id, occupiedWireIds),
      source: { ...wire.source, nodeId: sourceNodeId },
      target: { ...wire.target, nodeId: targetNodeId },
      route: {
        ...wire.route,
        waypoints: wire.route.waypoints.map(point => ({ x: point.x + command.offset.x, y: point.y + command.offset.y }))
      }
    });
  }
  const inputValues = { ...artifact.session.inputValues };
  for (const [sourceNodeId, copyNodeId] of idBySourceId) {
    const sourceValue = artifact.session.inputValues[sourceNodeId];
    if (sourceValue !== undefined) inputValues[copyNodeId] = sourceValue;
  }
  return {
    ...artifact,
    circuit: { ...artifact.circuit, nodes: [...artifact.circuit.nodes, ...copies], wires: [...artifact.circuit.wires, ...wireCopies] },
    session: { ...artifact.session, inputValues }
  };
}

function applyUnchecked(artifact: WorkspaceArtifactV1, command: CircuitCommand): WorkspaceArtifactV1 {
  switch (command.type) {
    case 'node.add':
      return { ...artifact, circuit: { ...artifact.circuit, nodes: [...artifact.circuit.nodes, command.node] } };
    case 'node.update':
      return { ...artifact, circuit: { ...artifact.circuit, nodes: artifact.circuit.nodes.map(node => node.id === command.nodeId ? { ...node, ...command.patch, id: node.id } : node) } };
    case 'node.move-many':
      return { ...artifact, circuit: { ...artifact.circuit, nodes: artifact.circuit.nodes.map(node => command.positions[node.id] ? { ...node, position: command.positions[node.id] } : node) } };
    case 'node.duplicate-many':
      return duplicateSelection(artifact, command);
    case 'node.delete-many': {
      const deletedNodeIds = new Set(command.nodeIds);
      const inputValues = Object.fromEntries(Object.entries(artifact.session.inputValues).filter(([nodeId]) => !deletedNodeIds.has(nodeId)));
      return {
        ...artifact,
        circuit: {
          ...artifact.circuit,
          nodes: artifact.circuit.nodes.filter(node => !deletedNodeIds.has(node.id)),
          wires: artifact.circuit.wires.filter(wire => !deletedNodeIds.has(wire.source.nodeId) && !deletedNodeIds.has(wire.target.nodeId))
        },
        session: { ...artifact.session, inputValues }
      };
    }
    case 'wire.connect':
      return { ...artifact, circuit: { ...artifact.circuit, wires: [...artifact.circuit.wires, command.wire] } };
    case 'wire.reconnect':
      return {
        ...artifact,
        circuit: {
          ...artifact.circuit,
          wires: artifact.circuit.wires.map(wire => wire.id === command.wireId
            ? { ...wire, ...(command.source ? { source: command.source } : {}), ...(command.target ? { target: command.target } : {}) }
            : wire)
        }
      };
    case 'wire.update':
      return { ...artifact, circuit: { ...artifact.circuit, wires: artifact.circuit.wires.map(wire => wire.id === command.wireId ? { ...wire, ...command.patch, id: wire.id } : wire) } };
    case 'wire.delete-many': {
      const deletedWireIds = new Set(command.wireIds);
      return { ...artifact, circuit: { ...artifact.circuit, wires: artifact.circuit.wires.filter(wire => !deletedWireIds.has(wire.id)) } };
    }
    case 'document.replace-import':
    case 'document.load-preset':
    case 'document.reset':
      return { ...cloneWorkspaceArtifactV1(command.artifact), artifactId: artifact.artifactId, createdAt: artifact.createdAt };
  }
}

export function reduceCircuitCommand(
  artifact: WorkspaceArtifactV1,
  command: CircuitCommand,
  metadata: CommandMetadata
): CommandReductionResult {
  const preflight = validateCommandPreflight(artifact, command);
  if (!preflight.valid) return { ok: false, artifact, issues: preflight.issues };
  const candidate = {
    ...applyUnchecked(artifact, command),
    revision: artifact.revision + 1,
    updatedAt: metadata.updatedAt
  } satisfies WorkspaceArtifactV1;
  const validation = validateWorkspaceDocument(candidate);
  const errors = validation.issues.filter(issue => issue.severity === 'error');
  if (errors.length > 0) return { ok: false, artifact, issues: errors };
  return { ok: true, artifact: cloneWorkspaceArtifactV1(candidate) };
}
