import type { ComponentKind, LabelPlacement } from '../domain/workspace.ts';
import { muxSelectCount } from '../kernel/logic.ts';

export interface LocalPoint {
  readonly x: number;
  readonly y: number;
}

export interface SymbolGeometry {
  readonly width: number;
  readonly height: number;
  readonly bodyPaths: readonly string[];
  readonly detailPaths: readonly string[];
  /**
   * 🔴 **أرجلُ الدبابيس** — علّةُ «النقطُ الداخلةُ والخارجةُ بعيدةٌ عن
   * العنصر». المنافذُ عند x=4 وx=116 بينما جسمُ البوابة يبدأ عند ٢٠
   * وينتهي عند ١٠٠، فكانت النقطةُ تطفو في فراغٍ بلا ما يصلها بالشكل.
   * كلُّ مخطَّطٍ في الكتاب يرسم رِجلاً قصيرةً بين الدبّوس والجسم؛
   * غيابُها هو ما جعل الرمزَ يبدو مفكَّكاً. (والأطرافُ لا أرجلَ لها:
   * منافذُها ملتصقةٌ بحافّة جسمها أصلاً.)
   */
  readonly leadPaths: readonly string[];
  /** جسمٌ مملوءٌ تحت الحدّ — للأطراف وحدَها، وحشوُه يقول الحالة. */
  readonly facePath?: string;
  readonly inputPorts: readonly LocalPoint[];
  readonly outputPort: LocalPoint;
  readonly inversionBubble?: Readonly<{ center: LocalPoint; radius: number }>;
  /** أسماءُ الدبابيس داخل الكتل التوافقية — لا تُرسم لغيرها. */
  readonly pinNames?: readonly string[];
  /** اسمُ الكتلة داخل جسمها (MUX/MAJ). استثناءٌ مقصودٌ من «لا نصَّ في
      الشكل»: شكلُ المستطيل لا يميّز كتلةً عن أخرى، فالاسمُ هو ما يميّزها. */
  readonly blockTitle?: string;
}

const symbolWidth = 120;
const symbolHeight = 80;
const leftPortX = 4;
const rightPortX = 116;
const bodyLeft = 20;
const bodyRight = 100;

function inputPortY(inputIndex: number, inputCount: number): number {
  if (inputCount <= 1) return symbolHeight / 2;
  return 16 + inputIndex * (48 / (inputCount - 1));
}

function ports(inputCount: number): LocalPoint[] {
  return Array.from({ length: inputCount }, (_, inputIndex) => ({ x: leftPortX, y: inputPortY(inputIndex, inputCount) }));
}

/** رِجلٌ أفقيةٌ من كل دبّوس دخلٍ إلى حافّة الجسم، ورِجلٌ للخرج. */
function leads(inputPorts: readonly LocalPoint[], attachX: number | ((y: number) => number), outputFrom: number, outputY: number): string[] {
  const attach = typeof attachX === 'function' ? attachX : () => attachX;
  return [
    ...inputPorts.map(port => `M ${port.x} ${port.y} H ${attach(port.y).toFixed(2)}`),
    `M ${outputFrom} ${outputY} H ${rightPortX}`
  ];
}

function rectangular(inputCount: number): SymbolGeometry {
  const inputPorts = ports(inputCount);
  return {
    width: symbolWidth,
    height: symbolHeight,
    bodyPaths: [`M ${bodyLeft} 8 H ${bodyRight} V 72 H ${bodyLeft} Z`],
    detailPaths: [],
    leadPaths: leads(inputPorts, bodyLeft, bodyRight, 40),
    inputPorts,
    outputPort: { x: rightPortX, y: 40 }
  };
}

/**
 * الطرف: بطاقةٌ مستديرةٌ **مملوءة**، ومنافذُها ملتصقةٌ بحافّتها فلا رِجلَ
 * لها. حشوُها هو ما يقول الحالةَ: الطالبُ يرى المدخلَ مضاءً من طرف
 * الشاشة بلا أن يلاحق نقطةً صغيرة. (والبواباتُ تبقى خطّيةً بلا حشو —
 * الفرقُ نفسُه مقصود: الأطرافُ حالةٌ والبواباتُ عملية.)
 */
function terminal(role: 'input' | 'output'): SymbolGeometry {
  const body = 'M 14 6 H 106 Q 116 6 116 16 V 48 Q 116 58 106 58 H 14 Q 4 58 4 48 V 16 Q 4 6 14 6 Z';
  return {
    width: symbolWidth,
    height: 64,
    bodyPaths: [body],
    detailPaths: [],
    leadPaths: [],
    facePath: body,
    inputPorts: role === 'input' ? [] : [{ x: 4, y: 32 }],
    outputPort: { x: 116, y: 32 }
  };
}

/** طرفُ الخرج بعد دائرة النفي إن وُجدت — الرِّجلُ تبدأ من بعدها لا تحتها. */
function outputAttach(bodyTip: number, inverted: boolean): number {
  return inverted ? 110 : bodyTip;
}

function triangle(inverted: boolean): SymbolGeometry {
  const bubble = inverted ? { center: { x: 104, y: 40 }, radius: 6 } : undefined;
  const inputPorts = [{ x: leftPortX, y: 40 }];
  return {
    width: symbolWidth,
    height: symbolHeight,
    bodyPaths: ['M 22 8 L 96 40 L 22 72 Z'],
    detailPaths: [],
    leadPaths: leads(inputPorts, 22, outputAttach(96, inverted), 40),
    inputPorts,
    outputPort: { x: rightPortX, y: 40 },
    ...(bubble ? { inversionBubble: bubble } : {})
  };
}

function andGate(inputCount: number, inverted: boolean): SymbolGeometry {
  const bubble = inverted ? { center: { x: 104, y: 40 }, radius: 6 } : undefined;
  const inputPorts = ports(inputCount);
  return {
    width: symbolWidth,
    height: symbolHeight,
    bodyPaths: ['M 20 8 H 58 C 86 8 100 21 100 40 C 100 59 86 72 58 72 H 20 Z'],
    detailPaths: [],
    leadPaths: leads(inputPorts, bodyLeft, outputAttach(bodyRight, inverted), 40),
    inputPorts,
    outputPort: { x: rightPortX, y: 40 },
    ...(bubble ? { inversionBubble: bubble } : {})
  };
}

/**
 * حافّةُ OR اليسرى **منحنيةٌ لا مستقيمة**، فرِجلٌ إلى x ثابتٍ تقف قبل
 * الجسم عند الأطراف وتخترقه عند الوسط. تُحلّ الحافّةُ عددياً من منحنى
 * بيزيه نفسِه — نفسُ المعادلة التي تُرسم بها، فلا تتفرّق الرِّجلُ عن الشكل.
 */
function orLeftEdgeX(y: number): number {
  const cubic = (a: number, b: number, c: number, d: number, t: number): number => {
    const u = 1 - t;
    return a * u ** 3 + 3 * b * t * u ** 2 + 3 * c * t ** 2 * u + d * t ** 3;
  };
  let low = 0;
  let high = 1;
  for (let step = 0; step < 24; step += 1) {
    const middle = (low + high) / 2;
    if (cubic(72, 55, 25, 8, middle) > y) low = middle;
    else high = middle;
  }
  return cubic(24, 40, 40, 24, (low + high) / 2);
}

function orGate(inputCount: number, inverted: boolean, exclusive: boolean): SymbolGeometry {
  const bubble = inverted ? { center: { x: 104, y: 40 }, radius: 6 } : undefined;
  const inputPorts = ports(inputCount);
  return {
    width: symbolWidth,
    height: symbolHeight,
    bodyPaths: ['M 24 8 C 54 10 84 18 100 40 C 84 62 54 70 24 72 C 40 55 40 25 24 8 Z'],
    detailPaths: exclusive ? ['M 16 8 C 32 25 32 55 16 72'] : [],
    leadPaths: leads(inputPorts, orLeftEdgeX, outputAttach(bodyRight, inverted), 40),
    inputPorts,
    outputPort: { x: rightPortX, y: 40 },
    ...(bubble ? { inversionBubble: bubble } : {})
  };
}

/**
 * المصباح: دائرةٌ بساقٍ واحدة — لا مستطيلَ طرفيّاً كبقية المخارج.
 * سببُ تخصيصه أنّ الطالب يجب أن يرى **إضاءةً** لا رقماً في صندوق؛
 * والقيمةُ تُكتب داخل الزجاجة فيبقى اللونُ مؤكِّداً لا حاملاً وحيداً
 * للمعنى. (منفذُ الخرج يبقى في الهندسة للتوافق ولا يُرسم: دورُ
 * `output` لا يصلح مصدراً أصلاً في المُحقِّق.)
 */
function lamp(): SymbolGeometry {
  return {
    width: symbolWidth,
    height: 80,
    bodyPaths: [
      /* ما يجعلها تُقرأ **لمبةً** لا نقطةَ اختبار هو **القاعدةُ الملولبة**
         لا الزجاجةُ وحدَها: دائرةٌ عاريةٌ رمزُ مِجَسٍّ في كل كتاب. */
      'M 4 40 H 24',
      'M 24 31 H 44 V 49 H 24 Z',
      'M 44 40 H 52',
      'M 52 40 A 26 26 0 1 1 104 40 A 26 26 0 1 1 52 40 Z'
    ],
    /* أسنانُ القاعدة تفصيلٌ رفيع؛ ولا شعيرةَ داخل الزجاجة — القيمةُ
       تُكتب فيها، وخطٌّ متعرّجٌ خلف رقمٍ يجعل الاثنين غيرَ مقروءين. */
    detailPaths: ['M 28 31 V 49 M 34 31 V 49 M 40 31 V 49'],
    leadPaths: [],
    inputPorts: [{ x: 4, y: 40 }],
    outputPort: { x: 116, y: 40 }
  };
}

/**
 * الكتلةُ التوافقية: مستطيلٌ **بأسماء منافذه**. المستطيلُ الأصمُّ كان
 * أسوأَ ما في المكتبة — لا يقول أيُّ دبّوسٍ هو المُحدِّد وأيُّها البيانات،
 * والطالبُ يوصّل بالتخمين. الأسماءُ من عُرف الكتاب (D0/D1/S · A/B/C).
 */
function labelledBlock(inputCount: number, pinNames: readonly string[], title: string): SymbolGeometry {
  const height = Math.max(symbolHeight, 24 + inputCount * 26);
  const spread = Array.from({ length: inputCount }, (_, index) => ({
    x: leftPortX,
    y: 24 + index * ((height - 48) / Math.max(1, inputCount - 1))
  }));
  const inputPorts = inputCount === 1 ? [{ x: leftPortX, y: height / 2 }] : spread;
  return {
    width: symbolWidth,
    height,
    bodyPaths: [`M ${bodyLeft} 6 H ${bodyRight} V ${height - 6} H ${bodyLeft} Z`],
    detailPaths: [],
    leadPaths: leads(inputPorts, bodyLeft, bodyRight, height / 2),
    inputPorts,
    outputPort: { x: rightPortX, y: height / 2 },
    pinNames: pinNames.slice(0, inputCount),
    blockTitle: title
  };
}

/**
 * شكلُ المازج شبهُ منحرفٍ كما في الكتاب: البياناتُ تدخل من اليسار
 * والمُحدِّداتُ من الأسفل. يتمدّد مع سعته (2:1 · 4:1 · 8:1) فيبقى بين
 * كل دبّوسين فراغٌ يكفي لسلكٍ ولاسمه.
 */
function mux(totalPorts: number): SymbolGeometry {
  const selectCount = muxSelectCount(totalPorts);
  const dataCount = 2 ** selectCount;
  /* الجسمُ ثم **كِشحٌ** أسفلَه لدبابيس المحدِّدات. بدون الكِشح كانت
     دبابيسُ المحدِّد تقع خارج ارتفاع الرمز، فتخرج من هدف الإصابة ومن
     حدود العقدة التي يقيسها التوزيعُ التلقائيّ و«ملاءمة». */
  const bodyHeight = Math.max(symbolHeight, 24 + dataCount * 26);
  const skirt = 18;
  const dataPorts = Array.from({ length: dataCount }, (_, index) => ({
    x: leftPortX,
    y: 22 + index * ((bodyHeight - 44) / Math.max(1, dataCount - 1))
  }));
  /* المحدِّداتُ موزَّعةٌ على عرض القاعدة لا مرصوصةً من ٤٤: بثلاثةٍ (8:1)
     كان آخرُها يزحف على الحافّة اليمنى. */
  const selectPorts = Array.from({ length: selectCount }, (_, index) => ({
    x: Math.round(28 + ((index + 1) * 68) / (selectCount + 1)),
    y: bodyHeight + skirt - 6
  }));
  const inset = Math.min(18, bodyHeight / 5);
  /* قاعدةُ شبه المنحرف مائلة، فرِجلُ كل محدِّدٍ تبدأ من ارتفاع القاعدة
     **عند سينِه** لا من ارتفاعٍ واحد. */
  const baseY = (x: number): number => bodyHeight - 8 - (inset * (x - 28)) / 68;
  return {
    width: symbolWidth,
    height: bodyHeight + skirt,
    bodyPaths: [`M 28 8 L 96 ${8 + inset} V ${bodyHeight - 8 - inset} L 28 ${bodyHeight - 8} Z`],
    detailPaths: [],
    leadPaths: [
      ...dataPorts.map(port => `M ${port.x} ${port.y} H 28`),
      ...selectPorts.map(port => `M ${port.x} ${baseY(port.x).toFixed(2)} V ${port.y}`),
      `M 96 ${bodyHeight / 2} H ${rightPortX}`
    ],
    inputPorts: [...dataPorts, ...selectPorts],
    outputPort: { x: rightPortX, y: bodyHeight / 2 },
    pinNames: [
      ...Array.from({ length: dataCount }, (_, index) => `D${index}`),
      ...Array.from({ length: selectCount }, (_, index) => `S${index}`)
    ],
    blockTitle: 'MUX'
  };
}

export function geometryForComponent(component: ComponentKind, inputCount: number): SymbolGeometry {
  switch (component) {
    case 'SWITCH':
    case 'BUTTON':
    case 'CONSTANT_0':
    case 'CONSTANT_1':
      return terminal('input');
    case 'PROBE':
      return terminal('output');
    case 'LED':
      return lamp();
    case 'BUFFER':
      return triangle(false);
    case 'NOT':
      return triangle(true);
    case 'AND':
      return andGate(inputCount, false);
    case 'NAND':
      return andGate(inputCount, true);
    case 'OR':
      return orGate(inputCount, false, false);
    case 'NOR':
      return orGate(inputCount, true, false);
    case 'XOR':
      return orGate(inputCount, false, true);
    case 'XNOR':
      return orGate(inputCount, true, true);
    case 'MUX':
      return mux(inputCount);
    case 'MAJORITY':
      return labelledBlock(inputCount, ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H'], 'MAJ');
    case 'ODD_PARITY':
      return labelledBlock(inputCount, ['I0', 'I1', 'I2', 'I3', 'I4', 'I5', 'I6', 'I7'], 'ODD');
    case 'EVEN_PARITY':
      return labelledBlock(inputCount, ['I0', 'I1', 'I2', 'I3', 'I4', 'I5', 'I6', 'I7'], 'EVEN');
  }
}

export function labelPoint(geometry: SymbolGeometry, placement: LabelPlacement): LocalPoint {
  if (placement === 'top') return { x: geometry.width / 2, y: -8 };
  if (placement === 'center') return { x: geometry.width / 2, y: geometry.height / 2 };
  return { x: geometry.width / 2, y: geometry.height + 18 };
}

export function symbolContainsTechnicalText(_geometry: SymbolGeometry): boolean {
  return false;
}
