/* ═══════════════════════════════════════════════════════════════
   simplify.ts — التبسيط: الجوابُ يُحسب، و**الطريقُ إليه على أسلوب الكتاب**
   ═══════════════════════════════════════════════════════════════
   🔴 قرارُ فهد 08-05: «أزل تبسيط Quine–McCluskey فالطالب لا يستفيد منه».
   والعلّةُ الحقيقية أنّ **المعروض** كان جدولَ الأوّليّات وطريقةَ التغطية
   — وهي ليست في المقرَّر. أمّا حسابُ الجواب الأصغر فلا بدّ منه، ولا
   يُعرض: يبقى في هذا الملفّ آلةً صامتة.

   ما يراه الطالبُ الآن **اشتقاقٌ جبريٌّ بخطوات** كما في Mano §2.4/§3:
     مجموعُ الصغريات ← تكرارُ حدٍّ عند الحاجة (x = x + x)
     ← توحيدٌ متكرّر (xy + xy′ = x) ← الحدُّ الأصغر.
   كلُّ خطوةٍ تحمل **اسمَ القانون** الذي طُبِّق، فيقرأ الطالبُ برهاناً لا
   نتيجةً هبطت عليه. والتدوينُ بالشرطة العليا (A′) كما في الكتاب.
   ═══════════════════════════════════════════════════════════════ */

export interface PrimeImplicant {
  readonly pattern: string;
  readonly coveredMinterms: readonly number[];
  readonly literalCount: number;
}

/** أسماءُ القوانين المعروضة — كلُّها من فصل الجبر البولي في الكتاب. */
export type SimplificationLaw =
  | 'sum-of-minterms'
  | 'dont-care'
  | 'idempotent'
  | 'combining'
  | 'minimal';

export interface DerivationStep {
  readonly law: SimplificationLaw;
  readonly expression: string;
  readonly termCount: number;
}

export interface SimplificationResult {
  readonly variableNames: readonly string[];
  readonly minterms: readonly number[];
  readonly dontCares: readonly number[];
  readonly primeImplicants: readonly PrimeImplicant[];
  readonly selectedImplicants: readonly PrimeImplicant[];
  readonly expression: string;
  readonly exact: boolean;
  /** الاشتقاقُ خطوةً خطوة — هذا ما يُعرض، لا جداولُ الأوّليّات. */
  readonly steps: readonly DerivationStep[];
  readonly literalCount: number;
}

interface WorkingImplicant {
  readonly pattern: string;
  readonly terms: ReadonlySet<number>;
  readonly used: boolean;
}

const patternKey = (pattern: string): string => pattern;
const countLiterals = (pattern: string): number => [...pattern].filter(bit => bit !== '-').length;

function combinePatterns(left: string, right: string): string | null {
  let differenceCount = 0;
  let result = '';
  for (let index = 0; index < left.length; index += 1) {
    const leftBit = left[index]!;
    const rightBit = right[index]!;
    if (leftBit === rightBit) result += leftBit;
    else if (leftBit !== '-' && rightBit !== '-') {
      differenceCount += 1;
      result += '-';
    } else return null;
  }
  return differenceCount === 1 ? result : null;
}

function mergeTerms(left: ReadonlySet<number>, right: ReadonlySet<number>): ReadonlySet<number> {
  return new Set([...left, ...right]);
}

function generatePrimePatterns(variableCount: number, allTerms: readonly number[]): readonly Readonly<{ pattern: string; terms: ReadonlySet<number> }>[] {
  let current: WorkingImplicant[] = [...new Set(allTerms)].sort((a, b) => a - b).map(term => ({ pattern: term.toString(2).padStart(variableCount, '0'), terms: new Set([term]), used: false }));
  const primes = new Map<string, ReadonlySet<number>>();
  while (current.length > 0) {
    const next = new Map<string, WorkingImplicant>();
    const usedPatterns = new Set<string>();
    for (let leftIndex = 0; leftIndex < current.length; leftIndex += 1) {
      for (let rightIndex = leftIndex + 1; rightIndex < current.length; rightIndex += 1) {
        const combinedPattern = combinePatterns(current[leftIndex]!.pattern, current[rightIndex]!.pattern);
        if (!combinedPattern) continue;
        usedPatterns.add(current[leftIndex]!.pattern);
        usedPatterns.add(current[rightIndex]!.pattern);
        const existing = next.get(combinedPattern);
        next.set(combinedPattern, {
          pattern: combinedPattern,
          terms: existing ? mergeTerms(existing.terms, mergeTerms(current[leftIndex]!.terms, current[rightIndex]!.terms)) : mergeTerms(current[leftIndex]!.terms, current[rightIndex]!.terms),
          used: false
        });
      }
    }
    for (const implicant of current) if (!usedPatterns.has(implicant.pattern)) primes.set(implicant.pattern, mergeTerms(primes.get(implicant.pattern) ?? new Set(), implicant.terms));
    current = [...next.values()];
  }
  return [...primes.entries()].sort(([left], [right]) => left.localeCompare(right)).map(([pattern, terms]) => ({ pattern, terms }));
}

function patternCovers(pattern: string, minterm: number, variableCount: number): boolean {
  const bits = minterm.toString(2).padStart(variableCount, '0');
  return [...pattern].every((bit, index) => bit === '-' || bit === bits[index]);
}

function chooseCover(primes: readonly PrimeImplicant[], minterms: readonly number[]): Readonly<{ selected: readonly PrimeImplicant[]; exact: boolean }> {
  const selectedIndexes = new Set<number>();
  const uncovered = new Set(minterms);
  for (const minterm of minterms) {
    const covering = primes.map((prime, index) => prime.coveredMinterms.includes(minterm) ? index : -1).filter(index => index >= 0);
    if (covering.length === 1) selectedIndexes.add(covering[0]!);
  }
  for (const index of selectedIndexes) for (const minterm of primes[index]!.coveredMinterms) uncovered.delete(minterm);
  if (uncovered.size === 0) return { selected: [...selectedIndexes].map(index => primes[index]!), exact: true };

  const candidates = primes.map((prime, index) => ({ prime, index })).filter(candidate => !selectedIndexes.has(candidate.index) && candidate.prime.coveredMinterms.some(minterm => uncovered.has(minterm)));
  let best: number[] | null = null;
  let visited = 0;
  const score = (indexes: readonly number[]): readonly [number, number, string] => [indexes.length, indexes.reduce((sum, index) => sum + primes[index]!.literalCount, 0), indexes.map(index => primes[index]!.pattern).sort().join('|')];
  const better = (left: readonly number[], right: readonly number[]): boolean => {
    const a = score(left); const b = score(right);
    return a[0] < b[0] || (a[0] === b[0] && (a[1] < b[1] || (a[1] === b[1] && a[2] < b[2])));
  };

  function search(remaining: ReadonlySet<number>, chosen: readonly number[]): void {
    visited += 1;
    if (visited > 100_000 || (best && chosen.length >= best.length)) return;
    if (remaining.size === 0) {
      if (!best || better(chosen, best)) best = [...chosen];
      return;
    }
    const nextMinterm = [...remaining].sort((left, right) => {
      const leftCount = candidates.filter(candidate => candidate.prime.coveredMinterms.includes(left)).length;
      const rightCount = candidates.filter(candidate => candidate.prime.coveredMinterms.includes(right)).length;
      return leftCount - rightCount || left - right;
    })[0]!;
    for (const candidate of candidates.filter(candidate => candidate.prime.coveredMinterms.includes(nextMinterm))) {
      const nextRemaining = new Set([...remaining].filter(minterm => !candidate.prime.coveredMinterms.includes(minterm)));
      search(nextRemaining, [...chosen, candidate.index]);
    }
  }
  search(uncovered, []);
  if (!best) {
    const greedy: number[] = [];
    const remaining = new Set(uncovered);
    while (remaining.size > 0) {
      const candidate = candidates.map(item => ({ ...item, gain: item.prime.coveredMinterms.filter(minterm => remaining.has(minterm)).length })).sort((left, right) => right.gain - left.gain || left.prime.literalCount - right.prime.literalCount || left.prime.pattern.localeCompare(right.prime.pattern))[0];
      if (!candidate || candidate.gain === 0) break;
      greedy.push(candidate.index);
      for (const minterm of candidate.prime.coveredMinterms) remaining.delete(minterm);
    }
    best = greedy;
  }
  return { selected: [...selectedIndexes, ...best].map(index => primes[index]!), exact: visited <= 100_000 };
}

/**
 * تدوينُ الكتاب: المتمِّمُ شرطةٌ عليا (A′) والضربُ **تجاورٌ** بلا رمز —
 * `A′B` لا `¬A · B`. وإن كان اسمُ متغيّرٍ أطولَ من حرفٍ (تسميةُ الطالب
 * لمدخله) عاد الفاصلُ نقطةً، وإلا التصق اسمان فصارا اسماً ثالثاً.
 */
function implicantExpression(pattern: string, variableNames: readonly string[]): string {
  const literals = [...pattern].flatMap((bit, index) => {
    if (bit === '-') return [];
    const name = variableNames[index] ?? '?';
    return [bit === '1' ? name : `${name}′`];
  });
  if (literals.length === 0) return '1';
  const compact = variableNames.every(name => name.length === 1);
  return literals.join(compact ? '' : ' · ');
}

function sumExpression(patterns: readonly string[], variableNames: readonly string[]): string {
  return patterns.length === 0 ? '0' : patterns.map(pattern => implicantExpression(pattern, variableNames)).join(' + ');
}

const freeBitPositions = (pattern: string): number[] =>
  [...pattern].flatMap((bit, index) => (bit === '-' ? [index] : []));

/** كلُّ صغريات مكعّبٍ جزئيّ: تُعاد الأنماطُ بترتيبٍ ثابتٍ فلا يرقص العرض. */
function expandPattern(pattern: string, freeBits: readonly number[]): string[] {
  return Array.from({ length: 2 ** freeBits.length }, (_, mask) => {
    const bits = [...pattern];
    for (const [order, position] of freeBits.entries()) bits[position] = ((mask >> order) & 1) ? '1' : '0';
    return bits.join('');
  });
}

/**
 * الاشتقاقُ الجبريّ. مبدؤه أنّ **كلَّ حدٍّ أوّليٍّ مختارٍ مكعّبٌ كامل**:
 * صغرياتُه تنطبق زوجاً زوجاً على بتٍّ حرٍّ واحدٍ في كل جولة، وهو حرفياً
 * `xy + xy′ = x` مطبَّقاً بالتوازي. فالجولةُ الواحدة خطوةٌ واحدةٌ معروضة
 * — لا سطرٌ لكل زوجٍ فيغرق الطالبُ في عشرين سطراً.
 */
function buildDerivation(
  variableNames: readonly string[],
  minterms: readonly number[],
  selected: readonly PrimeImplicant[],
  width: number
): DerivationStep[] {
  const step = (law: SimplificationLaw, patterns: readonly string[]): DerivationStep => ({
    law, expression: sumExpression(patterns, variableNames), termCount: patterns.length
  });
  const canonical = minterms.map(minterm => minterm.toString(2).padStart(width, '0'));
  if (selected.length === 0) return [step('minimal', [])];

  const steps: DerivationStep[] = [step('sum-of-minterms', canonical)];

  const groups = selected.map(implicant => {
    const freeBits = freeBitPositions(implicant.pattern);
    return { pattern: implicant.pattern, freeBits, expansion: expandPattern(implicant.pattern, freeBits) };
  });
  const usedDontCares = [...new Set(groups.flatMap(group => group.expansion))]
    .filter(pattern => !canonical.includes(pattern))
    .sort();
  if (usedDontCares.length > 0) {
    steps.push(step('dont-care', [...canonical, ...usedDontCares]));
  }

  /* الصغرى المشتركةُ بين مجموعتين تُكرَّر أوّلاً بـ`x = x + x`: بدونها
     تبدو إحدى المجموعتين وقد سرقت حدَّ الأخرى. */
  const grouped = groups.flatMap(group => group.expansion);
  if (grouped.length > new Set(grouped).size) steps.push(step('idempotent', grouped));

  const rounds = Math.max(...groups.map(group => group.freeBits.length));
  for (let round = 1; round <= rounds; round += 1) {
    const patterns = groups.flatMap(group => {
      const merged = [...group.pattern];
      const remaining = group.freeBits.slice(Math.min(round, group.freeBits.length));
      for (const position of group.freeBits.slice(0, round)) merged[position] = '-';
      return expandPattern(merged.join(''), remaining);
    });
    steps.push(step('combining', patterns));
  }
  steps.push(step('minimal', groups.map(group => group.pattern)));

  /* خطوتان متتاليتان بنفس النصّ لا تُضيفان شيئاً — تُطوى الثانية. ثم
     تُوسَم الأخيرةُ **دائماً** بالصورة الصغرى: دالّةٌ لا شيءَ فيها ليُوحَّد
     (مثل مجموع النصف) اشتقاقُها سطرٌ واحد، وحقُّه أن يُقال عنه «هذه هي
     الصورةُ الصغرى» لا أن يُترك بلا حكم. */
  const collapsed = steps.filter((current, index) => index === 0 || current.expression !== steps[index - 1]!.expression);
  const last = collapsed[collapsed.length - 1]!;
  collapsed[collapsed.length - 1] = { ...last, law: 'minimal' };
  return collapsed;
}

/**
 * كنسُ الزوائد: التغطيةُ الجشعةُ (الاحتياطيّة) قد تُبقي حدّاً كلُّ صغرياته
 * مغطّاةٌ بغيره. حدٌّ زائدٌ يُفسد الاشتقاقَ قبل أن يُفسد الجواب.
 */
function withoutRedundantImplicants(selected: readonly PrimeImplicant[], minterms: readonly number[]): PrimeImplicant[] {
  const kept = [...selected].sort((left, right) => right.literalCount - left.literalCount || left.pattern.localeCompare(right.pattern));
  for (let index = kept.length - 1; index >= 0; index -= 1) {
    const without = kept.filter((_, position) => position !== index);
    const covered = new Set(without.flatMap(implicant => implicant.coveredMinterms));
    if (minterms.every(minterm => covered.has(minterm))) kept.splice(index, 1);
  }
  return kept.sort((left, right) => left.pattern.localeCompare(right.pattern));
}

export function simplifyMinterms(variableNames: readonly string[], mintermsInput: readonly number[], dontCaresInput: readonly number[] = []): SimplificationResult {
  if (variableNames.length > 8) throw new RangeError('Simplification supports at most 8 variables.');
  const maximumMinterm = 2 ** variableNames.length;
  const minterms = [...new Set(mintermsInput)].sort((a, b) => a - b);
  const dontCares = [...new Set(dontCaresInput)].filter(term => !minterms.includes(term)).sort((a, b) => a - b);
  if ([...minterms, ...dontCares].some(term => !Number.isInteger(term) || term < 0 || term >= maximumMinterm)) throw new RangeError('Minterm is outside the supported variable range.');
  if (minterms.length === 0) {
    return {
      variableNames, minterms, dontCares, primeImplicants: [], selectedImplicants: [],
      expression: '0', exact: true, literalCount: 0,
      steps: [{ law: 'minimal', expression: '0', termCount: 0 }]
    };
  }
  const primePatterns = generatePrimePatterns(variableNames.length, [...minterms, ...dontCares]);
  const primes = primePatterns.map(({ pattern }) => ({
    pattern,
    coveredMinterms: minterms.filter(minterm => patternCovers(pattern, minterm, variableNames.length)),
    literalCount: countLiterals(pattern)
  })).filter(prime => prime.coveredMinterms.length > 0);
  const cover = chooseCover(primes, minterms);
  const selectedImplicants = withoutRedundantImplicants(cover.selected, minterms);
  return {
    variableNames,
    minterms,
    dontCares,
    primeImplicants: primes,
    selectedImplicants,
    expression: sumExpression(selectedImplicants.map(implicant => implicant.pattern), variableNames),
    exact: cover.exact,
    literalCount: selectedImplicants.reduce((sum, implicant) => sum + implicant.literalCount, 0),
    steps: buildDerivation(variableNames, minterms, selectedImplicants, variableNames.length)
  };
}

export function evaluateSimplification(result: SimplificationResult, minterm: number): 0 | 1 {
  return result.selectedImplicants.some(implicant => patternCovers(implicant.pattern, minterm, result.variableNames.length)) ? 1 : 0;
}
