import type { WorkspaceArtifactV1, WorkspaceNodeV1, WorkspacePointV1, WorkspaceWireV1, WireEndpointV1, WireRouteV1 } from '../domain/workspace.ts';
import { validateWorkspaceDocument } from './validate-document.ts';
import type { ValidationIssue } from './issues.ts';

export type CircuitCommand =
  | Readonly<{ type: 'node.add'; node: WorkspaceNodeV1 }>
  | Readonly<{ type: 'node.update'; nodeId: string; patch: Partial<Omit<WorkspaceNodeV1, 'id'>> }>
  | Readonly<{ type: 'node.move-many'; positions: Readonly<Record<string, WorkspacePointV1>> }>
  | Readonly<{ type: 'node.duplicate-many'; nodeIds: readonly string[]; offset: WorkspacePointV1 }>
  | Readonly<{ type: 'node.delete-many'; nodeIds: readonly string[] }>
  | Readonly<{ type: 'wire.connect'; wire: WorkspaceWireV1 }>
  | Readonly<{ type: 'wire.reconnect'; wireId: string; source?: WireEndpointV1; target?: WireEndpointV1 }>
  | Readonly<{ type: 'wire.update'; wireId: string; patch: Readonly<{ label?: string; route?: WireRouteV1 }> }>
  | Readonly<{ type: 'wire.delete-many'; wireIds: readonly string[] }>
  | Readonly<{ type: 'document.replace-import'; artifact: WorkspaceArtifactV1 }>
  | Readonly<{ type: 'document.load-preset'; artifact: WorkspaceArtifactV1 }>
  | Readonly<{ type: 'document.reset'; artifact: WorkspaceArtifactV1 }>;

export interface CommandValidationResult {
  readonly valid: boolean;
  readonly issues: readonly ValidationIssue[];
}

function commandIssue(code: ValidationIssue['code'], params: ValidationIssue['params'], location: Pick<ValidationIssue, 'nodeId' | 'wireId'> = {}): ValidationIssue {
  return { code, severity: 'error', params, ...location };
}

function candidateWithRevision(artifact: WorkspaceArtifactV1, circuit: WorkspaceArtifactV1['circuit']): WorkspaceArtifactV1 {
  return { ...artifact, circuit };
}

function validateCandidate(candidate: WorkspaceArtifactV1): CommandValidationResult {
  const result = validateWorkspaceDocument(candidate);
  const issues = result.issues.filter(issue => issue.severity === 'error');
  return { valid: issues.length === 0, issues };
}

export function validateCommandPreflight(artifact: WorkspaceArtifactV1, command: CircuitCommand): CommandValidationResult {
  const nodeById = new Map(artifact.circuit.nodes.map(node => [node.id, node]));
  const wireById = new Map(artifact.circuit.wires.map(wire => [wire.id, wire]));
  switch (command.type) {
    case 'node.add':
      if (nodeById.has(command.node.id)) return { valid: false, issues: [commandIssue('DUPLICATE_ID', { kind: 'node' }, { nodeId: command.node.id })] };
      return validateCandidate(candidateWithRevision(artifact, { ...artifact.circuit, nodes: [...artifact.circuit.nodes, command.node] }));
    case 'node.update': {
      const node = nodeById.get(command.nodeId);
      if (!node) return { valid: false, issues: [commandIssue('INVALID_TARGET', { reason: 'unknown-node' }, { nodeId: command.nodeId })] };
      return validateCandidate(candidateWithRevision(artifact, {
        ...artifact.circuit,
        nodes: artifact.circuit.nodes.map(candidate => candidate.id === command.nodeId ? { ...candidate, ...command.patch, id: candidate.id } : candidate)
      }));
    }
    case 'node.move-many': {
      const unknownNodeId = Object.keys(command.positions).find(nodeId => !nodeById.has(nodeId));
      if (unknownNodeId) return { valid: false, issues: [commandIssue('INVALID_TARGET', { reason: 'unknown-node' }, { nodeId: unknownNodeId })] };
      return validateCandidate(candidateWithRevision(artifact, {
        ...artifact.circuit,
        nodes: artifact.circuit.nodes.map(node => command.positions[node.id] ? { ...node, position: command.positions[node.id] } : node)
      }));
    }
    case 'node.duplicate-many': {
      const unknownNodeId = command.nodeIds.find(nodeId => !nodeById.has(nodeId));
      if (unknownNodeId) return { valid: false, issues: [commandIssue('INVALID_TARGET', { reason: 'unknown-node' }, { nodeId: unknownNodeId })] };
      const uniqueCount = new Set(command.nodeIds).size;
      const roleCounts = new Map<string, number>();
      for (const nodeId of new Set(command.nodeIds)) {
        const role = nodeById.get(nodeId)?.role;
        if (role) roleCounts.set(role, (roleCounts.get(role) ?? 0) + 1);
      }
      const currentCounts = new Map(['input', 'gate', 'output'].map(role => [role, artifact.circuit.nodes.filter(node => node.role === role).length]));
      const limits = { input: 8, gate: 100, output: 8 } as const;
      for (const role of ['input', 'gate', 'output'] as const) {
        const nextCount = (currentCounts.get(role) ?? 0) + (roleCounts.get(role) ?? 0);
        if (nextCount > limits[role]) return { valid: false, issues: [commandIssue('LIMIT_REACHED', { kind: role, count: nextCount, maximum: limits[role] })] };
      }
      return uniqueCount === 0 ? { valid: false, issues: [commandIssue('INVALID_TARGET', { reason: 'empty-selection' })] } : { valid: true, issues: [] };
    }
    case 'node.delete-many': {
      const unknownNodeId = command.nodeIds.find(nodeId => !nodeById.has(nodeId));
      return unknownNodeId ? { valid: false, issues: [commandIssue('INVALID_TARGET', { reason: 'unknown-node' }, { nodeId: unknownNodeId })] } : { valid: true, issues: [] };
    }
    case 'wire.connect':
      if (wireById.has(command.wire.id)) return { valid: false, issues: [commandIssue('DUPLICATE_ID', { kind: 'wire' }, { wireId: command.wire.id })] };
      return validateCandidate(candidateWithRevision(artifact, { ...artifact.circuit, wires: [...artifact.circuit.wires, command.wire] }));
    case 'wire.reconnect': {
      const wire = wireById.get(command.wireId);
      if (!wire) return { valid: false, issues: [commandIssue('INVALID_TARGET', { reason: 'unknown-wire' }, { wireId: command.wireId })] };
      const replacement = { ...wire, ...(command.source ? { source: command.source } : {}), ...(command.target ? { target: command.target } : {}) };
      return validateCandidate(candidateWithRevision(artifact, {
        ...artifact.circuit,
        wires: artifact.circuit.wires.map(candidate => candidate.id === command.wireId ? replacement : candidate)
      }));
    }
    case 'wire.update': {
      const wire = wireById.get(command.wireId);
      if (!wire) return { valid: false, issues: [commandIssue('INVALID_TARGET', { reason: 'unknown-wire' }, { wireId: command.wireId })] };
      return validateCandidate(candidateWithRevision(artifact, {
        ...artifact.circuit,
        wires: artifact.circuit.wires.map(candidate => candidate.id === command.wireId ? { ...candidate, ...command.patch, id: candidate.id } : candidate)
      }));
    }
    case 'wire.delete-many': {
      const unknownWireId = command.wireIds.find(wireId => !wireById.has(wireId));
      return unknownWireId ? { valid: false, issues: [commandIssue('INVALID_TARGET', { reason: 'unknown-wire' }, { wireId: unknownWireId })] } : { valid: true, issues: [] };
    }
    case 'document.replace-import':
    case 'document.load-preset':
    case 'document.reset':
      return validateCandidate(command.artifact);
  }
}
