import { cloneWorkspaceArtifactV1, type WorkspaceArtifactV1 } from '../domain/workspace.ts';

export const HISTORY_MAX_ENTRIES = 100;
export const HISTORY_MAX_BYTES = 5 * 1024 * 1024;

export interface WorkspaceHistory {
  readonly past: readonly WorkspaceArtifactV1[];
  readonly present: WorkspaceArtifactV1;
  readonly future: readonly WorkspaceArtifactV1[];
  readonly estimatedBytes: number;
}

function artifactBytes(artifact: WorkspaceArtifactV1): number {
  return new TextEncoder().encode(JSON.stringify(artifact)).byteLength;
}

function historyBytes(past: readonly WorkspaceArtifactV1[], present: WorkspaceArtifactV1, future: readonly WorkspaceArtifactV1[]): number {
  return [...past, present, ...future].reduce((total, artifact) => total + artifactBytes(artifact), 0);
}

function trimPast(past: WorkspaceArtifactV1[], present: WorkspaceArtifactV1, maximumEntries: number, maximumBytes: number): WorkspaceArtifactV1[] {
  while (past.length > maximumEntries) past.shift();
  while (past.length > 0 && historyBytes(past, present, []) > maximumBytes) past.shift();
  return past;
}

export function createWorkspaceHistory(initialArtifact: WorkspaceArtifactV1): WorkspaceHistory {
  const present = cloneWorkspaceArtifactV1(initialArtifact);
  return { past: [], present, future: [], estimatedBytes: artifactBytes(present) };
}

export function commitWorkspaceHistory(
  history: WorkspaceHistory,
  nextArtifact: WorkspaceArtifactV1,
  limits: Readonly<{ maximumEntries?: number; maximumBytes?: number }> = {}
): WorkspaceHistory {
  if (nextArtifact === history.present || JSON.stringify(nextArtifact) === JSON.stringify(history.present)) return history;
  const present = cloneWorkspaceArtifactV1(nextArtifact);
  const past = trimPast(
    [...history.past, cloneWorkspaceArtifactV1(history.present)],
    present,
    limits.maximumEntries ?? HISTORY_MAX_ENTRIES,
    limits.maximumBytes ?? HISTORY_MAX_BYTES
  );
  return { past, present, future: [], estimatedBytes: historyBytes(past, present, []) };
}

export function undoWorkspaceHistory(history: WorkspaceHistory): WorkspaceHistory {
  const previous = history.past.at(-1);
  if (!previous) return history;
  const past = history.past.slice(0, -1);
  const present = cloneWorkspaceArtifactV1(previous);
  const future = [cloneWorkspaceArtifactV1(history.present), ...history.future];
  return { past, present, future, estimatedBytes: historyBytes(past, present, future) };
}

export function redoWorkspaceHistory(history: WorkspaceHistory): WorkspaceHistory {
  const next = history.future[0];
  if (!next) return history;
  const past = [...history.past, cloneWorkspaceArtifactV1(history.present)];
  const present = cloneWorkspaceArtifactV1(next);
  const future = history.future.slice(1);
  return { past, present, future, estimatedBytes: historyBytes(past, present, future) };
}
