export const LAB_MESSAGES = {
  ar: {
    title: 'منشئ الدوائر التوافقية',
    observe: 'شاهد العلاقة',
    predict: 'تنبأ قبل المحاكاة',
    build: 'ابنِ بنفسك',
    verify: 'أثبت الصحة',
    complete: 'اكتمل الدليل',
    verifyAll: 'تحقق من الحالات الأربع',
    savedLocal: 'محفوظ محلياً',
    freeBuild: 'البناء الحر'
  },
  en: {
    title: 'Combinational Circuit Builder',
    observe: 'Observe the relationship',
    predict: 'Predict before simulation',
    build: 'Build it yourself',
    verify: 'Prove correctness',
    complete: 'Evidence complete',
    verifyAll: 'Verify all four cases',
    savedLocal: 'Saved locally',
    freeBuild: 'Free build'
  }
} as const;

export type LabLocale = keyof typeof LAB_MESSAGES;

export function message(locale: LabLocale, key: keyof typeof LAB_MESSAGES.ar): string {
  return LAB_MESSAGES[locale][key];
}

/**
 * الرفضُ يُشرح بالسبب لا بالرمز. القاعدةُ الملزِمة: الأمرُ المرفوض **لا
 * يغيّر الرسم** — فالرسالةُ هي كلُّ ما يراه الطالب، وإن كانت
 * `COMBINATIONAL_CYCLE` لم يتعلّم منها شيئاً.
 */
export function describeIssue(
  issue: Readonly<{ code: string; params: Readonly<Record<string, unknown>> }>,
  locale: LabLocale
): string {
  const ar = locale === 'ar';
  switch (issue.code) {
    case 'COMBINATIONAL_CYCLE':
      return ar
        ? 'لا يمكن: هذا يُغلق حلقةً على نفسها. الدائرة التوافقية تسير في اتجاه واحد من المدخل إلى المخرج.'
        : 'Not allowed: this closes a loop. A combinational circuit flows one way, input to output.';
    case 'TARGET_OCCUPIED':
      return ar
        ? 'هذا المدخل موصولٌ أصلاً. احذف سلكه أولاً، أو استخدم مدخلاً آخر.'
        : 'That input is already driven. Delete its wire first, or use another input.';
    case 'INVALID_SOURCE':
      return ar ? 'المصدر يجب أن يكون مخرَجَ عنصر.' : 'A wire must start at a component output.';
    case 'INVALID_TARGET':
      return ar ? 'الوجهة يجب أن تكون مدخلاً غير مشغول.' : 'A wire must end at a free component input.';
    case 'LIMIT_REACHED':
      return ar
        ? `بلغتَ الحدّ: ${issue.params.maximum} من نوع ${issue.params.kind}.`
        : `Limit reached: ${issue.params.maximum} ${issue.params.kind} components.`;
    case 'INVALID_ARITY':
      return ar
        ? `عدد المداخل يجب أن يكون بين ${issue.params.minimum} و${issue.params.maximum}.`
        : `Inputs must be between ${issue.params.minimum} and ${issue.params.maximum}.`;
    case 'OUT_OF_BOUNDS':
      return ar ? 'خارج مساحة العمل.' : 'Outside the workspace.';
    case 'ROLE_COMPONENT_MISMATCH':
      return ar ? 'هذا العنصر لا يصلح في هذا الموضع.' : 'That component does not fit this role.';
    default:
      return ar ? 'تعذّر تنفيذ هذه الخطوة.' : 'That step could not be applied.';
  }
}
