import type { CircuitDocumentV1, WorkspacePointV1, WorkspaceWireV1 } from '../domain/workspace.ts';
import { nodeBounds, portGeometryForNode } from './port-geometry.ts';
import { routeOrthogonal, type OrthogonalRouteResult } from './orthogonal-router.ts';

export function routeWire(document: CircuitDocumentV1, wire: WorkspaceWireV1): OrthogonalRouteResult {
  const sourceNode = document.nodes.find(node => node.id === wire.source.nodeId);
  const targetNode = document.nodes.find(node => node.id === wire.target.nodeId);
  if (!sourceNode || !targetNode) return { points: [], visitedCells: 0, found: false };
  const source = portGeometryForNode(sourceNode).output.center;
  const target = portGeometryForNode(targetNode).inputs.find(port => port.id === wire.target.portId)?.center;
  if (!target) return { points: [], visitedCells: 0, found: false };
  const endpointIds = new Set([sourceNode.id, targetNode.id]);
  return routeOrthogonal({
    source,
    target,
    obstacles: document.nodes.filter(node => !endpointIds.has(node.id)).map(nodeBounds),
    pinnedWaypoints: wire.route.mode === 'orthogonal-pinned' ? wire.route.waypoints : [],
    bounds: { width: document.width, height: document.height }
  });
}

export function pointsToSvgPath(points: readonly WorkspacePointV1[]): string {
  if (points.length === 0) return '';
  return points.map((point, index) => `${index === 0 ? 'M' : 'L'} ${point.x} ${point.y}`).join(' ');
}

export function pathContainsDiagonal(points: readonly WorkspacePointV1[]): boolean {
  return points.some((point, index) => index > 0 && point.x !== points[index - 1]!.x && point.y !== points[index - 1]!.y);
}
