import type { KarnaughMap } from '../kernel/karnaugh.ts';

export interface KarnaughViewModel {
  readonly map: KarnaughMap;
  readonly direction: 'ltr';
  readonly scrollable: true;
  readonly canExpand: true;
  readonly messageKey?: 'kmap.algorithmic-only';
}

export function createKarnaughViewModel(map: KarnaughMap): KarnaughViewModel {
  return { map, direction: 'ltr', scrollable: true, canExpand: true, ...(map.available ? {} : { messageKey: 'kmap.algorithmic-only' as const }) };
}
