const CATEGORY_ORDER: readonly ComponentCategory[] = ['essentials', 'gates', 'combinational'];

/** العناصرُ التي يختار الطالبُ عددَ مداخلها — نفسُ ما يقبله المُحقِّق. */
const VARIABLE_ARITY = new Set<ComponentKind>(['AND', 'NAND', 'OR', 'NOR', 'XOR', 'XNOR', 'ODD_PARITY', 'EVEN_PARITY']);

/**
 * عناصرُ سعتُها **مُعدَّدةٌ لا متّصلة**: مازجٌ 2:1 أو 4:1 أو 8:1 (2^n بيانات
 * + n مُحدِّداً)، وأغلبيةٌ بعددٍ فرديٍّ وحدَه — أغلبيةُ عددٍ زوجيٍّ غيرُ
 * معرَّفةٍ عند التعادل. حقلُ رقمٍ حرٌّ هنا يعرض قيماً يرفضها المُحقِّق،
 * فالاختيارُ أزرارٌ بما هو مسموحٌ فقط.
 */
const ENUMERATED_ARITY: Partial<Record<ComponentKind, ReadonlyArray<readonly [number, string]>>> = {
  MUX: [[3, '2:1'], [6, '4:1'], [11, '8:1']],
  MAJORITY: [[3, '3'], [5, '5'], [7, '7']]
};

function text(locale: LabLocale, ar: string, en: string): string {
  return locale === 'ar' ? ar : en;
}

/**
 * أيقونةُ Font Awesome — والورقةُ محمَّلةٌ في صفحة المختبر أصلاً.
 *
 * 🔑 **لماذا عنصرٌ لا محرف**: كانت الأزرارُ تحمل `✕` و`✎` و`🗑` نصّاً.
 *    والإيموجي **لا يُنزع لونُه ولا يتبع الثيم** (الدستور الثامن)، فيظهر
 *    مربّعُ سلّةٍ ملوّناً وسط واجهةٍ رماديةٍ منضبطة، ويختلف رسمُه بين
 *    ويندوز وأندرويد وiOS. و`el()` تكتب `textContent` فلا ينجو فيها
 *    وسمٌ — ولذلك تُلحَق الأيقونةُ ابناً بعد إنشاء الزرّ.
 */
function faIcon(name: string): HTMLElement {
  const icon = document.createElement('i');
  icon.className = `fa-solid fa-${name}`;
  icon.setAttribute('aria-hidden', 'true');
  return icon;
}

function el<K extends keyof HTMLElementTagNameMap>(
  name: K, className?: string, textContent?: string
): HTMLElementTagNameMap[K] {
  const node = document.createElement(name);
  if (className) node.className = className;
  if (textContent !== undefined) node.textContent = textContent;
  return node;
}

/* ── مكتبة العناصر ───────────────────────────────────────────── */

export interface LibraryCallbacks {
  readonly onPick: (component: ComponentKind) => void;
  readonly onCollapseChange: (collapsed: boolean) => void;
}

/**
 * زرُّ طيِّ عمودٍ جانبيّ. مشتركٌ بين المكتبة والدليل: عمودان يُطويان
 * بزرّين مختلفَي الشكل يجعلان الطالبَ يبحث عن الثاني بعد أن تعلّم الأوّل.
 */
function buildCollapseButton(onToggle: () => void): HTMLButtonElement {
  const button = el('button', 'cx-collapse');
  button.type = 'button';
  button.addEventListener('click', onToggle);
  return button;
}

/** جانبُ العمود في المحور المنطقيّ — لا «يمين» و«يسار». */
type PanelSide = 'start' | 'end';

/**
 * ما يبقى في الشريط المطويّ: مفتاحٌ ومصباحٌ ومِجَسّ، والبواباتُ الأربع
 * التي لا تكاد دائرةٌ تخلو منها. عشرةُ رموزٍ أطولُ من الشريط فتُمرَّر.
 */
const RAIL_COMPONENTS: readonly ComponentKind[] = ['SWITCH', 'LED', 'PROBE', 'NOT', 'AND', 'OR', 'XOR', 'NAND'];

/**
 * 🔴 اتجاهُ السهم **يُحسب ولا يُكتب حرفياً** (تصحيحُ فهد): العمودان على
 * جانبين متقابلين، وقيمةٌ ثابتةٌ تصحّ لأحدهما وتنقلب على الآخر — وهو ما
 * وقع: سهمُ العناصر صحيحٌ وسهمُ التحليل معكوس. والحسابُ يضمّ اتجاهَ
 * الصفحة أيضاً، فما يشير يساراً في الإنجليزية يشير يميناً في العربية.
 */
function syncCollapseButton(
  button: HTMLButtonElement,
  collapsed: boolean,
  locale: LabLocale,
  name: { ar: string; en: string },
  side: PanelSide
): void {
  const label = collapsed
    ? text(locale, `إظهار ${name.ar}`, `Show ${name.en}`)
    : text(locale, `طيّ ${name.ar}`, `Collapse ${name.en}`);
  button.title = label;
  button.setAttribute('aria-label', label);
  button.setAttribute('aria-expanded', String(!collapsed));

  const rightToLeft = document.documentElement.getAttribute('dir') === 'rtl';
  /* 🔴 السهمُ يشير إلى **أين تذهب المساحة**، لا إلى أين يذهب العمود
     (حكمُ فهد 08-05، وقد بنيتُها أوّلاً على الاصطلاح المقابل فقرأها
     معكوسة): مبسوطٌ ⇒ السهمُ نحو اللوحة لأنّها هي التي ستتّسع؛ ومطويٌّ
     ⇒ نحو حافّة العمود لأنّه هو الذي سيعود. والاصطلاحان كلاهما شائعٌ
     في الأدوات — فالحكمُ للمستخدم لا للسابقة. */
  const towardsStart = collapsed ? side === 'start' : side === 'end';
  const pointsLeft = rightToLeft ? !towardsStart : towardsStart;
  button.textContent = pointsLeft ? '‹' : '›';
}

export class LibraryPanel {
  readonly element: HTMLElement;
  private readonly list: HTMLDivElement;
  private readonly search: HTMLInputElement;
  private readonly note: HTMLParagraphElement;
  private readonly callbacks: LibraryCallbacks;
  private readonly collapseButton: HTMLButtonElement;
  private readonly rail: HTMLDivElement;
  private locale: LabLocale = 'ar';
  private open = new Set<ComponentCategory>(['essentials']);
  private query = '';
  private armed: ComponentKind | null = null;
  private collapsed = false;

  constructor(callbacks: LibraryCallbacks) {
    this.callbacks = callbacks;
    this.element = el('section', 'cx-panel cx-library');

    const head = el('header', 'cx-panel-head');
    head.appendChild(el('h2', 'cx-panel-title', 'العناصر'));
    this.collapseButton = buildCollapseButton(() => this.setCollapsed(!this.collapsed));
    head.appendChild(this.collapseButton);
    this.element.appendChild(head);

    const searchWrap = el('div', 'cx-lib-search');
    this.search = document.createElement('input');
    this.search.type = 'search';
    this.search.className = 'cx-lib-input';
    this.search.autocomplete = 'off';
    this.search.spellcheck = false;
    searchWrap.appendChild(this.search);
    this.element.appendChild(searchWrap);

    /* سطرُ الحالة يقول ما يحدث الآن: أيُّ عنصرٍ مُهيَّأ وكيف يُوضع. بدونه
       يبدو النقرُ على العنصر بلا أثر. */
    this.note = el('p', 'cx-lib-note');
    this.element.appendChild(this.note);

    this.list = el('div', 'cx-lib-list');
    this.element.appendChild(this.list);

    /* 🔴 **الشريطُ المطويُّ لا يكون فارغاً** (طلبُ فهد): عمودٌ مطويٌّ بلا
       شيءٍ يجعل الطيَّ مقايضةً خاسرة — تكسب مساحةً وتفقد العمل. تبقى فيه
       أيقوناتُ ما يُستعمل في كل دائرةٍ تقريباً: طرفا دخلٍ وخرجٍ والبواباتُ
       الأساسية. وبقيّتُها خلف زرّ الفتح. */
    this.rail = el('div', 'cx-lib-rail');
    for (const kind of RAIL_COMPONENTS) {
      const definition = COMPONENT_LIBRARY.find(candidate => candidate.kind === kind);
      if (!definition) continue;
      const button = el('button', 'cx-rail-btn');
      button.type = 'button';
      button.dataset.kind = kind;
      button.appendChild(buildSymbolIcon(kind, definition.inputCount));
      button.addEventListener('click', () => this.callbacks.onPick(kind));
      this.rail.appendChild(button);
    }
    this.element.appendChild(this.rail);

    this.search.addEventListener('input', () => {
      this.query = this.search.value.trim();
      this.renderList();
    });
  }

  setLocale(locale: LabLocale): void {
    this.locale = locale;
    const title = this.element.querySelector('.cx-panel-title');
    if (title) title.textContent = text(locale, 'العناصر', 'Components');
    this.search.placeholder = text(locale, 'ابحث باسم العنصر…', 'Search components…');
    this.search.setAttribute('aria-label', text(locale, 'ابحث في العناصر', 'Search components'));
    syncCollapseButton(this.collapseButton, this.collapsed, locale, { ar: 'العناصر', en: 'components' }, 'start');
    this.syncRailLabels();
    this.renderNote();
    /* ⚠️ **هنا موضعُه**: `setLocale` هو ما يُستدعى عند التركيب، فبناءُ
       القائمة معلَّقٌ عليه. انزاح هذا السطرُ إلى `setCollapsed` حين
       قسّمتُ الدالّة لإضافة الطيّ، فصارت المكتبةُ فارغةً حتى يطوي
       المستخدمُ العمودَ ويعيده. */
    this.renderList();
  }

  /** أسماءُ البوابات إنجليزيةٌ حصراً، والوصفُ يتبع لغةَ الواجهة. */
  private syncRailLabels(): void {
    for (const button of this.rail.querySelectorAll<HTMLButtonElement>('.cx-rail-btn')) {
      const kind = button.dataset.kind ?? '';
      const label = text(this.locale, `ضع ${kind}`, `Place ${kind}`);
      button.title = label;
      button.setAttribute('aria-label', label);
      button.classList.toggle('is-armed', this.armed === kind);
    }
  }

  setCollapsed(collapsed: boolean): void {
    this.collapsed = collapsed;
    this.element.classList.toggle('is-collapsed', collapsed);
    syncCollapseButton(this.collapseButton, collapsed, this.locale, { ar: 'العناصر', en: 'components' }, 'start');
    this.syncRailLabels();
    this.callbacks.onCollapseChange(collapsed);
  }

  setArmed(component: ComponentKind | null): void {
    this.armed = component;
    this.renderNote();
    for (const button of this.list.querySelectorAll<HTMLButtonElement>('.cx-lib-item')) {
      button.classList.toggle('is-armed', button.dataset.kind === component);
      button.setAttribute('aria-pressed', String(button.dataset.kind === component));
    }
    this.syncRailLabels();
  }

  private renderNote(): void {
    this.note.textContent = this.armed
      ? text(this.locale, `انقر اللوحة لوضع ${this.armed} · Esc للإلغاء`, `Click the canvas to place ${this.armed} · Esc to cancel`)
      : text(this.locale, 'اختر عنصراً ثم انقر مكانه على اللوحة.', 'Pick a component, then click where it goes.');
    this.note.classList.toggle('is-armed', this.armed !== null);
  }

  private renderList(): void {
    this.list.replaceChildren();
    const searching = this.query.length > 0;
    const matches = searching ? new Set(searchComponents(this.query).map(item => item.kind)) : null;

    for (const category of CATEGORY_ORDER) {
      const items = COMPONENT_LIBRARY.filter(item => item.category === category)
        .filter(item => (matches ? matches.has(item.kind) : true));
      /* أثناء البحث تُحذف الفئةُ الخالية تماماً بدل عرض عنوانٍ بلا نتائج. */
      if (searching && items.length === 0) continue;

      const group = el('div', 'cx-lib-group');
      const toggle = el('button', 'cx-lib-toggle');
      toggle.type = 'button';
      /* أثناء البحث كلُّ فئةٍ مطابقة **مفتوحة** — وهذا هو إصلاح
         «البحث يعدّ ولا يعرض». */
      const expanded = searching || this.open.has(category);
      toggle.setAttribute('aria-expanded', String(expanded));
      toggle.append(
        el('span', 'cx-lib-name', text(this.locale, CATEGORY_TITLES[category].ar, CATEGORY_TITLES[category].en)),
        el('span', 'cx-lib-count', String(items.length))
      );
      toggle.addEventListener('click', () => {
        if (this.open.has(category)) this.open.delete(category); else this.open.add(category);
        this.renderList();
      });
      group.appendChild(toggle);

      if (expanded) {
        const grid = el('div', 'cx-lib-grid');
        for (const item of items) {
          const button = el('button', 'cx-lib-item' + (this.armed === item.kind ? ' is-armed' : ''));
          button.type = 'button';
          button.title = item.kind;
          button.dataset.kind = item.kind;
          button.setAttribute('aria-pressed', String(this.armed === item.kind));
          button.appendChild(buildSymbolIcon(item.kind, item.inputCount));
          /* الاسمُ إنجليزيٌّ في كل اللغات — ترجمةُ اسم البوابة تُفسد
             المصطلحَ الذي سيقرؤه الطالب في كل مرجعٍ ودرس. */
          button.appendChild(el('span', 'cx-lib-label', item.kind));
          button.addEventListener('click', () => this.callbacks.onPick(item.kind));
          grid.appendChild(button);
        }
        group.appendChild(grid);
      }
      this.list.appendChild(group);
    }

    if (this.list.childElementCount === 0) {
      this.list.appendChild(el('p', 'cx-empty',
        text(this.locale, 'لا عنصر بهذا الاسم.', 'No component matches that name.')));
    }
  }
}

/* ── قائمةُ الأمثلة ──────────────────────────────────────────── */

const GROUP_TITLES: Record<PresetGroup, { ar: string; en: string }> = {
  free: { ar: 'ابدأ من الصفر', en: 'Start from scratch' },
  ch2: { ar: 'الفصل ٢ · الجبر البولياني والبوابات', en: 'Ch.2 · Boolean algebra & gates' },
  ch3: { ar: 'الفصل ٣ · التصغير على مستوى البوابات', en: 'Ch.3 · Gate-level minimization' },
  ch4: { ar: 'الفصل ٤ · المنطق التوافقي', en: 'Ch.4 · Combinational logic' }
};

const GROUP_ORDER: readonly PresetGroup[] = ['free', 'ch2', 'ch3', 'ch4'];

/**
 * قائمةٌ **مبنيّةٌ** لا `<select>` أصليّ — عُرفُ صفحات الحديقة (`sx-ts` في
 * صفحة الشعب): زرٌّ يعرض المختار، ولوحةٌ تُفتح بعناوين مجموعاتٍ وعلامةِ
 * اختيار. سببُ العُرف أنّ القائمةَ الأصلية لا تُجمَّع ولا تُنسَّق ولا
 * تتبع ثيمَ الموقع، وشكلُها يختلف بين نظامٍ وآخر.
 *
 * وأسماءُ الأمثلة **إنجليزيةٌ كاملة** ⇒ `dir="ltr"` عليها ولو كانت الصفحة
 * عربية: سطرٌ لاتينيٌّ داخل سياقٍ عربيٍّ تنقلب فيه الأقواسُ والأرقام.
 */
export class PresetMenu {
  readonly element: HTMLElement;
  private readonly button: HTMLButtonElement;
  private readonly panel: HTMLDivElement;
  private readonly onPick: (presetId: string) => void;
  private locale: LabLocale = 'ar';
  private current: string;
  private open = false;

  constructor(current: string, onPick: (presetId: string) => void) {
    this.current = current;
    this.onPick = onPick;
    this.element = el('div', 'cx-menu');

    this.button = el('button', 'cx-menu-btn');
    this.button.type = 'button';
    this.button.setAttribute('aria-haspopup', 'listbox');
    this.button.addEventListener('click', () => this.setOpen(!this.open));
    this.element.appendChild(this.button);

    this.panel = el('div', 'cx-menu-panel');
    this.panel.setAttribute('role', 'listbox');
    this.element.appendChild(this.panel);

    /* الإغلاقُ بالنقر خارجاً وبـEsc — قائمةٌ لا تُغلق إلا بإعادة نقر زرّها
       تحبس المستخدم. المستمعُ على `document` في طور الالتقاط ليسبق أي
       معالجٍ يوقف الانتشار. */
    document.addEventListener('pointerdown', event => {
      if (this.open && !this.element.contains(event.target as Node)) this.setOpen(false);
    }, true);
    document.addEventListener('keydown', event => {
      if (event.key === 'Escape' && this.open) { this.setOpen(false); this.button.focus(); }
    });
  }

  setLocale(locale: LabLocale): void {
    this.locale = locale;
    this.render();
  }

  get value(): string { return this.current; }
  set value(presetId: string) { this.current = presetId; this.render(); }

  private setOpen(open: boolean): void {
    this.open = open;
    this.element.classList.toggle('is-open', open);
    this.button.setAttribute('aria-expanded', String(open));
    if (open) this.render();
  }

  private render(): void {
    const currentPreset = CIRCUIT_PRESETS.find(preset => preset.id === this.current);
    this.button.replaceChildren();
    const label = el('span', 'cx-menu-value', currentPreset?.name ?? '—');
    label.dir = 'ltr';
    this.button.append(
      el('span', 'cx-menu-hint', text(this.locale, 'المثال', 'Example')),
      label,
      el('span', 'cx-menu-caret')
    );

    this.panel.replaceChildren();
    for (const group of GROUP_ORDER) {
      const items = CIRCUIT_PRESETS.filter(preset => presetGroup(preset.id) === group);
      if (items.length === 0) continue;
      const groupTitle = el('p', 'cx-menu-group', text(this.locale, GROUP_TITLES[group].ar, GROUP_TITLES[group].en));
      /* عنوانُ المجموعة يتبع لغةَ الواجهة — هو نصُّ واجهةٍ لا مصطلحٌ. */
      this.panel.appendChild(groupTitle);
      for (const preset of items) {
        const item = el('button', 'cx-menu-item' + (preset.id === this.current ? ' is-on' : ''));
        item.type = 'button';
        /* البندُ كلُّه LTR لا نصُّه وحدَه: علامةُ الاختيار يجب أن تقف
           في بداية سطرٍ لاتينيّ (يساره)، وإلا قرأت العينُ من الطرف
           الخطأ في صفحةٍ عربية. */
        item.dir = 'ltr';
        item.setAttribute('role', 'option');
        item.setAttribute('aria-selected', String(preset.id === this.current));
        const name = el('span', 'cx-menu-name', preset.name);
        name.dir = 'ltr';
        item.append(el('span', 'cx-menu-check'), name);
        item.addEventListener('click', () => {
          this.current = preset.id;
          this.setOpen(false);
          this.render();
          this.onPick(preset.id);
        });
        this.panel.appendChild(item);
      }
    }
  }
}

/* ── نافذةُ المختبر ──────────────────────────────────────────── */

/**
 * 🔴 نافذةٌ بعُرف الحديقة تنسخ `window.prompt`/`confirm` (تصحيحُ فهد
 * 08-05). نافذةُ المتصفّح لا تقبل ثيماً ولا لغةً ولا اتجاهاً، وتظهر
 * بخطّ النظام فوق صفحةٍ عربية — تكسر الوهمَ الذي يبنيه الموقعُ كلُّه.
 * وهذه تتبع شكلَ `.sx-modal` في صفحة الشعب: ستارٌ ضبابيٌّ وصندوقُ بطاقة.
 */
interface PromptOptions {
  readonly title: string;
  readonly label?: string;
  readonly value?: string;
  readonly note?: string;
  readonly confirmText: string;
  readonly cancelText: string;
  readonly danger?: boolean;
}

export function labPrompt(options: PromptOptions): Promise<string | null> {
  return new Promise(resolve => {
    const overlay = el('div', 'cx-modal');
    const box = el('div', 'cx-modal-box');
    box.setAttribute('role', 'dialog');
    box.setAttribute('aria-modal', 'true');

    const head = el('div', 'cx-modal-head');
    head.appendChild(el('h3', 'cx-modal-title', options.title));
    const close = el('button', 'cx-modal-x');
    close.appendChild(faIcon('xmark'));
    close.type = 'button';
    close.setAttribute('aria-label', options.cancelText);
    head.appendChild(close);
    box.appendChild(head);

    if (options.note) box.appendChild(el('p', 'cx-modal-note', options.note));

    let field: HTMLInputElement | null = null;
    if (options.label !== undefined) {
      const label = el('label', 'cx-modal-label', options.label);
      const input = el('input', 'cx-modal-input');
      input.type = 'text';
      input.maxLength = 60;
      input.value = options.value ?? '';
      label.appendChild(input);
      box.appendChild(label);
      field = input;
    }

    const actions = el('div', 'cx-modal-actions');
    const cancel = el('button', 'cx-btn-ghost', options.cancelText);
    cancel.type = 'button';
    const confirm = el('button', `cx-btn-primary${options.danger ? ' is-danger' : ''}`, options.confirmText);
    confirm.type = 'button';
    actions.append(cancel, confirm);
    box.appendChild(actions);
    overlay.appendChild(box);

    let settled = false;
    const finish = (result: string | null) => {
      if (settled) return;
      settled = true;
      document.removeEventListener('keydown', onKey, true);
      overlay.remove();
      resolve(result);
    };
    /* الالتقاطُ يسبق مستمعَ `Escape` في القوائم، وإلا أُغلقت القائمةُ
       تحت النافذة بدل النافذة نفسِها. */
    const onKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape') { event.stopPropagation(); finish(null); }
      if (event.key === 'Enter' && field) { event.preventDefault(); finish(field.value); }
    };
    document.addEventListener('keydown', onKey, true);
    close.addEventListener('click', () => finish(null));
    cancel.addEventListener('click', () => finish(null));
    confirm.addEventListener('click', () => finish(field ? field.value : ''));
    /* النقرُ على الستار وحدَه يُلغي — نقرةٌ داخل الصندوق ليست إلغاءً. */
    overlay.addEventListener('pointerdown', event => { if (event.target === overlay) finish(null); });

    document.body.appendChild(overlay);
    (field ?? confirm).focus();
    field?.select();
  });
}

/* ── قائمةُ المحفوظات ────────────────────────────────────────── */

export interface SlotMenuCallbacks {
  readonly list: () => readonly ArtifactSlot[];
  readonly onSaveNew: (name: string) => void;
  readonly onOverwrite: (slotId: string) => void;
  readonly onOpen: (slotId: string) => void;
  readonly onRename: (slotId: string, name: string) => void;
  readonly onRemove: (slotId: string) => void;
}

/**
 * محفوظاتُ الطالب المسمّاة. مبنيّةٌ بنفس عُرف قائمة الأمثلة (زرٌّ + لوحة)
 * فلا يتعلّم الطالبُ نمطين في شريطٍ واحد.
 *
 * ⚠️ والحفظُ التلقائيُّ **لا يظهر هنا**: هو جلستُك الجارية لا نسخةً
 * تختارها. خلطُهما يجعل «افتح» يبتلع ما تعمل عليه الآن.
 */
export class SlotMenu {
  readonly element: HTMLElement;
  private readonly button: HTMLButtonElement;
  private readonly panel: HTMLDivElement;
  private readonly callbacks: SlotMenuCallbacks;
  private locale: LabLocale = 'ar';
  private open = false;

  constructor(callbacks: SlotMenuCallbacks) {
    this.callbacks = callbacks;
    this.element = el('div', 'cx-menu cx-slots');

    this.button = el('button', 'cx-icon-btn');
    this.button.type = 'button';
    this.button.setAttribute('aria-haspopup', 'menu');
    /* 🔴 أيقونةٌ **تُفرَّق عن جارتها** (تصحيحُ فهد): كانت قرصَ الحفظ نفسَه
       الذي يحمله زرُّ التصدير، فزرّان متجاوران بأيقونةٍ واحدةٍ لا يُقرأ
       أحدُهما. صندوقُ أرشيفٍ بغطاءٍ ومقبض: «نُسخٌ محفوظة». */
    const icon = svgElement('svg', { viewBox: '0 0 24 24', class: 'cx-glyph', 'aria-hidden': 'true', focusable: 'false' });
    icon.appendChild(svgElement('path', { d: 'M3 5h18v4H3zM5 9v10h14V9M10 13h4' }));
    this.button.appendChild(icon);
    this.button.addEventListener('click', () => this.setOpen(!this.open));
    this.element.appendChild(this.button);

    this.panel = el('div', 'cx-menu-panel cx-slot-panel');
    this.panel.setAttribute('role', 'menu');
    this.element.appendChild(this.panel);

    document.addEventListener('pointerdown', event => {
      if (this.open && !this.element.contains(event.target as Node)) this.setOpen(false);
    }, true);
    document.addEventListener('keydown', event => {
      if (event.key === 'Escape' && this.open) { this.setOpen(false); this.button.focus(); }
    });
    this.syncButton();
  }

  setLocale(locale: LabLocale): void {
    this.locale = locale;
    this.syncButton();
    if (this.open) this.render();
  }

  /** تُستدعى بعد كل حفظٍ أو حذفٍ فيتبع العدُّ الحقيقةَ لا آخرَ فتحة. */
  refresh(): void {
    this.syncButton();
    if (this.open) this.render();
  }

  close(): void { this.setOpen(false); }

  private syncButton(): void {
    const count = this.callbacks.list().length;
    const label = text(this.locale, `محفوظاتي (${count})`, `My saves (${count})`);
    this.button.title = label;
    this.button.setAttribute('aria-label', label);
    this.button.classList.toggle('has-items', count > 0);
  }

  private setOpen(open: boolean): void {
    this.open = open;
    this.element.classList.toggle('is-open', open);
    this.button.setAttribute('aria-expanded', String(open));
    if (open) this.render();
  }

  private render(): void {
    this.panel.replaceChildren();
    this.panel.appendChild(el('p', 'cx-menu-group', text(this.locale, 'محفوظاتي', 'My saves')));

    const slots = this.callbacks.list();
    if (slots.length === 0) {
      this.panel.appendChild(el('p', 'cx-slot-empty',
        text(this.locale, 'لا محفوظات بعد. احفظ نسختك الأولى باسمٍ تتذكّره.', 'No saves yet. Store your first copy under a name you will recognise.')));
    }
    for (const slot of slots) {
      const row = el('div', 'cx-slot');
      const open = el('button', 'cx-slot-open');
      open.type = 'button';
      open.append(
        el('span', 'cx-slot-name', slot.name),
        el('span', 'cx-slot-date', formatSlotDate(slot.updatedAt, this.locale))
      );
      open.addEventListener('click', () => { this.setOpen(false); this.callbacks.onOpen(slot.id); });
      row.appendChild(open);

      const actions = el('div', 'cx-slot-actions');
      const overwrite = this.slotAction('floppy-disk', text(this.locale, 'استبدله بعملك الحالي', 'Replace with current work'));
      overwrite.addEventListener('click', () => { this.callbacks.onOverwrite(slot.id); this.refresh(); });
      const rename = this.slotAction('pen', text(this.locale, 'إعادة التسمية', 'Rename'));
      rename.addEventListener('click', async () => {
        const next = await labPrompt({
          title: text(this.locale, 'إعادة تسمية النسخة', 'Rename this copy'),
          label: text(this.locale, 'الاسم الجديد', 'New name'),
          value: slot.name,
          confirmText: text(this.locale, 'حفظ الاسم', 'Save name'),
          cancelText: text(this.locale, 'إلغاء', 'Cancel')
        });
        if (next !== null) { this.callbacks.onRename(slot.id, next); this.refresh(); }
      });
      const remove = this.slotAction('trash', text(this.locale, 'حذف', 'Delete'));
      remove.addEventListener('click', async () => {
        /* الحذفُ لا رجعةَ فيه ⇒ تأكيدٌ يذكر **الاسمَ** لا «هل أنت متأكّد؟» */
        const answer = await labPrompt({
          title: text(this.locale, 'حذف النسخة', 'Delete this copy'),
          note: text(this.locale, `ستُحذف «${slot.name}» نهائياً ولا يمكن استرجاعها.`, `“${slot.name}” will be deleted permanently and cannot be recovered.`),
          confirmText: text(this.locale, 'احذفها', 'Delete it'),
          cancelText: text(this.locale, 'إلغاء', 'Cancel'),
          danger: true
        });
        if (answer !== null) { this.callbacks.onRemove(slot.id); this.refresh(); }
      });
      actions.append(overwrite, rename, remove);
      row.appendChild(actions);
      this.panel.appendChild(row);
    }

    const add = el('button', 'cx-slot-add');
    add.type = 'button';
    add.textContent = text(this.locale, '＋ حفظ نسخة باسم', '＋ Save a copy');
    add.addEventListener('click', async () => {
      const name = await labPrompt({
        title: text(this.locale, 'حفظ نسخة باسم', 'Save a copy'),
        label: text(this.locale, 'اسم النسخة', 'Copy name'),
        value: text(this.locale, `نسختي ${slots.length + 1}`, `My copy ${slots.length + 1}`),
        note: text(this.locale, 'تُحفظ على هذا الجهاز، ويبقى حفظُك التلقائي كما هو.', 'Stored on this device; your autosave stays as it is.'),
        confirmText: text(this.locale, 'احفظ', 'Save'),
        cancelText: text(this.locale, 'إلغاء', 'Cancel')
      });
      if (name === null) return;
      this.setOpen(false);
      this.callbacks.onSaveNew(name);
    });
    this.panel.appendChild(add);
  }

  private slotAction(icon: string, label: string): HTMLButtonElement {
    const button = el('button', 'cx-slot-action');
    button.appendChild(faIcon(icon));
    button.type = 'button';
    button.title = label;
    button.setAttribute('aria-label', label);
    return button;
  }
}

/** تاريخٌ قصيرٌ بتقويم الواجهة — الأرقامُ العربية في العربية. */
function formatSlotDate(iso: string, locale: LabLocale): string {
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return '';
  return new Intl.DateTimeFormat(locale === 'ar' ? 'ar-SA-u-ca-gregory' : 'en-GB', {
    day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit'
  }).format(date);
}

/* ── لوحة الخصائص ────────────────────────────────────────────── */

export interface PropertiesCallbacks {
  readonly onUpdateNode: (nodeId: string, patch: Partial<Omit<WorkspaceNodeV1, 'id'>>) => void;
}

const PLACEMENT_LABELS: Record<LabelPlacement, { ar: string; en: string }> = {
  top: { ar: 'فوق', en: 'Top' },
  center: { ar: 'داخل', en: 'Center' },
  bottom: { ar: 'تحت', en: 'Bottom' }
};

export class PropertiesPanel {
  readonly element: HTMLElement;
  private readonly toggle: HTMLButtonElement;
  private readonly body: HTMLDivElement;
  private readonly callbacks: PropertiesCallbacks;
  private locale: LabLocale = 'ar';
  /* مطويّةٌ في البدء، ولا يغيّرها إلا المستخدم: تغيّرُ التحديد لا يفتح
     ولا يغلق — لوحةٌ تقفز مع كل نقرةٍ تُفقد الثقة بها. */
  private open = false;
  private node: WorkspaceNodeV1 | null = null;

  constructor(callbacks: PropertiesCallbacks) {
    this.callbacks = callbacks;
    this.element = el('section', 'cx-props');

    this.toggle = el('button', 'cx-props-toggle');
    this.toggle.type = 'button';
    this.toggle.setAttribute('aria-expanded', 'false');
    this.toggle.addEventListener('click', () => {
      this.open = !this.open;
      this.render();
    });
    this.element.appendChild(this.toggle);

    this.body = el('div', 'cx-props-body');
    this.element.appendChild(this.body);
  }

  setLocale(locale: LabLocale): void {
    this.locale = locale;
    this.render();
  }

  update(node: WorkspaceNodeV1 | null): void {
    this.node = node;
    this.render();
  }

  private render(): void {
    const heading = text(this.locale, 'الخصائص', 'Properties');
    this.toggle.replaceChildren(
      el('span', 'cx-props-name', heading),
      el('span', 'cx-props-subject', this.node ? (this.node.label || this.node.id) : '—')
    );
    this.toggle.setAttribute('aria-expanded', String(this.open));
    this.element.classList.toggle('is-open', this.open);
    this.body.replaceChildren();
    if (!this.open) return;

    const node = this.node;
    if (!node) {
      this.body.appendChild(el('p', 'cx-empty',
        text(this.locale, 'اختر عنصراً على اللوحة.', 'Select a component on the canvas.')));
      return;
    }

    const kind = el('p', 'cx-props-kind', node.component);
    kind.dir = 'ltr';
    this.body.appendChild(kind);

    /* الاسم: يُلتزم عند `change` لا عند كل حرف — وإلا صار التراجعُ
       يمشي حرفاً حرفاً ولا يعود إلى ما قبل التسمية. */
    const nameField = el('label', 'cx-field');
    nameField.appendChild(el('span', 'cx-field-label', text(this.locale, 'الاسم', 'Label')));
    const nameInput = document.createElement('input');
    nameInput.type = 'text';
    nameInput.className = 'cx-input';
    nameInput.maxLength = WORKSPACE_LIMITS.maximumLabelLength;
    nameInput.value = node.label;
    nameInput.dir = 'ltr';
    nameInput.addEventListener('change', () => {
      if (nameInput.value !== node.label) this.callbacks.onUpdateNode(node.id, { label: nameInput.value });
    });
    nameField.appendChild(nameInput);
    this.body.appendChild(nameField);

    const placementField = el('div', 'cx-field');
    placementField.appendChild(el('span', 'cx-field-label', text(this.locale, 'موضع الاسم', 'Label position')));
    const placementGroup = el('div', 'cx-segment');
    placementGroup.setAttribute('role', 'group');
    for (const placement of ['top', 'center', 'bottom'] as const) {
      const button = el('button', 'cx-segment-btn' + (node.labelPlacement === placement ? ' is-on' : ''),
        text(this.locale, PLACEMENT_LABELS[placement].ar, PLACEMENT_LABELS[placement].en));
      button.type = 'button';
      button.setAttribute('aria-pressed', String(node.labelPlacement === placement));
      button.addEventListener('click', () => this.callbacks.onUpdateNode(node.id, { labelPlacement: placement }));
      placementGroup.appendChild(button);
    }
    placementField.appendChild(placementGroup);
    this.body.appendChild(placementField);

    const capacities = ENUMERATED_ARITY[node.component];
    if (capacities) {
      const field = el('div', 'cx-field');
      field.appendChild(el('span', 'cx-field-label', text(this.locale, 'السعة', 'Capacity')));
      const group = el('div', 'cx-segment');
      group.setAttribute('role', 'group');
      for (const [count, caption] of capacities) {
        const button = el('button', 'cx-segment-btn' + (node.inputCount === count ? ' is-on' : ''), caption);
        button.type = 'button';
        button.dir = 'ltr';
        button.setAttribute('aria-pressed', String(node.inputCount === count));
        button.addEventListener('click', () => {
          if (node.inputCount !== count) this.callbacks.onUpdateNode(node.id, { inputCount: count });
        });
        group.appendChild(button);
      }
      field.appendChild(group);
      this.body.appendChild(field);
    }

    if (VARIABLE_ARITY.has(node.component)) {
      const arityField = el('label', 'cx-field');
      arityField.appendChild(el('span', 'cx-field-label', text(this.locale, 'عدد المداخل', 'Inputs')));
      const arityInput = document.createElement('input');
      arityInput.type = 'number';
      arityInput.className = 'cx-input';
      arityInput.min = '2';
      arityInput.max = '8';
      arityInput.step = '1';
      arityInput.value = String(node.inputCount);
      arityInput.addEventListener('change', () => {
        const next = Math.min(8, Math.max(2, Math.round(Number(arityInput.value) || node.inputCount)));
        arityInput.value = String(next);
        if (next !== node.inputCount) this.callbacks.onUpdateNode(node.id, { inputCount: next });
      });
      arityField.appendChild(arityInput);
      this.body.appendChild(arityField);
    }

    if (node.role === 'output') {
      const displayField = el('div', 'cx-field');
      displayField.appendChild(el('span', 'cx-field-label', text(this.locale, 'شكل المخرج', 'Output shape')));
      const displayGroup = el('div', 'cx-segment');
      displayGroup.setAttribute('role', 'group');
      for (const [component, display] of [['PROBE', 'probe'], ['LED', 'led']] as const) {
        const button = el('button', 'cx-segment-btn' + (node.component === component ? ' is-on' : ''), component);
        button.type = 'button';
        button.dir = 'ltr';
        button.setAttribute('aria-pressed', String(node.component === component));
        button.addEventListener('click', () => {
          if (node.component !== component) this.callbacks.onUpdateNode(node.id, { component, outputDisplay: display });
        });
        displayGroup.appendChild(button);
      }
      displayField.appendChild(displayGroup);
      this.body.appendChild(displayField);
    }
  }
}

/* ── لوحة الدليل ─────────────────────────────────────────────── */

type EvidenceTab = 'truth' | 'karnaugh' | 'signals' | 'explain';

const TAB_TITLES: Record<EvidenceTab, { ar: string; en: string }> = {
  truth: { ar: 'جدول الحقيقة', en: 'Truth table' },
  karnaugh: { ar: 'كارنو والتبسيط', en: 'Karnaugh & simplification' },
  signals: { ar: 'الإشارات', en: 'Signals' },
  explain: { ar: 'اشرح لي', en: 'Explain' }
};

const TAB_ORDER: readonly EvidenceTab[] = ['truth', 'karnaugh', 'signals', 'explain'];

export class EvidencePanel {
  readonly element: HTMLElement;
  private readonly tabsBar: HTMLDivElement;
  private readonly body: HTMLDivElement;
  private readonly expandButton: HTMLButtonElement;
  private readonly collapseButton: HTMLButtonElement;
  private collapsed = false;
  private locale: LabLocale = 'ar';
  /* الفتحُ على الناتج لا على التتبّع: جدولُ الحقيقة هو ما يُطلب من
     الطالب في الدرس والاختبار. */
  private tab: EvidenceTab = 'truth';
  private expanded = false;
  private showInternalSignals = false;
  private latest: { artifact: WorkspaceArtifactV1; snapshot: EvidenceSnapshot } | null = null;
  private readonly onExpandChange: (expanded: boolean) => void;
  private readonly onCollapseChange: (collapsed: boolean) => void;
  private readonly onApplyRow: (inputs: Readonly<Record<string, LogicBit>>) => void;
  /* بناءُ سياق الشرح يعرفه `LabView` وحدَه (اسمُ المثال وفصلُه) —
     تُحقن دالّةً فلا تعرف لوحةُ الدليل عن المسارد شيئاً. */
  explainContext: ((snapshot: EvidenceSnapshot) => ExplainContext | null) | null = null;

  constructor(
    onExpandChange: (expanded: boolean) => void,
    onCollapseChange: (collapsed: boolean) => void,
    onApplyRow: (inputs: Readonly<Record<string, LogicBit>>) => void
  ) {
    this.onExpandChange = onExpandChange;
    this.onCollapseChange = onCollapseChange;
    this.onApplyRow = onApplyRow;
    this.element = el('section', 'cx-panel cx-evidence');

    const head = el('header', 'cx-panel-head');
    head.appendChild(el('h2', 'cx-panel-title', 'التحليل والنتائج'));
    this.expandButton = el('button', 'cx-icon-btn');
    this.expandButton.type = 'button';
    this.expandButton.addEventListener('click', () => {
      this.expanded = !this.expanded;
      this.element.classList.toggle('is-expanded', this.expanded);
      this.syncExpandButton();
      this.onExpandChange(this.expanded);
    });
    head.appendChild(this.expandButton);
    /* التوسيعُ والطيُّ فعلان مختلفان: الأوّل يأخذ المختبرَ كلَّه لجدولٍ
       كبير، والثاني يُخلي المكانَ للوحة. زرٌّ واحدٌ لهما كان يعني أنّ
       «التحليلَ يقبل التكبير ولا يقبل التصغير» — وهي ملاحظةُ فهد. */
    this.collapseButton = buildCollapseButton(() => this.setCollapsed(!this.collapsed));
    head.appendChild(this.collapseButton);
    this.element.appendChild(head);

    this.tabsBar = el('div', 'cx-tabs');
    this.tabsBar.setAttribute('role', 'tablist');
    this.element.appendChild(this.tabsBar);

    this.body = el('div', 'cx-evidence-body');
    this.element.appendChild(this.body);
  }

  setLocale(locale: LabLocale): void {
    this.locale = locale;
    const title = this.element.querySelector('.cx-panel-title');
    if (title) title.textContent = text(locale, 'التحليل والنتائج', 'Analysis & evidence');
    this.syncExpandButton();
    syncCollapseButton(this.collapseButton, this.collapsed, locale, { ar: 'التحليل', en: 'analysis' }, 'end');
    this.renderTabs();
    this.renderBody();
  }

  setCollapsed(collapsed: boolean): void {
    this.collapsed = collapsed;
    this.element.classList.toggle('is-collapsed', collapsed);
    syncCollapseButton(this.collapseButton, collapsed, this.locale, { ar: 'التحليل', en: 'analysis' }, 'end');
    /* المطويُّ لا يُوسَّع: زرُّ التوسيع يبقى بلا معنى فيُخفى. */
    this.expandButton.hidden = collapsed;
    this.onCollapseChange(collapsed);
  }

  private syncExpandButton(): void {
    const label = this.expanded
      ? text(this.locale, 'تصغير لوحة الدليل', 'Collapse evidence')
      : text(this.locale, 'توسيع لوحة الدليل', 'Expand evidence');
    this.expandButton.title = label;
    this.expandButton.setAttribute('aria-label', label);
    this.expandButton.setAttribute('aria-pressed', String(this.expanded));
    this.expandButton.textContent = this.expanded ? '⤡' : '⤢';
  }

  update(artifact: WorkspaceArtifactV1, snapshot: EvidenceSnapshot): void {
    this.latest = { artifact, snapshot };
    this.renderTabs();
    this.renderBody();
  }

  private renderTabs(): void {
    this.tabsBar.replaceChildren();
    for (const tab of TAB_ORDER) {
      const button = el('button', 'cx-tab' + (this.tab === tab ? ' is-active' : ''));
      button.type = 'button';
      button.setAttribute('role', 'tab');
      button.setAttribute('aria-selected', String(this.tab === tab));
      button.textContent = text(this.locale, TAB_TITLES[tab].ar, TAB_TITLES[tab].en);
      button.addEventListener('click', () => { this.tab = tab; this.renderTabs(); this.renderBody(); });
      this.tabsBar.appendChild(button);
    }
  }

  private renderBody(): void {
    this.body.replaceChildren();
    if (!this.latest) return;
    const { artifact, snapshot } = this.latest;
    if (this.tab === 'signals') this.renderSignals(artifact, snapshot);
    else if (this.tab === 'truth') this.renderTruthTable(snapshot);
    else if (this.tab === 'explain') this.renderExplain(snapshot);
    else this.renderKarnaugh(snapshot);
  }

  /** يُستدعى من الشريط: يفتح تبويبَ الشرح ويأتي به إلى العين. */
  openExplain(): void {
    this.tab = 'explain';
    this.renderTabs();
    this.renderBody();
  }

  /* ── الشرح بالذكاء الاصطناعي ─────────────────────────────────
     الشرحُ الأوّل مجّانيٌّ ومخزَّن، ثم إعادتان لكل مثالٍ ولكل لغة —
     والمتبقّيةُ **مكتوبةٌ على الزرّ** لا رفضٌ مفاجئٌ عند الثالثة. */

  private renderExplain(snapshot: EvidenceSnapshot): void {
    const context = this.explainContext?.(snapshot);
    if (!context) {
      this.body.appendChild(el('p', 'cx-empty', text(this.locale, 'لا دائرة لتُشرح بعد.', 'Nothing to explain yet.')));
      return;
    }
    const wrap = el('div', 'cx-ai');
    const head = el('div', 'cx-ai-head');
    const name = el('span', 'cx-ai-name', context.presetName);
    name.dir = 'ltr';
    head.appendChild(name);
    wrap.appendChild(head);

    const body = el('div', 'cx-ai-body');
    wrap.appendChild(body);

    const cached = readCachedExplanation(context.presetId, this.locale);
    const used = regenerationsUsed(context.presetId, this.locale);
    const remaining = REGENERATION_ALLOWANCE - used;

    const action = el('button', 'cx-btn-primary cx-ai-go');
    action.type = 'button';
    const syncAction = () => {
      const left = REGENERATION_ALLOWANCE - regenerationsUsed(context.presetId, this.locale);
      /* ⚠️ «هل يوجد شرح؟» يُقاس بوجود **فقرةِ شرحٍ** لا بوجود أبناء:
         سطرُ الدعوة الأوّل ابنٌ أيضاً، فكان الزرُّ يقول «اشرح مرّةً أخرى»
         قبل أن يُشرح شيء. */
      const hasText = body.querySelector('.cx-ai-p, .cx-ai-h') !== null;
      action.textContent = hasText
        ? text(this.locale, `اشرح مرّةً أخرى (${left} متبقّية)`, `Explain again (${left} left)`)
        : text(this.locale, 'اشرح لي هذا المثال', 'Explain this example');
      action.disabled = hasText && left <= 0;
      action.title = action.disabled
        ? text(this.locale, 'انتهت إعادتاك لهذا المثال.', 'You have used both regenerations for this example.')
        : '';
    };

    if (cached) {
      body.replaceChildren(renderExplanation(cached));
    } else {
      body.appendChild(el('p', 'cx-ai-idle', text(this.locale,
        'شرحٌ مكتوبٌ لهذه الدائرة بعينها: فكرتُها · كيف تعمل بواباتُها · مثالٌ من الواقع · موضعُها في الكتاب.',
        'A written explanation of this exact circuit: the idea, how its gates work, a real-world use, and where it sits in the textbook.')));
    }

    action.addEventListener('click', async () => {
      const left = REGENERATION_ALLOWANCE - regenerationsUsed(context.presetId, this.locale);
      const isRegeneration = body.querySelector('.cx-ai-p, .cx-ai-h') !== null;
      if (isRegeneration && left <= 0) return;
      action.disabled = true;
      const status = el('p', 'cx-ai-status', text(this.locale, 'يقرأ دائرتك…', 'Reading your circuit…'));
      body.replaceChildren(status);
      const result = await streamExplanation(
        buildExplainMessages(context, this.locale),
        partial => body.replaceChildren(renderExplanation(partial)),
        () => { status.textContent = text(this.locale, 'يفكّر…', 'Thinking…'); }
      );
      if (result.ok) {
        writeCachedExplanation(context.presetId, this.locale, result.text);
        if (isRegeneration) countRegeneration(context.presetId, this.locale);
        body.replaceChildren(renderExplanation(result.text));
      } else {
        /* السببُ يُقال: «تعذّر» وحدَها تجعل الطالبَ يعيد المحاولة عبثاً. */
        const reasons: Record<string, [string, string]> = {
          offline: ['لا اتصال بالشبكة الآن.', 'No network connection right now.'],
          unavailable: ['خدمةُ الشرح غير متاحة الآن — جرّب بعد قليل.', 'The explain service is unavailable — try again shortly.'],
          empty: ['لم يصل شرحٌ — أعد المحاولة.', 'No explanation came back — try again.']
        };
        const [ar, en] = reasons[result.reason] ?? ['تعذّر الشرح.', 'Explanation failed.'];
        body.replaceChildren(el('p', 'cx-ai-error', text(this.locale, ar, en)));
      }
      syncAction();
      action.disabled = false;
    });

    syncAction();
    /* الحصّةُ تُقال قبل أن تُستهلك، لا بعد أن تنفد. */
    if (cached) {
      wrap.appendChild(el('p', 'cx-ai-quota', text(
        this.locale,
        remaining > 0 ? `لك ${remaining} إعادةٌ لهذا المثال.` : 'انتهت إعادتاك لهذا المثال.',
        remaining > 0 ? `${remaining} regeneration(s) left for this example.` : 'No regenerations left for this example.'
      )));
    }
    wrap.appendChild(action);
    this.body.appendChild(wrap);
  }

  private renderSignals(artifact: WorkspaceArtifactV1, snapshot: EvidenceSnapshot): void {
    const rows = createSignalViewRows(artifact, snapshot);
    if (rows.length === 0) {
      this.body.appendChild(el('p', 'cx-empty', text(this.locale, 'لا عقد بعد.', 'No nodes yet.')));
      return;
    }
    /* المخرجاتُ وحدَها ظاهرةٌ افتراضياً: هي ما يسأل عنه السؤال. البواباتُ
       والمداخلُ تتبّعٌ داخليّ يُطلب عند الحاجة، وعددُها مكتوبٌ على
       الكاشف فيعرف الطالبُ أنّ شيئاً هناك ولا يبحث عنه. */
    const primary = rows.filter(row => row.role === 'output');
    const internal = rows.filter(row => row.role !== 'output');
    this.body.appendChild(this.buildSignalList(primary.length > 0 ? primary : rows));

    if (primary.length > 0 && internal.length > 0) {
      const toggle = el('button', 'cx-more');
      toggle.type = 'button';
      toggle.setAttribute('aria-expanded', String(this.showInternalSignals));
      toggle.textContent = this.showInternalSignals
        ? text(this.locale, 'إخفاء الإشارات الداخلية', 'Hide internal signals')
        : text(this.locale, `الإشارات الداخلية (${internal.length})`, `Internal signals (${internal.length})`);
      toggle.addEventListener('click', () => {
        this.showInternalSignals = !this.showInternalSignals;
        this.renderBody();
      });
      this.body.appendChild(toggle);
      if (this.showInternalSignals) this.body.appendChild(this.buildSignalList(internal));
    }
  }

  private buildSignalList(rows: readonly ReturnType<typeof createSignalViewRows>[number][]): HTMLElement {
    const list = el('div', 'cx-signals');
    for (const row of rows) {
      const item = el('div', `cx-signal is-${row.role}`);
      item.appendChild(el('span', 'cx-signal-name', row.label || row.nodeId));
      const value = el('span', `cx-signal-value ${row.value === 1 ? 'is-high' : row.value === 0 ? 'is-low' : 'is-unknown'}`);
      value.textContent = String(row.value);
      item.appendChild(value);
      /* التعبيرُ سطرٌ تقنيّ ⇒ LTR صراحةً ولو كانت الواجهةُ عربية. */
      const expression = el('code', 'cx-signal-expr', row.expression);
      expression.dir = 'ltr';
      item.appendChild(expression);
      list.appendChild(item);
    }
    return list;
  }

  private renderTruthTable(snapshot: EvidenceSnapshot): void {
    const model = createTruthTableViewModel(snapshot.truthTable);
    if (model.columns.length === 0 || model.rowCount === 0) {
      this.body.appendChild(el('p', 'cx-empty',
        text(this.locale, 'أضف مدخلاً ومخرجاً لتوليد الجدول.', 'Add an input and an output to generate the table.')));
      return;
    }
    const scroll = el('div', 'cx-scroll');
    const table = el('table', 'cx-table');
    table.dir = 'ltr';

    const headRow = el('tr');
    for (const column of model.columns) {
      const cell = el('th', `cx-col-${column.kind}`, column.id);
      headRow.appendChild(cell);
    }
    const thead = el('thead');
    thead.appendChild(headRow);
    table.appendChild(thead);

    const tbody = el('tbody');
    /* الصفُّ الموافقُ للمدخلات الحالية مُعلَّم — وهو الرابطُ الذي يجعل
       الطالب يرى «أين يظهر الصفُّ نفسُه» عند تبديل مدخل. */
    const currentIndex = currentRowIndex(snapshot);
    for (const row of snapshot.truthTable.rows) {
      const tr = el('tr', row.index === currentIndex ? 'is-current' : '');
      /* 🔴 الصفُّ **يُشغّل الآلة**. جدولٌ لا يُنقر صورةٌ عن الدائرة؛ ونقرُه
         يجعله لوحةَ قيادةٍ لها: يقرأ الطالبُ سطراً فيرى الدائرةَ تتخذ
         حالتَه ويتتبّع الإشارةَ حتى المخرَج. */
      tr.tabIndex = 0;
      tr.setAttribute('role', 'button');
      tr.setAttribute('aria-label', `Apply row ${row.index}`);
      const apply = () => this.onApplyRow(row.inputs);
      tr.addEventListener('click', apply);
      tr.addEventListener('keydown', event => {
        if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); apply(); }
      });
      for (const column of model.columns) {
        const value = column.kind === 'input' ? row.inputs[column.id] : row.outputs[column.id];
        /* صنفُ العمود على الخانة أيضاً لا على رأسه وحدَه: الفاصلُ بين
           المداخل والمخارج يجب أن ينزل عبر الجدول كلِّه. */
        tr.appendChild(el('td',
          `cx-col-${column.kind} is-${value === 1 ? 'high' : value === 0 ? 'low' : 'unknown'}`,
          String(value ?? 'X')));
      }
      tbody.appendChild(tr);
    }
    table.appendChild(tbody);
    scroll.appendChild(table);
    this.body.appendChild(scroll);
  }

  private renderKarnaugh(snapshot: EvidenceSnapshot): void {
    const outputIds = snapshot.truthTable.outputNodeIds;
    if (outputIds.length === 0) {
      this.body.appendChild(el('p', 'cx-empty',
        text(this.locale, 'لا مخرج لعرض خريطته.', 'No output to map.')));
      return;
    }
    for (const outputId of outputIds) {
      const map = snapshot.karnaughByOutputId[outputId];
      const simplification = snapshot.simplificationByOutputId[outputId];
      const block = el('div', 'cx-kmap-block');
      const heading = el('h3', 'cx-kmap-title', snapshot.displayNameByNodeId[outputId] ?? outputId);
      heading.dir = 'ltr';
      block.appendChild(heading);

      /* كلُّ حدٍّ مختارٍ **مجموعةٌ ملوّنةٌ على الخريطة**: هذا هو الرابطُ
         الذي يجعل الخريطةَ تعليماً لا زينة — يرى الطالبُ أنّ هذا التجميعَ
         بعينِه أنتج ذلك الحدَّ بعينِه. (بلا هذا كانت الخريطةُ جدولاً ثانياً
         لنفس الأرقام.) */
      const groups = simplification?.selectedImplicants ?? [];
      const groupOf = (minterm: number): number[] =>
        groups.flatMap((implicant, index) => implicant.coveredMinterms.includes(minterm) ? [index] : []);

      if (map && map.available) {
        const view = createKarnaughViewModel(map);
        const scroll = el('div', 'cx-scroll');
        const table = el('table', 'cx-kmap');
        table.dir = view.direction;
        const head = el('tr');
        const corner = el('th', 'cx-kmap-corner');
        /* زاويةٌ على شكل الكتاب: متغيّراتُ الصفوف أسفلَ القُطر ومتغيّراتُ
           الأعمدة أعلاه — لا سطرٌ واحدٌ بشرطةٍ مائلة. */
        corner.appendChild(el('span', 'cx-kmap-colvars', map.columnVariables.join('')));
        corner.appendChild(el('span', 'cx-kmap-rowvars', map.rowVariables.join('')));
        corner.dir = 'ltr';
        head.appendChild(corner);
        /* رؤوسُ الأعمدة والصفوف صنفٌ مستقلّ: هي **عناوينُ رمادِ كود** لا
           قيمُ خانات، وبلا هذا التفريق ذابت في الداكن حتى صار الجدول
           بلا شبكةٍ مقروءة. */
        for (const code of map.columnGrayCodes) head.appendChild(el('th', 'cx-kmap-axis', code));
        const thead = el('thead');
        thead.appendChild(head);
        table.appendChild(thead);
        const tbody = el('tbody');
        for (let row = 0; row < map.rows; row += 1) {
          const tr = el('tr');
          tr.appendChild(el('th', 'cx-kmap-axis', map.rowGrayCodes[row] ?? ''));
          for (let column = 0; column < map.columns; column += 1) {
            const cell = map.cells.find(candidate => candidate.row === row && candidate.column === column);
            const td = el('td', `is-${cell?.value === 1 ? 'high' : cell?.value === 0 ? 'low' : 'unknown'}`);
            /* رقمُ الصغرى في الزاوية كما يرقّم الكتابُ خاناتِه m0..m15 —
               وهو الجسرُ بين صفِّ الجدول وخانة الخريطة. */
            td.appendChild(el('span', 'cx-kmap-index', `m${cell?.minterm ?? 0}`));
            td.appendChild(el('span', 'cx-kmap-bit', String(cell?.value ?? 'X')));
            for (const groupIndex of cell ? groupOf(cell.minterm) : []) {
              td.appendChild(el('span', `cx-kmap-group cx-kmap-group--${groupIndex % 6}`));
            }
            tr.appendChild(td);
          }
          tbody.appendChild(tr);
        }
        table.appendChild(tbody);
        scroll.appendChild(table);
        block.appendChild(scroll);

        if (groups.length > 0 && simplification) {
          const legend = el('div', 'cx-kmap-legend');
          for (const [index, implicant] of groups.entries()) {
            const item = el('span', `cx-legend-item cx-kmap-group--${index % 6}`);
            item.dir = 'ltr';
            item.textContent = termText(implicant.pattern, simplification.variableNames);
            legend.appendChild(item);
          }
          block.appendChild(legend);
        }
      } else {
        /* أكثرُ من ستّة متغيّرات: لا خريطةَ مرئية — والتبسيطُ يستمرّ.
           غيابُ الخريطة يُشرح ولا يُترك فراغاً. */
        block.appendChild(el('p', 'cx-note', text(this.locale,
          'أكثر من ٦ متغيّرات: لا خريطة مرئية، والتبسيط الجبري يستمر.',
          'More than 6 variables: no visual map; the algebraic derivation continues.')));
      }

      if (simplification) block.appendChild(this.buildDerivation(simplification));
      this.body.appendChild(block);
    }
  }

  /**
   * الاشتقاقُ الجبريّ معروضاً: سطرٌ لكل خطوةٍ يحمل **اسمَ القانون**
   * والتعبيرَ بعد تطبيقه. هذا ما نسخ Quine–McCluskey: الطالبُ يقرأ في
   * كتابه هذه القوانينَ بأسمائها، فيرى هنا الطريقَ نفسَه على دائرته.
   */
  private buildDerivation(result: SimplificationResult): HTMLElement {
    const wrapper = el('div', 'cx-derivation');
    const head = el('div', 'cx-derivation-head');
    head.appendChild(el('span', 'cx-derivation-label',
      text(this.locale, 'التبسيط الجبري — خطوة بخطوة', 'Algebraic simplification — step by step')));
    head.appendChild(el('span', 'cx-derivation-count', text(
      this.locale,
      `${result.minterms.length} صغرى · ${result.literalCount} حرفاً في الناتج`,
      `${result.minterms.length} minterms · ${result.literalCount} literals`
    )));
    wrapper.appendChild(head);

    const list = el('ol', 'cx-steps');
    for (const step of result.steps) {
      const item = el('li', `cx-step is-${step.law}`);
      const law = el('span', 'cx-step-law', text(this.locale, LAW_TITLES[step.law].ar, LAW_TITLES[step.law].en));
      item.appendChild(law);
      /* قاعدةُ الموقع: نصٌّ لاتينيٌّ كاملٌ يُقرأ لاتينياً ولو في صفحةٍ
         عربية — والتعبيرُ الجبريُّ لاتينيٌّ كلُّه. */
      const expression = el('code', 'cx-step-expr', step.expression);
      expression.dir = 'ltr';
      item.appendChild(expression);
      const rule = LAW_RULES[step.law];
      if (rule) {
        const hint = el('span', 'cx-step-rule', rule);
        hint.dir = 'ltr';
        item.appendChild(hint);
      }
      list.appendChild(item);
    }
    wrapper.appendChild(list);
    return wrapper;
  }
}

/** أسماءُ القوانين كما تُذكر في الكتاب — عربيّها وإنجليزيّها. */
const LAW_TITLES: Record<SimplificationLaw, { ar: string; en: string }> = {
  'sum-of-minterms': { ar: 'مجموع الصغريات من الجدول', en: 'Sum of minterms from the table' },
  'dont-care': { ar: 'ضمُّ حدود اللامبالاة', en: 'Include don’t-care terms' },
  idempotent: { ar: 'التكرار', en: 'Idempotent law' },
  combining: { ar: 'التوحيد', en: 'Combining' },
  minimal: { ar: 'الصورة الصغرى', en: 'Minimal form' }
};

/** القانونُ نفسُه مكتوباً بالرموز — الطالبُ يطابقه بما في كتابه. */
const LAW_RULES: Partial<Record<SimplificationLaw, string>> = {
  idempotent: 'x + x = x',
  combining: 'xy + xy′ = x',
  'sum-of-minterms': 'F = Σm',
  'dont-care': 'd → 1'
};

/** الحدُّ بتدوين الكتاب — مكرَّرٌ هنا للأسطورة وحدَها. */
function termText(pattern: string, variableNames: readonly string[]): string {
  const compact = variableNames.every(name => name.length === 1);
  const literals = [...pattern].flatMap((bit, index) => {
    if (bit === '-') return [];
    const name = variableNames[index] ?? '?';
    return [bit === '1' ? name : `${name}′`];
  });
  return literals.length === 0 ? '1' : literals.join(compact ? '' : ' · ');
}

/** فهرسُ الصفّ الذي يطابق المدخلات الحالية، أو -1 إن كان فيها مجهول. */
function currentRowIndex(snapshot: EvidenceSnapshot): number {
  const inputIds = snapshot.truthTable.inputNodeIds;
  if (inputIds.length === 0) return -1;
  let index = 0;
  for (const id of inputIds) {
    const value = snapshot.values[id];
    if (value !== 0 && value !== 1) return -1;
    index = index * 2 + value;
  }
  return index;
}
