import type { LogicValue } from './logic.ts';
import type { TruthTable } from './truth-table.ts';

export interface KarnaughCell {
  readonly row: number;
  readonly column: number;
  readonly minterm: number;
  readonly value: LogicValue;
}

export interface KarnaughMap {
  readonly available: boolean;
  readonly variableNames: readonly string[];
  readonly rowVariables: readonly string[];
  readonly columnVariables: readonly string[];
  readonly rowGrayCodes: readonly string[];
  readonly columnGrayCodes: readonly string[];
  readonly rows: number;
  readonly columns: number;
  readonly cells: readonly KarnaughCell[];
  readonly reason?: 'more-than-six-variables';
}

export function grayCode(index: number): number {
  return index ^ (index >> 1);
}

function paddedBinary(value: number, width: number): string {
  return width === 0 ? '' : value.toString(2).padStart(width, '0');
}

export function createKarnaughMap(variableNames: readonly string[], valuesByMinterm: readonly LogicValue[]): KarnaughMap {
  if (variableNames.length > 6) {
    return { available: false, variableNames, rowVariables: [], columnVariables: [], rowGrayCodes: [], columnGrayCodes: [], rows: 0, columns: 0, cells: [], reason: 'more-than-six-variables' };
  }
  const rowVariableCount = Math.floor(variableNames.length / 2);
  const columnVariableCount = variableNames.length - rowVariableCount;
  const rows = 2 ** rowVariableCount;
  const columns = 2 ** columnVariableCount;
  const rowGrayCodes = Array.from({ length: rows }, (_, index) => paddedBinary(grayCode(index), rowVariableCount));
  const columnGrayCodes = Array.from({ length: columns }, (_, index) => paddedBinary(grayCode(index), columnVariableCount));
  const cells: KarnaughCell[] = [];
  for (let row = 0; row < rows; row += 1) {
    for (let column = 0; column < columns; column += 1) {
      const bitString = `${rowGrayCodes[row]}${columnGrayCodes[column]}`;
      const minterm = bitString === '' ? 0 : Number.parseInt(bitString, 2);
      cells.push({ row, column, minterm, value: valuesByMinterm[minterm] ?? 'X' });
    }
  }
  return {
    available: true,
    variableNames,
    rowVariables: variableNames.slice(0, rowVariableCount),
    columnVariables: variableNames.slice(rowVariableCount),
    rowGrayCodes,
    columnGrayCodes,
    rows,
    columns,
    cells
  };
}

export function createKarnaughMapFromTruthTable(
  table: TruthTable,
  outputNodeId: string,
  variableNames: readonly string[] = table.inputNodeIds
): KarnaughMap {
  return createKarnaughMap(variableNames, table.rows.map(row => row.outputs[outputNodeId] ?? 'X'));
}
