import type { WorkspaceNodeV1 } from '../domain/workspace.ts';
import { geometryForComponent, type LocalPoint } from './symbol-geometry.ts';

export const PORT_HIT_TARGET_SIZE = 44;
export const PORT_VISIBLE_RADIUS = 5;

export interface AbsolutePortGeometry {
  readonly id: string;
  readonly center: LocalPoint;
  readonly hitBox: Readonly<{ x: number; y: number; width: number; height: number }>;
}

function absolutePoint(node: WorkspaceNodeV1, localPoint: LocalPoint): LocalPoint {
  return { x: node.position.x + localPoint.x, y: node.position.y + localPoint.y };
}

function port(id: string, center: LocalPoint): AbsolutePortGeometry {
  return {
    id,
    center,
    hitBox: { x: center.x - PORT_HIT_TARGET_SIZE / 2, y: center.y - PORT_HIT_TARGET_SIZE / 2, width: PORT_HIT_TARGET_SIZE, height: PORT_HIT_TARGET_SIZE }
  };
}

export function portGeometryForNode(node: WorkspaceNodeV1): Readonly<{ inputs: readonly AbsolutePortGeometry[]; output: AbsolutePortGeometry }> {
  const geometry = geometryForComponent(node.component, node.inputCount);
  return {
    inputs: geometry.inputPorts.map((input, inputIndex) => port(`in-${inputIndex}`, absolutePoint(node, input))),
    output: port('out', absolutePoint(node, geometry.outputPort))
  };
}

export function nodeBounds(node: WorkspaceNodeV1): Readonly<{ x: number; y: number; width: number; height: number }> {
  const geometry = geometryForComponent(node.component, node.inputCount);
  return { x: node.position.x, y: node.position.y, width: geometry.width, height: geometry.height };
}
