interface PresetNode { readonly id: string; readonly kind: ComponentKind; readonly x: number; readonly y: number; readonly inputs?: number; readonly label?: string }
interface PresetWire { readonly from: string; readonly to: string; readonly port: number }
export interface CircuitPreset { readonly id: string; readonly name: string; readonly artifact: WorkspaceArtifactV1 }

/** فصولُ الكتاب المعتمد (Mano & Ciletti) — القائمةُ تُجمَّع بها. */
export type PresetGroup = 'free' | 'ch2' | 'ch3' | 'ch4';

function createPreset(id: string, name: string, nodes: readonly PresetNode[], wires: readonly PresetWire[]): CircuitPreset {
  const workspaceNodes: WorkspaceNodeV1[] = nodes.map(node => ({
    id: node.id,
    role: expectedRoleForComponent(node.kind),
    component: node.kind,
    label: node.label ?? node.id.toUpperCase(),
    labelPlacement: 'bottom',
    position: { x: node.x, y: node.y },
    inputCount: node.inputs ?? (expectedRoleForComponent(node.kind) === 'input' ? 0 : 1),
    ...(node.kind === 'CONSTANT_0' ? { constantValue: 0 as const } : {}),
    ...(node.kind === 'CONSTANT_1' ? { constantValue: 1 as const } : {}),
    ...(node.kind === 'PROBE' ? { outputDisplay: 'probe' as const } : {}),
    ...(node.kind === 'LED' ? { outputDisplay: 'led' as const } : {})
  }));
  const workspaceWires: WorkspaceWireV1[] = wires.map((wire, index) => ({
    id: `wire-${index + 1}`,
    source: { nodeId: wire.from, portId: 'out' },
    target: { nodeId: wire.to, portId: `in-${wire.port}` as WorkspaceWireV1['target']['portId'] },
    label: '',
    route: { mode: 'orthogonal-auto', waypoints: [] }
  }));
  const now = '2026-08-03T00:00:00Z';
  return { id, name, artifact: {
    schemaVersion: WORKSPACE_SCHEMA_VERSION,
    kind: WORKSPACE_KIND,
    labId: WORKSPACE_LAB_ID,
    artifactId: `preset-${id}`,
    revision: 0,
    title: name,
    createdAt: now,
    updatedAt: now,
    sourcePresetId: id,
    circuit: { width: WORKSPACE_LIMITS.width, height: WORKSPACE_LIMITS.height, nodes: workspaceNodes, wires: workspaceWires },
    session: { inputValues: Object.fromEntries(workspaceNodes.filter(node => node.role === 'input').map(node => [node.id, 0])), viewport: { x: 0, y: 0, zoom: 1 } }
  } };
}

