/**
 * الافتراضُ **مثالٌ عاملٌ لا لوحةٌ فارغة**: أوّلُ ما يراه الطالب دائرةٌ
 * تعمل وجدولُ حقيقتها، فيفهم الغرضَ قبل أن يُطلب منه البناء. البناءُ
 * الحرُّ اختيارٌ صريحٌ من القائمة.
 */
export function presetById(id: string | null): CircuitPreset {
  return CIRCUIT_PRESETS.find(preset => preset.id === id) ?? halfAdder;
}


