import type { LogicBit, WorkspaceArtifactV1 } from '../domain/workspace.ts';
import type { EditorSessionAction } from '../state/session.ts';
import { deriveExpressions } from '../kernel/expressions.ts';
import { evaluateWorkspace } from '../kernel/evaluate.ts';
import { createKarnaughMapFromTruthTable, type KarnaughMap } from '../kernel/karnaugh.ts';
import { simplifyMinterms, type SimplificationResult } from '../kernel/simplify.ts';
import { deriveSignalCone, type SignalCone } from '../kernel/signal-cone.ts';
import { deriveTruthTable, type TruthTable, type TruthRow } from '../kernel/truth-table.ts';
import type { LogicValue } from '../kernel/logic.ts';

export interface EvidenceSnapshot {
  readonly revision: number;
  readonly values: Readonly<Record<string, LogicValue>>;
  readonly expressions: Readonly<Record<string, string>>;
  readonly truthTable: TruthTable;
  readonly karnaughByOutputId: Readonly<Record<string, KarnaughMap>>;
  readonly simplificationByOutputId: Readonly<Record<string, SimplificationResult>>;
  /** تسميةُ العرض لكل عقدة — اسمُ الطالب لا معرّفُ النظام. */
  readonly displayNameByNodeId: Readonly<Record<string, string>>;
}

/**
 * الخريطةُ والجبرُ يُكتبان **بأسماء المدخلات** لا بمعرّفاتها. كانت تُكتب
 * `input-a` في رأس كارنو وفي التعبير المبسَّط، وهو معرّفُ نظامٍ لا اسمُ
 * متغيّر — ولا يشبه شيئاً في الكتاب. وتكرارُ اسمٍ أو خلوُّه يعيد المعرّفَ
 * فلا يلتبس متغيّران.
 */
function displayNames(artifact: WorkspaceArtifactV1): Record<string, string> {
  const counts = new Map<string, number>();
  for (const node of artifact.circuit.nodes) {
    const label = node.label.trim();
    if (label) counts.set(label, (counts.get(label) ?? 0) + 1);
  }
  return Object.fromEntries(artifact.circuit.nodes.map(node => {
    const label = node.label.trim();
    return [node.id, label && counts.get(label) === 1 ? label : node.id];
  }));
}

export function createEvidenceSnapshot(artifact: WorkspaceArtifactV1): EvidenceSnapshot {
  const truthTable = deriveTruthTable(artifact);
  const evaluation = evaluateWorkspace(artifact, artifact.session.inputValues);
  const displayNameByNodeId = displayNames(artifact);
  const variableNames = truthTable.inputNodeIds.map(nodeId => displayNameByNodeId[nodeId] ?? nodeId);
  const karnaughByOutputId: Record<string, KarnaughMap> = {};
  const simplificationByOutputId: Record<string, SimplificationResult> = {};
  for (const outputNodeId of truthTable.outputNodeIds) {
    karnaughByOutputId[outputNodeId] = createKarnaughMapFromTruthTable(truthTable, outputNodeId, variableNames);
    const minterms = truthTable.rows.filter(row => row.outputs[outputNodeId] === 1).map(row => row.index);
    const dontCares = truthTable.rows.filter(row => row.outputs[outputNodeId] === 'X').map(row => row.index);
    simplificationByOutputId[outputNodeId] = simplifyMinterms(variableNames, minterms, dontCares);
  }
  return {
    revision: artifact.revision,
    values: evaluation.values,
    expressions: deriveExpressions(artifact),
    truthTable,
    karnaughByOutputId,
    simplificationByOutputId,
    displayNameByNodeId
  };
}

export function actionsForTruthRow(row: TruthRow): readonly EditorSessionAction[] {
  return Object.entries(row.inputs).map(([nodeId, value]) => ({ type: 'session.set-input', nodeId, value: value as LogicBit }));
}

export function coneForTruthRow(artifact: WorkspaceArtifactV1, outputNodeId: string): SignalCone {
  return deriveSignalCone(artifact, outputNodeId);
}
