import { parseWorkspaceArtifact } from '../domain/parse-workspace.ts';
import {
  WORKSPACE_LIMITS,
  expectedRoleForComponent,
  type ComponentKind,
  type WorkspaceArtifactV1,
  type WorkspaceNodeV1
} from '../domain/workspace.ts';
import type { DocumentValidationResult, ValidationIssue } from './issues.ts';

const oneInputComponents = new Set<ComponentKind>(['BUFFER', 'NOT']);
/* المازجُ يقبل 2^n+n منفذاً (2:1 · 4:1 · 8:1)، والأغلبيةُ عدداً فردياً
   وحدَه — أغلبيةُ عددٍ زوجيٍّ غيرُ معرَّفةٍ عند التعادل. */
const MUX_PORT_COUNTS = [3, 6, 11] as const;
const MAJORITY_PORT_COUNTS = [3, 5, 7] as const;
const variableInputComponents = new Set<ComponentKind>(['AND', 'NAND', 'OR', 'NOR', 'XOR', 'XNOR', 'ODD_PARITY', 'EVEN_PARITY']);

function issue(
  code: ValidationIssue['code'],
  severity: ValidationIssue['severity'],
  params: ValidationIssue['params'] = {},
  location: Pick<ValidationIssue, 'nodeId' | 'portId' | 'wireId' | 'path'> = {}
): ValidationIssue {
  return { code, severity, params, ...location };
}

function expectedInputCount(node: WorkspaceNodeV1): { minimum: number; maximum: number; allowed?: readonly number[] } {
  if (node.role === 'input') return { minimum: 0, maximum: 0 };
  if (node.role === 'output' || oneInputComponents.has(node.component)) return { minimum: 1, maximum: 1 };
  if (node.component === 'MUX') return { minimum: 3, maximum: 11, allowed: MUX_PORT_COUNTS };
  if (node.component === 'MAJORITY') return { minimum: 3, maximum: 7, allowed: MAJORITY_PORT_COUNTS };
  if (variableInputComponents.has(node.component)) return { minimum: 2, maximum: 8 };
  return { minimum: node.inputCount, maximum: node.inputCount };
}

function cycleNodeIds(artifact: WorkspaceArtifactV1): string[] {
  const nodeIds = new Set(artifact.circuit.nodes.map(node => node.id));
  const outgoing = new Map<string, string[]>();
  for (const nodeId of nodeIds) outgoing.set(nodeId, []);
  for (const wire of artifact.circuit.wires) {
    if (nodeIds.has(wire.source.nodeId) && nodeIds.has(wire.target.nodeId)) outgoing.get(wire.source.nodeId)?.push(wire.target.nodeId);
  }
  for (const targets of outgoing.values()) targets.sort((left, right) => left.localeCompare(right));

  const state = new Map<string, 'visiting' | 'visited'>();
  const stack: string[] = [];
  const cyclic = new Set<string>();
  function visit(nodeId: string): void {
    if (state.get(nodeId) === 'visited') return;
    if (state.get(nodeId) === 'visiting') {
      const cycleStart = stack.lastIndexOf(nodeId);
      for (const cycleNodeId of stack.slice(cycleStart)) cyclic.add(cycleNodeId);
      return;
    }
    state.set(nodeId, 'visiting');
    stack.push(nodeId);
    for (const targetNodeId of outgoing.get(nodeId) ?? []) visit(targetNodeId);
    stack.pop();
    state.set(nodeId, 'visited');
  }
  for (const nodeId of [...nodeIds].sort((left, right) => left.localeCompare(right))) visit(nodeId);
  return [...cyclic].sort((left, right) => left.localeCompare(right));
}

export function validateWorkspaceDocument(input: unknown): DocumentValidationResult {
  const parsed = parseWorkspaceArtifact(input);
  if (!parsed.ok) {
    return {
      valid: false,
      issues: parsed.issues.map(domainIssue => issue(domainIssue.code, 'error', { reason: domainIssue.reason, ...domainIssue.params }, { path: domainIssue.path }))
    };
  }
  const artifact = parsed.value;
  const issues: ValidationIssue[] = [];
  const inputs = artifact.circuit.nodes.filter(node => node.role === 'input');
  const outputs = artifact.circuit.nodes.filter(node => node.role === 'output');
  const gates = artifact.circuit.nodes.filter(node => node.role === 'gate');
  /* الحدُّ ثمانيةٌ لأنّ الجدولَ ينمو ٢^ن — فيُحسب **المتغيّراتُ الحرّة**
     وحدَها. الثابتُ ليس متغيّراً ولا يضيف صفّاً واحداً، وعدُّه كان يمنع
     مازجَ 8:1 بمداخلَ ثابتةٍ وهو أوّلُ ما يبنيه الطالبُ ليجرّبه. */
  const freeInputs = inputs.filter(node => node.component !== 'CONSTANT_0' && node.component !== 'CONSTANT_1');
  for (const [kind, count, maximum] of [['input', freeInputs.length, 8], ['output', outputs.length, 8], ['gate', gates.length, 100]] as const) {
    if (count > maximum) issues.push(issue('LIMIT_REACHED', 'error', { kind, count, maximum }));
  }

  const nodeIdCounts = new Map<string, number>();
  const wireIdCounts = new Map<string, number>();
  for (const node of artifact.circuit.nodes) nodeIdCounts.set(node.id, (nodeIdCounts.get(node.id) ?? 0) + 1);
  for (const wire of artifact.circuit.wires) wireIdCounts.set(wire.id, (wireIdCounts.get(wire.id) ?? 0) + 1);
  for (const [nodeId, count] of nodeIdCounts) if (count > 1) issues.push(issue('DUPLICATE_ID', 'error', { kind: 'node', count }, { nodeId }));
  for (const [wireId, count] of wireIdCounts) if (count > 1) issues.push(issue('DUPLICATE_ID', 'error', { kind: 'wire', count }, { wireId }));

  const nodeById = new Map(artifact.circuit.nodes.map(node => [node.id, node]));
  for (const node of artifact.circuit.nodes) {
    const expectedRole = expectedRoleForComponent(node.component);
    if (node.role !== expectedRole) issues.push(issue('ROLE_COMPONENT_MISMATCH', 'error', { expectedRole, actualRole: node.role }, { nodeId: node.id }));
    const arity = expectedInputCount(node);
    const outsideAllowed = arity.allowed ? !arity.allowed.includes(node.inputCount) : false;
    if (node.inputCount < arity.minimum || node.inputCount > arity.maximum || outsideAllowed) {
      issues.push(issue('INVALID_ARITY', 'error', { minimum: arity.minimum, maximum: arity.maximum, actual: node.inputCount }, { nodeId: node.id }));
    }
    if (node.position.x < 0 || node.position.x > WORKSPACE_LIMITS.width || node.position.y < 0 || node.position.y > WORKSPACE_LIMITS.height) {
      issues.push(issue('OUT_OF_BOUNDS', 'error', { x: node.position.x, y: node.position.y }, { nodeId: node.id }));
    }
    if (node.component === 'CONSTANT_0' && node.constantValue !== undefined && node.constantValue !== 0) {
      issues.push(issue('INVALID_COMPONENT_CONFIGURATION', 'error', { expected: 0, actual: node.constantValue }, { nodeId: node.id }));
    }
    if (node.component === 'CONSTANT_1' && node.constantValue !== undefined && node.constantValue !== 1) {
      issues.push(issue('INVALID_COMPONENT_CONFIGURATION', 'error', { expected: 1, actual: node.constantValue }, { nodeId: node.id }));
    }
  }

  const targetCounts = new Map<string, string[]>();
  for (const wire of artifact.circuit.wires) {
    const sourceNode = nodeById.get(wire.source.nodeId);
    const targetNode = nodeById.get(wire.target.nodeId);
    if (!sourceNode || sourceNode.role === 'output' || wire.source.portId !== 'out') {
      issues.push(issue('INVALID_SOURCE', 'error', { reason: !sourceNode ? 'unknown-node' : sourceNode.role === 'output' ? 'output-terminal' : 'invalid-port' }, { nodeId: wire.source.nodeId, portId: wire.source.portId, wireId: wire.id }));
    }
    const targetMatch = /^in-(\d+)$/.exec(wire.target.portId);
    const targetIndex = targetMatch ? Number(targetMatch[1]) : -1;
    if (!targetNode || targetNode.role === 'input' || targetIndex < 0 || targetIndex >= (targetNode?.inputCount ?? 0)) {
      issues.push(issue('INVALID_TARGET', 'error', { reason: !targetNode ? 'unknown-node' : targetNode.role === 'input' ? 'input-terminal' : 'invalid-port' }, { nodeId: wire.target.nodeId, portId: wire.target.portId, wireId: wire.id }));
      continue;
    }
    const targetKey = `${wire.target.nodeId}:${wire.target.portId}`;
    const wireIds = targetCounts.get(targetKey) ?? [];
    wireIds.push(wire.id);
    targetCounts.set(targetKey, wireIds);
  }
  for (const [targetKey, wireIds] of targetCounts) {
    if (wireIds.length <= 1) continue;
    const separatorIndex = targetKey.lastIndexOf(':');
    issues.push(issue('TARGET_OCCUPIED', 'error', { wireIds: wireIds.join('|') }, { nodeId: targetKey.slice(0, separatorIndex), portId: targetKey.slice(separatorIndex + 1) }));
  }

  const connectedTargets = new Set(artifact.circuit.wires.map(wire => `${wire.target.nodeId}:${wire.target.portId}`));
  for (const node of artifact.circuit.nodes.filter(candidate => candidate.role !== 'input')) {
    for (let inputIndex = 0; inputIndex < node.inputCount; inputIndex += 1) {
      const portId = `in-${inputIndex}`;
      if (!connectedTargets.has(`${node.id}:${portId}`)) issues.push(issue('UNCONNECTED_PIN', 'warning', {}, { nodeId: node.id, portId }));
    }
  }

  const cyclicNodeIds = cycleNodeIds(artifact);
  if (cyclicNodeIds.length > 0) issues.push(issue('COMBINATIONAL_CYCLE', 'error', { nodeIds: cyclicNodeIds.join('|') }));
  return { valid: !issues.some(validationIssue => validationIssue.severity === 'error'), artifact, issues };
}
