import type { WorkspaceNodeV1, WorkspacePointV1 } from '../domain/workspace.ts';
import { nodeBounds } from './port-geometry.ts';

export interface SelectionState {
  readonly nodeIds: readonly string[];
  readonly wireIds: readonly string[];
}

export interface SelectionRectangle {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

export const EMPTY_SELECTION: SelectionState = Object.freeze({ nodeIds: [], wireIds: [] });

export function rectangleFromPoints(start: WorkspacePointV1, end: WorkspacePointV1): SelectionRectangle {
  return { x: Math.min(start.x, end.x), y: Math.min(start.y, end.y), width: Math.abs(end.x - start.x), height: Math.abs(end.y - start.y) };
}

function rectanglesIntersect(left: SelectionRectangle, right: SelectionRectangle): boolean {
  return left.x <= right.x + right.width && left.x + left.width >= right.x && left.y <= right.y + right.height && left.y + left.height >= right.y;
}

export function nodesInsideRectangle(nodes: readonly WorkspaceNodeV1[], rectangle: SelectionRectangle): readonly string[] {
  return nodes.filter(node => rectanglesIntersect(rectangle, nodeBounds(node))).map(node => node.id);
}

export function selectOnlyNode(nodeId: string): SelectionState {
  return { nodeIds: [nodeId], wireIds: [] };
}

export function selectOnlyWire(wireId: string): SelectionState {
  return { nodeIds: [], wireIds: [wireId] };
}

export function toggleNode(selection: SelectionState, nodeId: string): SelectionState {
  const nodeIds = selection.nodeIds.includes(nodeId) ? selection.nodeIds.filter(id => id !== nodeId) : [...selection.nodeIds, nodeId];
  return { nodeIds, wireIds: selection.wireIds };
}

export function toggleWire(selection: SelectionState, wireId: string): SelectionState {
  const wireIds = selection.wireIds.includes(wireId) ? selection.wireIds.filter(id => id !== wireId) : [...selection.wireIds, wireId];
  return { nodeIds: selection.nodeIds, wireIds };
}

export function mergeRectangleSelection(selection: SelectionState, nodeIds: readonly string[], additive: boolean): SelectionState {
  return { nodeIds: additive ? [...new Set([...selection.nodeIds, ...nodeIds])] : [...new Set(nodeIds)], wireIds: additive ? selection.wireIds : [] };
}
