import { migrateWorkspaceArtifact } from '../domain/migrate-workspace.ts';
import type { WorkspaceArtifactV1 } from '../domain/workspace.ts';
import { stableJson, verifySha256 } from './checksum.ts';
import { createShareEnvelope, SHARE_KIND, type ShareEnvelope } from './share-envelope.ts';

const textEncoder = new TextEncoder();
const textDecoder = new TextDecoder();

function bytesToBase64Url(bytes: Uint8Array): string {
  let binary = '';
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary).replaceAll('+', '-').replaceAll('/', '_').replace(/=+$/, '');
}

function base64UrlToBytes(value: string): Uint8Array {
  const base64 = value.replaceAll('-', '+').replaceAll('_', '/').padEnd(Math.ceil(value.length / 4) * 4, '=');
  const binary = atob(base64);
  return Uint8Array.from(binary, character => character.charCodeAt(0));
}

export type SharePayload =
  | Readonly<{ mode: 'fragment'; fragment: string; envelope: ShareEnvelope }>
  | Readonly<{ mode: 'json'; json: string; envelope: ShareEnvelope }>;

export type DecodedShare = Readonly<{ ok: true; artifact: WorkspaceArtifactV1 }> | Readonly<{ ok: false; reason: 'invalid' | 'tampered' | 'unsupported' }>;

/**
 * 🔴 الحمولةُ **تُضغط قبل الترميز**. بلا ضغطٍ كان جامعٌ كامل (عشرُ عقد)
 * يتجاوز حدَّ الرابط، فتصير المشاركةُ ميزةً تعمل على أصغرِ مثالٍ وحدَه —
 * وهي بلا قيمة. ووثيقةُ الدائرة **مكرَّرةٌ جداً** (نفسُ المفاتيح في كل
 * عقدةٍ وسلك) فيبتلعها deflate إلى نحو الخُمس.
 *
 * والفكُّ يقبل غيرَ المضغوط أيضاً: روابطُ سبقت هذا التغيير، والملفُّ
 * المصدَّر يحمل نفسَ المظروف نصّاً صريحاً.
 */
async function deflate(bytes: Uint8Array): Promise<Uint8Array | null> {
  if (typeof CompressionStream === 'undefined') return null;
  const stream = new Blob([bytes as BlobPart]).stream().pipeThrough(new CompressionStream('deflate-raw'));
  return new Uint8Array(await new Response(stream).arrayBuffer());
}

async function inflate(bytes: Uint8Array): Promise<Uint8Array | null> {
  if (typeof DecompressionStream === 'undefined') return null;
  try {
    const stream = new Blob([bytes as BlobPart]).stream().pipeThrough(new DecompressionStream('deflate-raw'));
    return new Uint8Array(await new Response(stream).arrayBuffer());
  } catch { return null; }
}

/** حدٌّ يمرّ في تطبيقات المراسلة وحقولِ العناوين بلا قصّ. */
export async function encodeSharePayload(artifact: WorkspaceArtifactV1, maximumFragmentLength = 6000): Promise<SharePayload> {
  const envelope = await createShareEnvelope(artifact);
  const json = stableJson(envelope);
  const raw = textEncoder.encode(json);
  const packed = await deflate(raw);
  const fragment = `circuit=${bytesToBase64Url(packed ?? raw)}`;
  return fragment.length <= maximumFragmentLength ? { mode: 'fragment', fragment, envelope } : { mode: 'json', json: `${json}\n`, envelope };
}

export async function decodeShareEnvelope(input: string, createArtifactId: () => string): Promise<DecodedShare> {
  let candidate: unknown;
  try {
    let payload = input;
    if (input.startsWith('circuit=')) {
      const bytes = base64UrlToBytes(input.slice('circuit='.length));
      /* المضغوطُ أوّلاً ثم الخام: فكُّ ضغطٍ فاشلٌ يعيد `null` ولا يرمي،
         فيمرّ الرابطُ القديمُ كما هو. */
      const unpacked = await inflate(bytes);
      payload = textDecoder.decode(unpacked ?? bytes);
    }
    candidate = JSON.parse(payload);
  } catch { return { ok: false, reason: 'invalid' }; }
  if (!candidate || typeof candidate !== 'object') return { ok: false, reason: 'invalid' };
  const envelope = candidate as Partial<ShareEnvelope>;
  if (envelope.kind !== SHARE_KIND || envelope.version !== 1 || typeof envelope.checksum !== 'string' || !envelope.artifact) return { ok: false, reason: 'invalid' };
  if (!await verifySha256(envelope.artifact, envelope.checksum)) return { ok: false, reason: 'tampered' };
  const migration = migrateWorkspaceArtifact(envelope.artifact);
  if (!migration.ok) return { ok: false, reason: 'unsupported' };
  return { ok: true, artifact: { ...migration.value, artifactId: createArtifactId(), revision: 0, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() } };
}
