import { WORKSPACE_LIMITS, type WorkspacePointV1, type WorkspaceViewportV1 } from '../domain/workspace.ts';

export interface ViewportSize { readonly width: number; readonly height: number }

export function screenToWorkspace(point: WorkspacePointV1, viewport: WorkspaceViewportV1): WorkspacePointV1 {
  return { x: (point.x - viewport.x) / viewport.zoom, y: (point.y - viewport.y) / viewport.zoom };
}

export function workspaceToScreen(point: WorkspacePointV1, viewport: WorkspaceViewportV1): WorkspacePointV1 {
  return { x: point.x * viewport.zoom + viewport.x, y: point.y * viewport.zoom + viewport.y };
}

export function clampZoom(zoom: number): number {
  return Math.min(WORKSPACE_LIMITS.maximumZoom, Math.max(WORKSPACE_LIMITS.minimumZoom, zoom));
}

export function zoomViewportAt(viewport: WorkspaceViewportV1, screenAnchor: WorkspacePointV1, requestedZoom: number): WorkspaceViewportV1 {
  const zoom = clampZoom(requestedZoom);
  const workspaceAnchor = screenToWorkspace(screenAnchor, viewport);
  return { x: screenAnchor.x - workspaceAnchor.x * zoom, y: screenAnchor.y - workspaceAnchor.y * zoom, zoom };
}

export function panViewport(viewport: WorkspaceViewportV1, delta: WorkspacePointV1): WorkspaceViewportV1 {
  return { ...viewport, x: viewport.x + delta.x, y: viewport.y + delta.y };
}

export function fitWorkspaceViewport(container: ViewportSize, padding = 48): WorkspaceViewportV1 {
  const availableWidth = Math.max(1, container.width - padding * 2);
  const availableHeight = Math.max(1, container.height - padding * 2);
  const zoom = clampZoom(Math.min(availableWidth / WORKSPACE_LIMITS.width, availableHeight / WORKSPACE_LIMITS.height));
  return {
    x: (container.width - WORKSPACE_LIMITS.width * zoom) / 2,
    y: (container.height - WORKSPACE_LIMITS.height * zoom) / 2,
    zoom
  };
}

/* ═══ اصطلاحُ العالم — وهو الذي يستعمله المُصيِّر ═══
   الدوالُّ أعلاه تعامل `viewport.x` **إزاحةَ شاشة** (`screen = p*zoom + x`)،
   بينما `canvas-view` يرسم `translate(-x*zoom) scale(zoom)` أي
   `screen = (p - x) * zoom` — فـ`x` عندَه **إحداثيُّ عالمٍ** لأعلى يسار
   الرؤية. خلطُ الاصطلاحين لا يُعطّل التكبير بل يجعله يقذف الدائرةَ خارج
   الإطار، فيبدو للمستخدم أنّ «التكبير لا يعمل» وهو يعمل ويهرب.
   الدوالُّ التالية هي اصطلاحُ العالم صراحةً، والقديمةُ تبقى لمن يستعملها. */

export function worldToScreen(point: WorkspacePointV1, viewport: WorkspaceViewportV1): WorkspacePointV1 {
  return { x: (point.x - viewport.x) * viewport.zoom, y: (point.y - viewport.y) * viewport.zoom };
}

export function screenToWorld(point: WorkspacePointV1, viewport: WorkspaceViewportV1): WorkspacePointV1 {
  return { x: point.x / viewport.zoom + viewport.x, y: point.y / viewport.zoom + viewport.y };
}

/** تكبيرٌ يثبّت النقطةَ التي تحت المؤشّر — بلا تثبيتها يفقد المستخدمُ موضعَه. */
export function zoomAroundPoint(
  viewport: WorkspaceViewportV1,
  screenAnchor: WorkspacePointV1,
  requestedZoom: number
): WorkspaceViewportV1 {
  const zoom = clampZoom(requestedZoom);
  const anchor = screenToWorld(screenAnchor, viewport);
  return { x: anchor.x - screenAnchor.x / zoom, y: anchor.y - screenAnchor.y / zoom, zoom };
}

/**
 * يمنع الانزلاقَ إلى فراغٍ لا نهائيّ: يبقى من مساحة العمل جزءٌ ظاهرٌ
 * دائماً. الهامشُ يسمح بالعمل قربَ الحوافّ بلا أن تُفقد اللوحةُ كلُّها.
 */
export function clampPan(
  viewport: WorkspaceViewportV1,
  container: ViewportSize,
  margin = 240
): WorkspaceViewportV1 {
  const visibleWidth = container.width / viewport.zoom;
  const visibleHeight = container.height / viewport.zoom;
  const minimumX = -margin;
  const minimumY = -margin;
  const maximumX = Math.max(minimumX, WORKSPACE_LIMITS.width + margin - visibleWidth);
  const maximumY = Math.max(minimumY, WORKSPACE_LIMITS.height + margin - visibleHeight);
  return {
    zoom: viewport.zoom,
    x: Math.min(Math.max(viewport.x, minimumX), maximumX),
    y: Math.min(Math.max(viewport.y, minimumY), maximumY)
  };
}

export function wheelZoomFactor(deltaY: number): number {
  return Math.exp(-deltaY * 0.0015);
}

export function pinchZoom(viewport: WorkspaceViewportV1, screenAnchor: WorkspacePointV1, initialDistance: number, currentDistance: number): WorkspaceViewportV1 {
  if (initialDistance <= 0 || currentDistance <= 0) return viewport;
  return zoomViewportAt(viewport, screenAnchor, viewport.zoom * currentDistance / initialDistance);
}
