import type { LogicBit, WorkspaceArtifactV1, WorkspaceNodeV1, WorkspaceWireV1 } from '../domain/workspace.ts';
import { createGraphPlan, type GraphIssue } from './graph.ts';
import { evaluateLogicComponent, type LogicValue } from './logic.ts';

export type EvaluationIssueCode = 'INVALID_SOURCE_PORT' | 'INVALID_TARGET_PORT' | 'MULTIPLE_WIRES_TO_PORT';

export interface EvaluationIssue {
  readonly code: EvaluationIssueCode;
  readonly wireIds: readonly string[];
  readonly nodeId: string;
  readonly portId: string;
}

export interface WorkspaceEvaluation {
  readonly values: Readonly<Record<string, LogicValue>>;
  readonly orderedNodeIds: readonly string[];
  readonly graphIssues: readonly GraphIssue[];
  readonly evaluationIssues: readonly EvaluationIssue[];
}

function portIndex(portId: string): number | null {
  const match = /^in-(\d+)$/.exec(portId);
  return match ? Number(match[1]) : null;
}

function inputValueForNode(node: WorkspaceNodeV1, assignment: Readonly<Record<string, LogicBit>>): LogicValue {
  if (node.component === 'CONSTANT_0') return 0;
  if (node.component === 'CONSTANT_1') return 1;
  return assignment[node.id] ?? 'X';
}

function orderedInputs(
  node: WorkspaceNodeV1,
  wires: readonly WorkspaceWireV1[],
  values: Readonly<Record<string, LogicValue>>,
  issues: EvaluationIssue[]
): LogicValue[] {
  const wireByPort = new Map<number, WorkspaceWireV1[]>();
  for (const wire of wires) {
    if (wire.source.portId !== 'out') {
      issues.push({ code: 'INVALID_SOURCE_PORT', wireIds: [wire.id], nodeId: wire.source.nodeId, portId: wire.source.portId });
    }
    const targetPortIndex = portIndex(wire.target.portId);
    if (targetPortIndex === null) {
      issues.push({ code: 'INVALID_TARGET_PORT', wireIds: [wire.id], nodeId: node.id, portId: wire.target.portId });
      continue;
    }
    const candidates = wireByPort.get(targetPortIndex) ?? [];
    candidates.push(wire);
    wireByPort.set(targetPortIndex, candidates);
  }

  return Array.from({ length: node.inputCount }, (_, inputIndex) => {
    const candidates = wireByPort.get(inputIndex) ?? [];
    if (candidates.length !== 1) {
      if (candidates.length > 1) {
        issues.push({ code: 'MULTIPLE_WIRES_TO_PORT', wireIds: candidates.map(wire => wire.id), nodeId: node.id, portId: `in-${inputIndex}` });
      }
      return 'X';
    }
    return values[candidates[0].source.nodeId] ?? 'X';
  });
}

export function evaluateWorkspace(
  artifact: WorkspaceArtifactV1,
  assignment: Readonly<Record<string, LogicBit>> = artifact.session.inputValues
): WorkspaceEvaluation {
  const graphPlan = createGraphPlan(artifact);
  const values: Record<string, LogicValue> = {};
  const evaluationIssues: EvaluationIssue[] = [];
  const nodeById = new Map(artifact.circuit.nodes.map(node => [node.id, node]));

  for (const nodeId of graphPlan.orderedNodeIds) {
    const node = nodeById.get(nodeId);
    if (!node) continue;
    if (node.role === 'input') {
      values[node.id] = inputValueForNode(node, assignment);
      continue;
    }
    const inputs = orderedInputs(node, graphPlan.incomingWires.get(node.id) ?? [], values, evaluationIssues);
    values[node.id] = evaluateLogicComponent(node.component, inputs);
  }
  for (const nodeId of graphPlan.cycleNodeIds) values[nodeId] = 'X';

  return {
    values,
    orderedNodeIds: graphPlan.orderedNodeIds,
    graphIssues: graphPlan.issues,
    evaluationIssues
  };
}
