import type { ComponentKind, LogicBit } from '../domain/workspace.ts';

export type LogicValue = LogicBit | 'X';

export function invertLogic(value: LogicValue): LogicValue {
  if (value === 'X') return 'X';
  return value === 1 ? 0 : 1;
}

function andValues(values: readonly LogicValue[]): LogicValue {
  if (values.some(value => value === 0)) return 0;
  return values.every(value => value === 1) ? 1 : 'X';
}

function orValues(values: readonly LogicValue[]): LogicValue {
  if (values.some(value => value === 1)) return 1;
  return values.every(value => value === 0) ? 0 : 'X';
}

function xorValues(values: readonly LogicValue[]): LogicValue {
  if (values.some(value => value === 'X')) return 'X';
  return values.reduce<number>((parity, value) => parity ^ Number(value), 0) as LogicBit;
}

function majorityValue(values: readonly LogicValue[]): LogicValue {
  const required = Math.floor(values.length / 2) + 1;
  const ones = values.filter(value => value === 1).length;
  const zeros = values.filter(value => value === 0).length;
  if (ones >= required) return 1;
  if (zeros >= required) return 0;
  return 'X';
}

export function evaluateLogicComponent(
  component: ComponentKind,
  inputs: readonly LogicValue[],
  inputValue: LogicValue = 'X'
): LogicValue {
  switch (component) {
    case 'SWITCH':
    case 'BUTTON':
      return inputValue;
    case 'CONSTANT_0':
      return 0;
    case 'CONSTANT_1':
      return 1;
    case 'PROBE':
    case 'LED':
    case 'BUFFER':
      return inputs[0] ?? 'X';
    case 'NOT':
      return invertLogic(inputs[0] ?? 'X');
    case 'AND':
      return andValues(inputs);
    case 'NAND':
      return invertLogic(andValues(inputs));
    case 'OR':
      return orValues(inputs);
    case 'NOR':
      return invertLogic(orValues(inputs));
    case 'XOR':
    case 'ODD_PARITY':
      return xorValues(inputs);
    case 'XNOR':
    case 'EVEN_PARITY':
      return invertLogic(xorValues(inputs));
    case 'MUX': {
      /* مازجٌ عامّ: 2^n مدخلَ بيانات ثم n مُحدِّداً في آخر المنافذ،
         أوّلُ المحدِّدات أقلُّها وزناً — عُرفُ الكتاب. الترتيبُ يجعل
         توسيعَ 2:1 إلى 4:1 إضافةَ منافذَ في الذيل لا إعادةَ توصيل. */
      const selectCount = muxSelectCount(inputs.length);
      const dataCount = 2 ** selectCount;
      let index = 0;
      for (let bit = 0; bit < selectCount; bit += 1) {
        const select = inputs[dataCount + bit] ?? 'X';
        /* مُحدِّدٌ مجهول: النتيجةُ معروفةٌ فقط إن اتّفقت كلُّ المداخل
           التي قد يشير إليها — وإلا فهي مجهولةٌ بحقّ. */
        if (select !== 0 && select !== 1) {
          const data = inputs.slice(0, dataCount);
          return data.every(value => value === data[0]) ? (data[0] ?? 'X') : 'X';
        }
        index += select << bit;
      }
      return inputs[index] ?? 'X';
    }
    case 'MAJORITY':
      return majorityValue(inputs);
  }
}

/** عددُ محدِّدات مازجٍ بعدد منافذَ كليّ: 3⇒1 · 6⇒2 · 11⇒3 · 20⇒4. */
export function muxSelectCount(totalPorts: number): number {
  let selectCount = 1;
  while (2 ** selectCount + selectCount < totalPorts) selectCount += 1;
  return selectCount;
}
