import type { LabLocale } from './messages.ts';

const WORKER_ENDPOINT = 'https://gardin-main.xxli50xx.workers.dev';
const DEV_ENDPOINT = '/api/ai';
const LOCAL_HOSTS = new Set(['localhost', '127.0.0.1', '[::1]', '']);

/** حصّةُ الطالب: شرحٌ أوّلُ مخزَّن + إعادتان لكل مثالٍ ولكل لغة. */
export const REGENERATION_ALLOWANCE = 2;

export function explainEndpoint(): string {
  return LOCAL_HOSTS.has(location.hostname) ? DEV_ENDPOINT : WORKER_ENDPOINT;
}

export interface ExplainContext {
  readonly presetId: string;
  readonly presetName: string;
  readonly chapter: string;
  readonly variableNames: readonly string[];
  readonly outputNames: readonly string[];
  /** صفوفُ الجدول بصيغةٍ مضغوطة: `01 → 1 0`. */
  readonly truthRows: readonly string[];
  /** التعبيرُ المبسَّط لكل مخرَج بتدوين الكتاب. */
  readonly expressions: readonly string[];
  readonly gateSummary: string;
}

/* ── الكاش والحصّة ─────────────────────────────────────────────
   المفتاحُ يحمل **اللغة**: بدونها يعطي كاشٌ عربيٌّ شرحاً عربياً لصفحةٍ
   إنجليزية. (فخٌّ متوقَّعٌ سُجِّل قبل البناء ثم وقع فعلاً في المودلات.) */

const cacheKey = (presetId: string, locale: LabLocale): string => `garden_labs_ai_${presetId}_${locale}`;
const usesKey = (presetId: string, locale: LabLocale): string => `garden_labs_ai_uses_${presetId}_${locale}`;

function safeStorage(): Storage | null {
  try {
    localStorage.setItem('garden_labs_probe', '1');
    localStorage.removeItem('garden_labs_probe');
    return localStorage;
  } catch { return null; }
}

export function readCachedExplanation(presetId: string, locale: LabLocale): string | null {
  return safeStorage()?.getItem(cacheKey(presetId, locale)) ?? null;
}

export function writeCachedExplanation(presetId: string, locale: LabLocale, text: string): void {
  try { safeStorage()?.setItem(cacheKey(presetId, locale), text); } catch { /* الشرحُ يُعرض ولو لم يُخزَّن */ }
}

export function regenerationsUsed(presetId: string, locale: LabLocale): number {
  const raw = safeStorage()?.getItem(usesKey(presetId, locale));
  const value = Number(raw);
  return Number.isFinite(value) && value > 0 ? Math.min(value, REGENERATION_ALLOWANCE) : 0;
}

export function countRegeneration(presetId: string, locale: LabLocale): void {
  try {
    safeStorage()?.setItem(usesKey(presetId, locale), String(regenerationsUsed(presetId, locale) + 1));
  } catch { /* العدُّ تحسينٌ لا شرط */ }
}

/* ── الرسائل ───────────────────────────────────────────────── */

/**
 * رسالةُ النظام تحمل **الدائرةَ نفسَها**، وتقيّد الشكل: مصطلحاتُ
 * البوابات إنجليزيةٌ دائماً ولو كان الشرحُ عربياً (عُرفُ الموقع)، والطولُ
 * محدودٌ فلا يتحوّل الشرحُ إلى فصلٍ يهرب منه الطالب.
 */
export function buildExplainMessages(context: ExplainContext, locale: LabLocale): { role: string; content: string }[] {
  const facts = [
    `Example: ${context.presetName}`,
    `Textbook chapter: ${context.chapter}`,
    `Inputs: ${context.variableNames.join(', ') || '—'}`,
    `Outputs: ${context.outputNames.join(', ') || '—'}`,
    `Gates used: ${context.gateSummary}`,
    `Simplified expressions: ${context.expressions.join('  |  ') || '—'}`,
    'Truth table:',
    ...context.truthRows
  ].join('\n');

  const system = locale === 'ar'
    ? [
      'أنت شارحٌ في «الحديقة الرقمية»، منصّةٍ تعليمية لطلاب حاسب في الجامعة السعودية الإلكترونية.',
      'المقرَّر CS231 (المنطق الرقمي)، والكتابُ المعتمد Mano & Ciletti — Digital Design.',
      'تشرح **دائرةً بعينها** أُعطيت لك ببياناتها الكاملة. لا تخترع بوابةً ولا صفّاً غيرَ ما أُعطيت.',
      'اكتب بالعربية الفصحى، و**أسماءُ البوابات والمتغيّرات تبقى إنجليزيةً كما هي** (AND · XOR · Cin).',
      'الشكل، بهذا الترتيب وبعناوين قصيرة:',
      '## الفكرة — سطران يقولان ما تفعله هذه الدائرة.',
      '## كيف تعمل — تتبّعُ الإشارة من المدخل إلى المخرج عبر بواباتها هي.',
      '## من الواقع — مثالٌ ملموسٌ واحدٌ يستعمل هذه الدائرة فعلاً.',
      '## في الكتاب — أين يقع هذا في المقرَّر وبأي اسمٍ يُذكر.',
      '## تحقّق — سؤالٌ واحدٌ قصيرٌ يجيب عنه الطالب بتشغيل المفاتيح.',
      'لا تتجاوز ٣٥٠ كلمة. لا مقدّمات ولا اعتذارات ولا تكرارٌ لما في الجدول.'
    ].join('\n')
    : [
      'You explain circuits on Digital Garden, a learning platform for computer-science students at Saudi Electronic University.',
      'The course is CS231 (Digital Logic); the set textbook is Mano & Ciletti, Digital Design.',
      'You are explaining **one specific circuit** whose full data is given. Never invent a gate or a row you were not given.',
      'Structure, in this order, with short headings:',
      '## The idea — two lines on what this circuit does.',
      '## How it works — trace the signal from input to output through its actual gates.',
      '## In the real world — one concrete use of this exact circuit.',
      '## In the textbook — where this sits in the course and what it is called.',
      '## Check yourself — one short question the student answers by flipping the switches.',
      'Stay under 350 words. No preamble, no apologies, no restating the table.'
    ].join('\n');

  return [
    { role: 'system', content: system },
    { role: 'user', content: facts }
  ];
}

/* ── النداء ────────────────────────────────────────────────── */

export type ExplainResult =
  | Readonly<{ ok: true; text: string }>
  | Readonly<{ ok: false; reason: 'offline' | 'unavailable' | 'empty' }>;

/**
 * بثٌّ بصيغة SSE من OpenAI. `reasoning_content` يأتي أوّلاً (النموذج
 * مفكِّر) فيُعرض مؤشّرَ «يفكّر» لا نصّاً — نصُّ التفكير ليس شرحاً.
 * وإن ردّ الخادمُ JSON عادياً (ووركرٌ قديم) نقرأه دفعةً واحدة.
 */
export async function streamExplanation(
  messages: readonly { role: string; content: string }[],
  onDelta: (textSoFar: string) => void,
  onThinking: () => void
): Promise<ExplainResult> {
  let response: Response;
  try {
    response = await fetch(explainEndpoint(), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ messages, max_tokens: 1200, stream: true })
    });
  } catch {
    return { ok: false, reason: 'offline' };
  }
  if (!response.ok) return { ok: false, reason: 'unavailable' };

  const contentType = response.headers.get('Content-Type') ?? '';
  if (!contentType.includes('text/event-stream') || !response.body) {
    try {
      const payload = await response.json() as { choices?: { message?: { content?: string } }[] };
      const text = payload.choices?.[0]?.message?.content ?? '';
      if (!text.trim()) return { ok: false, reason: 'empty' };
      onDelta(text);
      return { ok: true, text };
    } catch {
      return { ok: false, reason: 'unavailable' };
    }
  }

  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';
  let full = '';
  let thinkingAnnounced = false;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    /* الحدُّ سطرٌ فارغٌ بين الأحداث، والقطعةُ قد تنتهي في منتصف حدث ⇒
       يُحتفظ بالبقيّة للقراءة التالية. تجزئةُ السطور بلا هذا تُنتج
       JSON مبتوراً يُرمى صامتاً فيبدو البثُّ متقطّعاً. */
    const events = buffer.split('\n\n');
    buffer = events.pop() ?? '';
    for (const event of events) {
      for (const line of event.split('\n')) {
        if (!line.startsWith('data:')) continue;
        const payload = line.slice(5).trim();
        if (!payload || payload === '[DONE]') continue;
        try {
          const parsed = JSON.parse(payload) as { choices?: { delta?: { content?: string; reasoning_content?: string } }[] };
          const delta = parsed.choices?.[0]?.delta;
          if (!delta) continue;
          if (delta.reasoning_content && !full && !thinkingAnnounced) {
            thinkingAnnounced = true;
            onThinking();
          }
          if (delta.content) {
            full += delta.content;
            onDelta(full);
          }
        } catch { /* قطعةٌ غيرُ مكتملة — تُتجاهل */ }
      }
    }
  }
  if (!full.trim()) return { ok: false, reason: 'empty' };
  return { ok: true, text: full };
}

/* ── العرض ─────────────────────────────────────────────────── */

/**
 * ⚠️ نصُّ النموذج **لا يُحقن HTML بأي حال**: يُبنى DOM بالنصّ الخالص،
 * ولا يُفهم من العلامات إلا ما نعرفه (`## عنوان` و`- بند` و`**غليظ**`).
 * ناتجُ نموذجٍ يمرّ عبر `innerHTML` ثغرةٌ مفتوحة مهما بدا بريئاً.
 */
export function renderExplanation(text: string): DocumentFragment {
  const fragment = document.createDocumentFragment();
  let list: HTMLUListElement | null = null;
  for (const rawLine of text.split('\n')) {
    const line = rawLine.trim();
    if (!line) { list = null; continue; }
    if (line.startsWith('#')) {
      list = null;
      const heading = document.createElement('h4');
      heading.className = 'cx-ai-h';
      heading.textContent = line.replace(/^#+\s*/, '');
      fragment.appendChild(heading);
      continue;
    }
    if (/^[-*•]\s+/.test(line)) {
      if (!list) {
        list = document.createElement('ul');
        list.className = 'cx-ai-list';
        fragment.appendChild(list);
      }
      const item = document.createElement('li');
      appendInline(item, line.replace(/^[-*•]\s+/, ''));
      list.appendChild(item);
      continue;
    }
    list = null;
    const paragraph = document.createElement('p');
    paragraph.className = 'cx-ai-p';
    appendInline(paragraph, line);
    fragment.appendChild(paragraph);
  }
  return fragment;
}

function appendInline(target: HTMLElement, text: string): void {
  for (const [index, chunk] of text.split('**').entries()) {
    if (!chunk) continue;
    if (index % 2 === 1) {
      const strong = document.createElement('strong');
      strong.textContent = chunk;
      target.appendChild(strong);
    } else {
      target.appendChild(document.createTextNode(chunk));
    }
  }
}
