import type { WorkspacePointV1 } from '../domain/workspace.ts';

export const ROUTER_GRID_SIZE = 20;
export const ROUTER_CLEARANCE = 20;
export const ROUTER_PORT_STUB = 20;

export interface RouterObstacle {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

export interface OrthogonalRouteRequest {
  readonly source: WorkspacePointV1;
  readonly target: WorkspacePointV1;
  readonly obstacles: readonly RouterObstacle[];
  readonly pinnedWaypoints?: readonly WorkspacePointV1[];
  readonly bounds: Readonly<{ width: number; height: number }>;
}

export interface OrthogonalRouteResult {
  readonly points: readonly WorkspacePointV1[];
  readonly visitedCells: number;
  readonly found: boolean;
}

interface GridPoint { readonly column: number; readonly row: number }
interface QueueEntry { readonly point: GridPoint; readonly f: number; readonly h: number }

const key = (point: GridPoint): string => `${point.column}:${point.row}`;
const manhattan = (a: GridPoint, b: GridPoint): number => Math.abs(a.column - b.column) + Math.abs(a.row - b.row);
const snap = (value: number): number => Math.round(value / ROUTER_GRID_SIZE) * ROUTER_GRID_SIZE;
const toGrid = (point: WorkspacePointV1): GridPoint => ({ column: Math.round(point.x / ROUTER_GRID_SIZE), row: Math.round(point.y / ROUTER_GRID_SIZE) });
const fromGrid = (point: GridPoint): WorkspacePointV1 => ({ x: point.column * ROUTER_GRID_SIZE, y: point.row * ROUTER_GRID_SIZE });

function queueCompare(left: QueueEntry, right: QueueEntry): number {
  return left.f - right.f || left.h - right.h || left.point.row - right.point.row || left.point.column - right.point.column;
}

function heapPush(heap: QueueEntry[], entry: QueueEntry): void {
  heap.push(entry);
  let index = heap.length - 1;
  while (index > 0) {
    const parent = Math.floor((index - 1) / 2);
    if (queueCompare(heap[parent]!, heap[index]!) <= 0) break;
    [heap[parent], heap[index]] = [heap[index]!, heap[parent]!];
    index = parent;
  }
}

function heapPop(heap: QueueEntry[]): QueueEntry | undefined {
  const first = heap[0];
  const last = heap.pop();
  if (!first || !last || heap.length === 0) return first;
  heap[0] = last;
  let index = 0;
  while (true) {
    const left = index * 2 + 1; const right = left + 1;
    if (left >= heap.length) break;
    const smallest = right < heap.length && queueCompare(heap[right]!, heap[left]!) < 0 ? right : left;
    if (queueCompare(heap[index]!, heap[smallest]!) <= 0) break;
    [heap[index], heap[smallest]] = [heap[smallest]!, heap[index]!];
    index = smallest;
  }
  return first;
}

function insideObstacle(point: WorkspacePointV1, obstacle: RouterObstacle): boolean {
  return point.x >= obstacle.x - ROUTER_CLEARANCE
    && point.x <= obstacle.x + obstacle.width + ROUTER_CLEARANCE
    && point.y >= obstacle.y - ROUTER_CLEARANCE
    && point.y <= obstacle.y + obstacle.height + ROUTER_CLEARANCE;
}

function isBlocked(point: GridPoint, obstacles: readonly RouterObstacle[]): boolean {
  const workspacePoint = fromGrid(point);
  return obstacles.some(obstacle => insideObstacle(workspacePoint, obstacle));
}

function segmentIsClear(start: WorkspacePointV1, end: WorkspacePointV1, obstacles: readonly RouterObstacle[]): boolean {
  return obstacles.every(obstacle => {
    const left = obstacle.x - ROUTER_CLEARANCE;
    const right = obstacle.x + obstacle.width + ROUTER_CLEARANCE;
    const top = obstacle.y - ROUTER_CLEARANCE;
    const bottom = obstacle.y + obstacle.height + ROUTER_CLEARANCE;
    if (start.y === end.y) {
      const minimumX = Math.min(start.x, end.x); const maximumX = Math.max(start.x, end.x);
      return start.y < top || start.y > bottom || maximumX < left || minimumX > right;
    }
    const minimumY = Math.min(start.y, end.y); const maximumY = Math.max(start.y, end.y);
    return start.x < left || start.x > right || maximumY < top || minimumY > bottom;
  });
}

function fastRoute(start: WorkspacePointV1, target: WorkspacePointV1, obstacles: readonly RouterObstacle[]): readonly WorkspacePointV1[] | null {
  const middleX = snap((start.x + target.x) / 2);
  const middleY = snap((start.y + target.y) / 2);
  const candidates: readonly (readonly WorkspacePointV1[])[] = [
    [start, { x: target.x, y: start.y }, target],
    [start, { x: start.x, y: target.y }, target],
    [start, { x: middleX, y: start.y }, { x: middleX, y: target.y }, target],
    [start, { x: start.x, y: middleY }, { x: target.x, y: middleY }, target]
  ];
  return candidates.find(points => points.every((point, index) => index === 0 || segmentIsClear(points[index - 1]!, point, obstacles))) ?? null;
}

function reconstruct(cameFrom: ReadonlyMap<string, GridPoint>, current: GridPoint): WorkspacePointV1[] {
  const result: GridPoint[] = [current];
  let cursor = current;
  while (cameFrom.has(key(cursor))) {
    cursor = cameFrom.get(key(cursor))!;
    result.push(cursor);
  }
  return result.reverse().map(fromGrid);
}

function routeGridLeg(startPoint: WorkspacePointV1, targetPoint: WorkspacePointV1, request: OrthogonalRouteRequest): OrthogonalRouteResult {
  const start = toGrid(startPoint);
  const target = toGrid(targetPoint);
  const maximumColumn = Math.floor(request.bounds.width / ROUTER_GRID_SIZE);
  const maximumRow = Math.floor(request.bounds.height / ROUTER_GRID_SIZE);
  const open: QueueEntry[] = [];
  heapPush(open, { point: start, f: manhattan(start, target), h: manhattan(start, target) });
  const closed = new Set<string>();
  const cameFrom = new Map<string, GridPoint>();
  const gScore = new Map<string, number>([[key(start), 0]]);
  const fScore = new Map<string, number>([[key(start), manhattan(start, target)]]);
  let visitedCells = 0;

  while (open.length > 0) {
    const entry = heapPop(open)!;
    const current = entry.point;
    if (closed.has(key(current))) continue;
    closed.add(key(current));
    visitedCells += 1;

    if (current.column === target.column && current.row === target.row) {
      return { points: reconstruct(cameFrom, current), visitedCells, found: true };
    }

    const neighbors: readonly GridPoint[] = [
      { column: current.column + 1, row: current.row },
      { column: current.column, row: current.row + 1 },
      { column: current.column, row: current.row - 1 },
      { column: current.column - 1, row: current.row }
    ];

    for (const neighbor of neighbors) {
      if (neighbor.column < 0 || neighbor.row < 0 || neighbor.column > maximumColumn || neighbor.row > maximumRow) continue;
      if (key(neighbor) !== key(target) && isBlocked(neighbor, request.obstacles)) continue;
      const tentativeScore = (gScore.get(key(current)) ?? Infinity) + 1;
      if (tentativeScore >= (gScore.get(key(neighbor)) ?? Infinity)) continue;
      cameFrom.set(key(neighbor), current);
      gScore.set(key(neighbor), tentativeScore);
      const h = manhattan(neighbor, target);
      const f = tentativeScore + h;
      fScore.set(key(neighbor), f);
      heapPush(open, { point: neighbor, f, h });
    }
  }

  return { points: [startPoint, targetPoint], visitedCells, found: false };
}

export function simplifyOrthogonalPoints(points: readonly WorkspacePointV1[], protectedPoints: readonly WorkspacePointV1[] = []): readonly WorkspacePointV1[] {
  const protectedKeys = new Set(protectedPoints.map(point => `${point.x}:${point.y}`));
  const deduplicated = points.filter((point, index) => index === 0 || point.x !== points[index - 1]!.x || point.y !== points[index - 1]!.y);
  if (deduplicated.length <= 2) return deduplicated;
  return deduplicated.filter((point, index) => {
    if (index === 0 || index === deduplicated.length - 1) return true;
    if (protectedKeys.has(`${point.x}:${point.y}`)) return true;
    const previous = deduplicated[index - 1]!;
    const next = deduplicated[index + 1]!;
    return !((previous.x === point.x && point.x === next.x) || (previous.y === point.y && point.y === next.y));
  });
}

function routeLegs(anchors: readonly WorkspacePointV1[], request: OrthogonalRouteRequest): OrthogonalRouteResult {
  const points: WorkspacePointV1[] = [];
  let visitedCells = 0;
  let found = true;
  for (let index = 1; index < anchors.length; index += 1) {
    const leg = routeGridLeg(anchors[index - 1]!, anchors[index]!, request);
    visitedCells += leg.visitedCells;
    found = found && leg.found;
    const simplifiedLeg = simplifyOrthogonalPoints(leg.points);
    points.push(...(index === 1 ? simplifiedLeg : simplifiedLeg.slice(1)));
  }
  return { points, visitedCells, found };
}

export function routeOrthogonal(request: OrthogonalRouteRequest): OrthogonalRouteResult {
  const sourceStub = { x: request.source.x + ROUTER_PORT_STUB, y: request.source.y };
  const sourceTurn = { x: snap(sourceStub.x), y: sourceStub.y };
  const sourceGrid = { x: sourceTurn.x, y: snap(sourceStub.y) };
  const targetStub = { x: request.target.x - ROUTER_PORT_STUB, y: request.target.y };
  const targetTurn = { x: snap(targetStub.x), y: targetStub.y };
  const targetGrid = { x: targetTurn.x, y: snap(targetStub.y) };
  const pinned = (request.pinnedWaypoints ?? []).map(point => ({ x: snap(point.x), y: snap(point.y) }));
  const quickPoints = pinned.length === 0 ? fastRoute(sourceGrid, targetGrid, request.obstacles) : null;
  const middle = quickPoints ? { points: quickPoints, visitedCells: 0, found: true } : routeLegs([sourceGrid, ...pinned, targetGrid], request);
  return {
    points: simplifyOrthogonalPoints([
      request.source,
      sourceStub,
      sourceTurn,
      sourceGrid,
      ...middle.points.slice(1, -1),
      targetGrid,
      targetTurn,
      targetStub,
      request.target
    ], pinned),
    visitedCells: middle.visitedCells,
    found: middle.found
  };
}

export function isOrthogonalPath(points: readonly WorkspacePointV1[]): boolean {
  return points.every((point, index) => index === 0 || point.x === points[index - 1]!.x || point.y === points[index - 1]!.y);
}
