import { migrateWorkspaceArtifact } from '../domain/migrate-workspace.ts';
import type { WorkspaceArtifactV1 } from '../domain/workspace.ts';
import { sha256, stableJson, verifySha256 } from './checksum.ts';

export const EXPORT_KIND = 'digital-garden-lab-export' as const;

export interface ArtifactExportEnvelope {
  readonly kind: typeof EXPORT_KIND;
  readonly exportedAt: string;
  readonly checksum: string;
  readonly artifact: WorkspaceArtifactV1;
}

export type ImportPreview =
  | Readonly<{ ok: true; envelope: ArtifactExportEnvelope; artifact: WorkspaceArtifactV1 }>
  | Readonly<{ ok: false; reason: 'invalid-json' | 'invalid-envelope' | 'checksum-mismatch' | 'unsupported-or-corrupted' }>;

export async function createExportEnvelope(artifact: WorkspaceArtifactV1, exportedAt: string): Promise<ArtifactExportEnvelope> {
  return { kind: EXPORT_KIND, exportedAt, checksum: await sha256(artifact), artifact };
}

export async function serializeArtifactExport(artifact: WorkspaceArtifactV1, exportedAt: string): Promise<string> {
  return `${stableJson(await createExportEnvelope(artifact, exportedAt))}\n`;
}

export async function previewArtifactImport(serialized: string): Promise<ImportPreview> {
  let input: unknown;
  try { input = JSON.parse(serialized); } catch { return { ok: false, reason: 'invalid-json' }; }
  if (!input || typeof input !== 'object') return { ok: false, reason: 'invalid-envelope' };
  const envelope = input as Partial<ArtifactExportEnvelope>;
  if (envelope.kind !== EXPORT_KIND || typeof envelope.exportedAt !== 'string' || typeof envelope.checksum !== 'string' || !envelope.artifact) return { ok: false, reason: 'invalid-envelope' };
  if (!await verifySha256(envelope.artifact, envelope.checksum)) return { ok: false, reason: 'checksum-mismatch' };
  const migration = migrateWorkspaceArtifact(envelope.artifact);
  if (!migration.ok) return { ok: false, reason: 'unsupported-or-corrupted' };
  return { ok: true, envelope: envelope as ArtifactExportEnvelope, artifact: migration.value };
}
