/* ═══════════════════════════════════════════════════════════════
   auto-layout.ts — إعادةُ توزيع الرسم توزيعاً مقروءاً
   ═══════════════════════════════════════════════════════════════
   الطالبُ يبني بالتجربة فيتراكم الرسمُ متشابكاً، أو يستورد آلةً لم
   يرسمها. زرٌّ واحدٌ يعيد ترتيبَها كما ترسم الكتبُ الدوائر:

   • **الأعمدةُ عمقُ الإشارة.** عمقُ العقدة = أطولُ مسارٍ من مدخلٍ إليها،
     فتقع المداخلُ يساراً والمخارجُ يميناً ولا يعود سلكٌ إلى الوراء أبداً
     (الدائرةُ توافقيةٌ فالبيانُ لا دورةَ فيه، وهذا ما يجعل العمقَ
     معرَّفاً أصلاً).
   • **المخارجُ تُدفع إلى آخر عمود** مهما كان عمقُها، فتصطفّ النتائجُ
     في طرفٍ واحدٍ يقرؤه الطالب.
   • **الترتيبُ داخل العمود بمركز ثقل أسلافه** — العقدةُ تقف قبالة ما
     يغذّيها، وهو ما يقلّل تقاطعَ الأسلاك بلا خوارزميةِ تقاطعاتٍ كاملة.
     ثم مرّةٌ ثانيةٌ من اليمين إلى اليسار لتستقرّ المداخلُ قبالة أحفادها.
   • كلُّ المواضع على شبكة الوضع، وإلا استقرّت العناصرُ بين الخطوط.

   نتيجتُها **أمرُ `node.move-many` واحد** ⇒ تراجعٌ واحدٌ يُلغي التوزيع
   كلَّه. توزيعٌ لا يُتراجَع عنه عقوبةٌ على تجربته.
   ═══════════════════════════════════════════════════════════════ */

import { WORKSPACE_LIMITS, type CircuitDocumentV1, type WorkspacePointV1 } from '../domain/workspace.ts';
import { geometryForComponent } from './symbol-geometry.ts';

export interface AutoLayoutOptions {
  readonly grid: number;
  readonly columnGap: number;
  readonly rowGap: number;
  readonly origin: WorkspacePointV1;
}

export const DEFAULT_AUTO_LAYOUT: AutoLayoutOptions = {
  grid: 40,
  columnGap: 80,
  rowGap: 40,
  origin: { x: 40, y: 40 }
};

function snap(value: number, grid: number): number {
  return Math.round(value / grid) * grid;
}

/** عمقُ كل عقدة: أطولُ مسارٍ من أي مدخل. يُحسب بترتيبٍ طوبولوجيّ. */
function depthByNodeId(document_: CircuitDocumentV1): Map<string, number> {
  const incoming = new Map<string, string[]>();
  const outgoing = new Map<string, string[]>();
  for (const node of document_.nodes) { incoming.set(node.id, []); outgoing.set(node.id, []); }
  for (const wire of document_.wires) {
    if (!incoming.has(wire.target.nodeId) || !outgoing.has(wire.source.nodeId)) continue;
    incoming.get(wire.target.nodeId)!.push(wire.source.nodeId);
    outgoing.get(wire.source.nodeId)!.push(wire.target.nodeId);
  }

  const depth = new Map<string, number>();
  const pending = new Map<string, number>();
  const queue: string[] = [];
  for (const node of document_.nodes) {
    const count = incoming.get(node.id)!.length;
    pending.set(node.id, count);
    if (count === 0) { depth.set(node.id, 0); queue.push(node.id); }
  }
  while (queue.length > 0) {
    const nodeId = queue.shift()!;
    for (const targetId of outgoing.get(nodeId) ?? []) {
      depth.set(targetId, Math.max(depth.get(targetId) ?? 0, (depth.get(nodeId) ?? 0) + 1));
      const remaining = (pending.get(targetId) ?? 1) - 1;
      pending.set(targetId, remaining);
      if (remaining === 0) queue.push(targetId);
    }
  }
  /* عقدةٌ لم تُزَر (بيانٌ ناقصٌ أو دورةٌ رفضها المُحقِّق قبلاً) تُلحق
     بعمقٍ صفرٍ بدل أن تختفي — لا عنصرَ يضيع من اللوحة. */
  for (const node of document_.nodes) if (!depth.has(node.id)) depth.set(node.id, 0);
  return depth;
}

export function computeAutoLayout(
  document_: CircuitDocumentV1,
  options: AutoLayoutOptions = DEFAULT_AUTO_LAYOUT
): Readonly<Record<string, WorkspacePointV1>> {
  if (document_.nodes.length === 0) return {};
  const depth = depthByNodeId(document_);
  const maximumDepth = Math.max(...depth.values());
  /* المخارجُ في العمود الأخير: نتائجُ الآلة تُقرأ في طرفٍ واحد. */
  const columnOf = new Map<string, number>();
  for (const node of document_.nodes) {
    columnOf.set(node.id, node.role === 'output' ? maximumDepth : depth.get(node.id)!);
  }
  const lastColumn = Math.max(...columnOf.values());

  const columns: string[][] = Array.from({ length: lastColumn + 1 }, () => []);
  for (const node of document_.nodes) columns[columnOf.get(node.id)!]!.push(node.id);

  const sourcesOf = new Map<string, string[]>();
  const targetsOf = new Map<string, string[]>();
  for (const node of document_.nodes) { sourcesOf.set(node.id, []); targetsOf.set(node.id, []); }
  for (const wire of document_.wires) {
    sourcesOf.get(wire.target.nodeId)?.push(wire.source.nodeId);
    targetsOf.get(wire.source.nodeId)?.push(wire.target.nodeId);
  }

  /* ترتيبٌ ابتدائيٌّ ثابت (بالمعرّف) فلا يقفز الرسمُ بين تشغيلين. */
  for (const column of columns) column.sort((left, right) => left.localeCompare(right));
  const orderOf = new Map<string, number>();
  const applyOrder = () => {
    for (const column of columns) column.forEach((nodeId, index) => orderOf.set(nodeId, index));
  };
  applyOrder();

  const barycenter = (nodeId: string, neighbours: ReadonlyMap<string, string[]>): number => {
    const list = (neighbours.get(nodeId) ?? []).map(id => orderOf.get(id)).filter((v): v is number => v !== undefined);
    return list.length === 0 ? orderOf.get(nodeId)! : list.reduce((sum, value) => sum + value, 0) / list.length;
  };
  for (let columnIndex = 1; columnIndex <= lastColumn; columnIndex += 1) {
    columns[columnIndex]!.sort((left, right) => barycenter(left, sourcesOf) - barycenter(right, sourcesOf));
    applyOrder();
  }
  for (let columnIndex = lastColumn - 1; columnIndex >= 0; columnIndex -= 1) {
    columns[columnIndex]!.sort((left, right) => barycenter(left, targetsOf) - barycenter(right, targetsOf));
    applyOrder();
  }

  const widthOf = (nodeId: string): number => {
    const node = document_.nodes.find(candidate => candidate.id === nodeId)!;
    return geometryForComponent(node.component, node.inputCount).width;
  };
  const heightOf = (nodeId: string): number => {
    const node = document_.nodes.find(candidate => candidate.id === nodeId)!;
    return geometryForComponent(node.component, node.inputCount).height;
  };

  const columnX: number[] = [];
  let cursorX = options.origin.x;
  for (const column of columns) {
    columnX.push(snap(cursorX, options.grid));
    const widest = column.length === 0 ? 0 : Math.max(...column.map(widthOf));
    cursorX += widest + options.columnGap;
  }

  /* توسيطُ كل عمودٍ رأسياً حول أطول عمود: رسمٌ متّزنٌ لا معلَّقٌ من أعلى. */
  const columnHeights = columns.map(column =>
    column.reduce((total, nodeId) => total + heightOf(nodeId) + options.rowGap, -options.rowGap));
  const tallest = Math.max(0, ...columnHeights);

  const positions: Record<string, WorkspacePointV1> = {};
  for (const [columnIndex, column] of columns.entries()) {
    let cursorY = options.origin.y + Math.max(0, (tallest - columnHeights[columnIndex]!) / 2);
    for (const nodeId of column) {
      positions[nodeId] = {
        x: Math.min(columnX[columnIndex]!, WORKSPACE_LIMITS.width - widthOf(nodeId)),
        y: Math.min(snap(cursorY, options.grid), WORKSPACE_LIMITS.height - heightOf(nodeId))
      };
      cursorY += heightOf(nodeId) + options.rowGap;
    }
  }
  return positions;
}
