import type { LogicBit, WorkspaceArtifactV1 } from '../domain/workspace.ts';
import { evaluateWorkspace, type EvaluationIssue } from './evaluate.ts';
import type { GraphIssue } from './graph.ts';
import { deriveSignalCone, type SignalCone } from './signal-cone.ts';
import type { LogicValue } from './logic.ts';

export interface TruthRow {
  readonly index: number;
  readonly inputs: Readonly<Record<string, LogicBit>>;
  readonly outputs: Readonly<Record<string, LogicValue>>;
}

export interface TruthTable {
  readonly inputNodeIds: readonly string[];
  readonly outputNodeIds: readonly string[];
  readonly rows: readonly TruthRow[];
  readonly graphIssues: readonly GraphIssue[];
  readonly evaluationIssues: readonly EvaluationIssue[];
}

export interface ExpectedTruthRow {
  readonly inputs: Readonly<Record<string, LogicBit>>;
  readonly outputs: Readonly<Record<string, LogicBit>>;
}

export interface TruthCounterexample {
  readonly rowIndex: number;
  readonly inputs: Readonly<Record<string, LogicBit>>;
  readonly outputNodeId: string;
  readonly expected: LogicBit;
  readonly actual: LogicValue;
  readonly signalCone: SignalCone;
}

function variableInputIds(artifact: WorkspaceArtifactV1): string[] {
  return artifact.circuit.nodes
    .filter(node => node.role === 'input' && (node.component === 'SWITCH' || node.component === 'BUTTON'))
    .map(node => node.id)
    .sort((left, right) => left.localeCompare(right));
}

function outputIds(artifact: WorkspaceArtifactV1): string[] {
  return artifact.circuit.nodes
    .filter(node => node.role === 'output')
    .map(node => node.id)
    .sort((left, right) => left.localeCompare(right));
}

export function assignmentForRow(inputNodeIds: readonly string[], rowIndex: number): Readonly<Record<string, LogicBit>> {
  return Object.fromEntries(inputNodeIds.map((nodeId, inputIndex) => {
    const bitPosition = inputNodeIds.length - inputIndex - 1;
    return [nodeId, ((rowIndex >> bitPosition) & 1) as LogicBit];
  }));
}

export function deriveTruthTable(artifact: WorkspaceArtifactV1): TruthTable {
  const inputNodeIds = variableInputIds(artifact);
  const outputNodeIds = outputIds(artifact);
  const rowCount = 2 ** inputNodeIds.length;
  const rows: TruthRow[] = [];
  const graphIssues: GraphIssue[] = [];
  const evaluationIssues: EvaluationIssue[] = [];
  for (let rowIndex = 0; rowIndex < rowCount; rowIndex += 1) {
    const inputs = assignmentForRow(inputNodeIds, rowIndex);
    const evaluation = evaluateWorkspace(artifact, inputs);
    if (rowIndex === 0) graphIssues.push(...evaluation.graphIssues);
    evaluationIssues.push(...evaluation.evaluationIssues);
    rows.push({
      index: rowIndex,
      inputs,
      outputs: Object.fromEntries(outputNodeIds.map(nodeId => [nodeId, evaluation.values[nodeId] ?? 'X']))
    });
  }
  return { inputNodeIds, outputNodeIds, rows, graphIssues, evaluationIssues };
}

export function firstTruthCounterexample(
  artifact: WorkspaceArtifactV1,
  expectedRows: readonly ExpectedTruthRow[]
): TruthCounterexample | null {
  const table = deriveTruthTable(artifact);
  for (let rowIndex = 0; rowIndex < Math.min(table.rows.length, expectedRows.length); rowIndex += 1) {
    const actualRow = table.rows[rowIndex];
    const expectedRow = expectedRows[rowIndex];
    for (const outputNodeId of table.outputNodeIds) {
      const expected = expectedRow.outputs[outputNodeId];
      if (expected === undefined) continue;
      const actual = actualRow.outputs[outputNodeId] ?? 'X';
      if (actual !== expected) {
        return {
          rowIndex,
          inputs: actualRow.inputs,
          outputNodeId,
          expected,
          actual,
          signalCone: deriveSignalCone(artifact, outputNodeId)
        };
      }
    }
  }
  return null;
}
