import type { WorkspaceArtifactV1, WorkspaceWireV1 } from '../domain/workspace.ts';

export type GraphIssueCode = 'DUPLICATE_NODE_ID' | 'UNKNOWN_WIRE_SOURCE' | 'UNKNOWN_WIRE_TARGET' | 'COMBINATIONAL_CYCLE';

export interface GraphIssue {
  readonly code: GraphIssueCode;
  readonly nodeIds: readonly string[];
  readonly wireId?: string;
}

export interface GraphPlan {
  readonly orderedNodeIds: readonly string[];
  readonly cycleNodeIds: readonly string[];
  readonly incomingWires: ReadonlyMap<string, readonly WorkspaceWireV1[]>;
  readonly issues: readonly GraphIssue[];
}

function insertSorted(values: string[], value: string): void {
  const insertionIndex = values.findIndex(candidate => candidate.localeCompare(value) > 0);
  if (insertionIndex === -1) values.push(value);
  else values.splice(insertionIndex, 0, value);
}

export function createGraphPlan(artifact: WorkspaceArtifactV1): GraphPlan {
  const issues: GraphIssue[] = [];
  const nodeIds = artifact.circuit.nodes.map(node => node.id);
  const uniqueNodeIds = [...new Set(nodeIds)].sort((left, right) => left.localeCompare(right));
  if (uniqueNodeIds.length !== nodeIds.length) {
    const duplicateIds = uniqueNodeIds.filter(nodeId => nodeIds.filter(candidate => candidate === nodeId).length > 1);
    issues.push({ code: 'DUPLICATE_NODE_ID', nodeIds: duplicateIds });
  }

  const nodeIdSet = new Set(uniqueNodeIds);
  const outgoing = new Map<string, string[]>();
  const incomingWires = new Map<string, WorkspaceWireV1[]>();
  const indegree = new Map(uniqueNodeIds.map(nodeId => [nodeId, 0]));
  for (const nodeId of uniqueNodeIds) {
    outgoing.set(nodeId, []);
    incomingWires.set(nodeId, []);
  }

  const orderedWires = [...artifact.circuit.wires].sort((left, right) => left.id.localeCompare(right.id));
  for (const wire of orderedWires) {
    const sourceExists = nodeIdSet.has(wire.source.nodeId);
    const targetExists = nodeIdSet.has(wire.target.nodeId);
    if (!sourceExists) issues.push({ code: 'UNKNOWN_WIRE_SOURCE', nodeIds: [wire.source.nodeId], wireId: wire.id });
    if (!targetExists) issues.push({ code: 'UNKNOWN_WIRE_TARGET', nodeIds: [wire.target.nodeId], wireId: wire.id });
    if (!sourceExists || !targetExists) continue;
    outgoing.get(wire.source.nodeId)?.push(wire.target.nodeId);
    incomingWires.get(wire.target.nodeId)?.push(wire);
    indegree.set(wire.target.nodeId, (indegree.get(wire.target.nodeId) ?? 0) + 1);
  }

  const available = uniqueNodeIds.filter(nodeId => indegree.get(nodeId) === 0);
  const orderedNodeIds: string[] = [];
  while (available.length > 0) {
    const nodeId = available.shift();
    if (!nodeId) break;
    orderedNodeIds.push(nodeId);
    const targets = [...(outgoing.get(nodeId) ?? [])].sort((left, right) => left.localeCompare(right));
    for (const targetNodeId of targets) {
      const nextIndegree = (indegree.get(targetNodeId) ?? 0) - 1;
      indegree.set(targetNodeId, nextIndegree);
      if (nextIndegree === 0) insertSorted(available, targetNodeId);
    }
  }

  const orderedSet = new Set(orderedNodeIds);
  const cycleNodeIds = uniqueNodeIds.filter(nodeId => !orderedSet.has(nodeId));
  if (cycleNodeIds.length > 0) issues.push({ code: 'COMBINATIONAL_CYCLE', nodeIds: cycleNodeIds });
  return { orderedNodeIds, cycleNodeIds, incomingWires, issues };
}
