import type { ComponentKind } from '../../domain/workspace.ts';

export type ComponentCategory = 'essentials' | 'gates' | 'combinational';
export interface ComponentDefinition { readonly kind: ComponentKind; readonly category: ComponentCategory; readonly inputCount: number; readonly keywords: readonly string[] }

export const COMPONENT_LIBRARY: readonly ComponentDefinition[] = [
  { kind: 'SWITCH', category: 'essentials', inputCount: 0, keywords: ['input', 'switch'] },
  { kind: 'BUTTON', category: 'essentials', inputCount: 0, keywords: ['input', 'momentary', 'button'] },
  { kind: 'CONSTANT_0', category: 'essentials', inputCount: 0, keywords: ['constant', 'zero', '0'] },
  { kind: 'CONSTANT_1', category: 'essentials', inputCount: 0, keywords: ['constant', 'one', '1'] },
  { kind: 'PROBE', category: 'essentials', inputCount: 1, keywords: ['output', 'probe'] },
  { kind: 'LED', category: 'essentials', inputCount: 1, keywords: ['output', 'light'] },
  { kind: 'BUFFER', category: 'gates', inputCount: 1, keywords: ['buffer', 'gate'] },
  { kind: 'NOT', category: 'gates', inputCount: 1, keywords: ['not', 'invert', 'gate'] },
  { kind: 'AND', category: 'gates', inputCount: 2, keywords: ['and', 'gate'] },
  { kind: 'NAND', category: 'gates', inputCount: 2, keywords: ['nand', 'gate'] },
  { kind: 'OR', category: 'gates', inputCount: 2, keywords: ['or', 'gate'] },
  { kind: 'NOR', category: 'gates', inputCount: 2, keywords: ['nor', 'gate'] },
  { kind: 'XOR', category: 'gates', inputCount: 2, keywords: ['xor', 'exclusive', 'gate'] },
  { kind: 'XNOR', category: 'gates', inputCount: 2, keywords: ['xnor', 'equivalence', 'gate'] },
  { kind: 'MUX', category: 'combinational', inputCount: 3, keywords: ['mux', 'multiplexer', 'selector'] },
  { kind: 'MAJORITY', category: 'combinational', inputCount: 3, keywords: ['majority', 'voter'] },
  { kind: 'ODD_PARITY', category: 'combinational', inputCount: 4, keywords: ['odd', 'parity'] },
  { kind: 'EVEN_PARITY', category: 'combinational', inputCount: 4, keywords: ['even', 'parity'] }
] as const;

/**
 * عددُ مداخل العنصر عند وضعه. مصدرُه **هذا الجدولُ وحدَه** — نسخةٌ ثانيةٌ
 * منه في طبقة الرسم كانت ستُنتج عناصرَ يرفضها المُحقِّق بـ`INVALID_ARITY`
 * فور وضعها، وهو خطأٌ يظهر للطالب لا للمبرمج.
 */
export function defaultInputCount(component: ComponentKind): number {
  return COMPONENT_LIBRARY.find(definition => definition.kind === component)?.inputCount ?? 2;
}

export function searchComponents(query: string, category?: ComponentCategory): readonly ComponentDefinition[] {
  const normalized = query.trim().toLocaleLowerCase('en');
  return COMPONENT_LIBRARY.filter(definition => (!category || definition.category === category) && (!normalized || [definition.kind, ...definition.keywords].some(term => term.toLocaleLowerCase('en').includes(normalized))));
}
