/* ═══════════════════════════════════════════════════════════════
   main.ts — نقطةُ دخول مختبر الدوائر التوافقية
   ═══════════════════════════════════════════════════════════════
   يقرأ المثالَ من الرابط (`?preset=full-adder`) واللغةَ من إعدادات
   الحديقة، ثم يركّب الواجهة. المثالُ من الرابط هو ما يجعل **محرّكاً
   واحداً يخدم أمثلةً كثيرة** بدل صفحةٍ لكل مثال.

   الاستعادةُ **قبل** التركيب لا بعده: تركيبُ المثال ثم استبدالُه بعملٍ
   محفوظٍ يُري الطالبَ وميضَ دائرةٍ ليست دائرتَه.
   ═══════════════════════════════════════════════════════════════ */

import './app/lab.css';
import { LabView, restoreArtifact } from './app/lab-view.ts';
import type { LabLocale } from './app/messages.ts';
import type { WorkspaceArtifactV1 } from './domain/workspace.ts';
import { decodeShareEnvelope } from './persistence/share-codec.ts';

function currentLocale(): LabLocale {
  try {
    return localStorage.getItem('garden_lang') === 'en' ? 'en' : 'ar';
  } catch {
    /* التخزينُ قد يكون محجوباً (وضعُ التصفّح الخاص) — العربيةُ الافتراض. */
    return 'ar';
  }
}

/**
 * الدائرةُ المشارَكة تُقرأ من **شذرة** الرابط لا من استعلامه: الشذرةُ لا
 * تُرسل إلى الخادم في HTTP أصلاً، فلا يمرّ عملُ الطالب بسجلٍّ ولا وسيط.
 * وتُقرأ مرّةً واحدةً عند التحميل ثم **تُمحى الشذرة** فلا يعيدها تحديثُ
 * الصفحة فوق ما بناه من فتحها.
 */
async function sharedArtifactFromHash(): Promise<WorkspaceArtifactV1 | null> {
  const hash = location.hash.replace(/^#/, '');
  if (!hash.startsWith('circuit=')) return null;
  const decoded = await decodeShareEnvelope(hash, () => `artifact:shared.${Date.now().toString(36)}`);
  history.replaceState(null, '', `${location.pathname}${location.search}`);
  return decoded.ok ? decoded.artifact : null;
}

async function mount(): Promise<void> {
  const host = document.querySelector<HTMLElement>('[data-lab-root]');
  if (!host) return;

  const presetId = new URLSearchParams(location.search).get('preset');
  /* 🔴 **الدائرةُ المشارَكة تتقدّم على كل شيء**: من فتح رابطاً شُورك به
     جاء ليرى تلك الدائرة، فعرضُ مثالٍ أو عملٍ محفوظٍ مكانَها يجعل
     الرابطَ يبدو مكسوراً. وتُحمَّل **نسخةً بهويّةٍ جديدة** فلا تكتب على
     عمل من فتحها. */
  const shared = await sharedArtifactFromHash();
  /* ومثالٌ صريحٌ في الرابط يتقدّم على المحفوظ: الرابطُ نيّةٌ قالها الدرسُ
     الآن، والمحفوظُ نيّةٌ قديمة. */
  const restored = shared || presetId ? null : await restoreArtifact();
  const view = new LabView(presetId, currentLocale(), restored ?? undefined);
  host.replaceChildren(view.element);
  /* بعد التركيب لا قبله: التركيبُ يبني الشريطَ واللوحةَ ثم تُستبدل
     الوثيقةُ فيهما دفعةً واحدة. */
  if (shared) view.adoptSharedArtifact(shared);

  /* ⚠️ الحدثُ يُبثّ على `document` لا `window` — والخطأُ فيه صامتٌ
     تماماً: النصوصُ الساكنة تتبدّل بـ`garden.js` وما رسمناه بـJS لا
     يتبدّل، فيبدو نقصَ ترجمةٍ لا حدثاً ميتاً. */
  document.addEventListener('garden:languageChanged', () => view.setLocale(currentLocale()));
}

if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => void mount());
else void mount();
